quests[12894] = { id = 12894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lager der Kreuzfahrer", description = "Kreuzfahrer Dargath, Kreuzfahrer MacKellar, Ingenieur Schilf und die Zwillinge Gerk und Burr wurden vor Tagen zum Todesfeld entsandt, um dort eine neue Front zu eröffnen. Dem letzten Briefwechsel zufolge, hatten sie an der Grenze zu den Todesfeldern nordwestlich von hier erfolgreich ein Lager errichtet.\n\nAngesichts dieser neuen Informationen über Drakuru und Prinz Navarius denke ich, dass es nur klug wäre, jemanden schnellstens zum Lager der Kreuzfahrer zu entsenden.\n\nPackt Eure Sachen, {name}. Ihr müsst sofort los!", sourceObjective = "Sucht Kreuzfahrer MacKellar im Lager der Kreuzfahrer in Zul'Drak auf.", completion = "Es lief alles gut, bis die Geißel angriff. Sie haben sich mit Dargath, Gerk und Burr davongemacht und haben darüber hinaus auch unser Beförderungsmittel zerstört. Ratet mal, wer den Angriff angeführt hat.\n\n<MacKellar nickt.>\n\nNavarius...\n\nScheint, als wäre die ganze Gegend hier eine Art Werkstatt, in der Diener der Geißel hergestellt werden. Wir stehen mitten in einem verdammten untoten Minenfeld!", sourceObjectiveStatus = "unverified-source-field" }
quests[12895] = { id = 12895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verschwundene Bronzebart", description = "Vor unserem Aufbruch erhielt ich die Akte, die Späher Vor'takh über diesen Brann Bronzebart angelegt hat. Seinen Tagebucheintragungen und Funden an den Grizzlyhügeln zufolge besteht kein Zweifel, dass Brann zu den Sturmgipfeln aufgebrochen ist. Bevor wir abstürzten sah ich noch kurz eine Lagerstätte. Sie liegt südlich von hier, jenseits der Fußmarschen, oberhalb des gefrorenen Flusses namens Bors Atemstrom. \n\nWenn Brann nicht dort ist, dann durchsucht das Lager und die Umgebung nach Hinweisen darauf, wohin dieser verflixte Zwerg aufgebrochen ist. Bringt mir alles, was Ihr dort findet.", sourceObjective = "Holt die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Boktar Blutfurie an der Absturzstelle Grom'ash.", progress = "Habt Ihr Bronzebarts Lager schon finden können?", completion = "Bei unserem Glück hätte ich das vermutlich vorhersehen müssen. Aber so leicht wird er mir nicht davonkommen. Ich bin gespannt, was in der Nachricht steht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12896] = { id = 12896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man ihn nicht überzeugen kann", description = "Todesritter wie General Lichtbann werden an der kurzen Leine gehalten und können nur unter höchst außergewöhnlichen Umständen dazu gebracht werden, sich gegen den Lichkönig zu stellen.\n\nDer General hält sich ausschließlich im Gewölbe auf und überwacht die Erschaffung neuer Waffen. Wagt Euch an eines seiner Waffenregale in der Nordschmiede und er wird auftauchen, das versichere ich Euch. Ich werde Euch Ekel, Lady Nachtwald und den Springer zur Unterstützung schicken.\n\nWenn wir das Schattengewölbe endlich erobern wollen, muss General Lichtbann fallen!", sourceObjective = "Besiegt General Lichtbann und informiert anschließend Thassarian an Bord der Himmelsbrecher über Euren Erfolg.", completion = "General Lichtbann und seine Streitkräfte wurde besiegt? Das Schattengewölbe ist erobert?", sourceObjectiveStatus = "unverified-source-field" }
quests[12897] = { id = 12897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn man ihn nicht überzeugen kann", description = "Todesritter wie General Lichtbann werden an einer zu kurzen Leine gehalten, als dass wir sie vom Willen des Lichkönigs loslösen könnten... außer unter außergewöhnlichen Umständen.\n\nDer General hält sich innerhalb des Gewölbes auf und beaufsichtigt die Herstellung neuer Waffen. Sabotiert eines seiner Waffenregale an der nördlichen Schmiede und ich versichere Euch, er wird kommen. Ich werde Ekel, Lady Nachtwald und den Springer zu Eurer Unterstützung mitschicken.\n\nWenn wir das Schattengewölbe jemals erobern wollen, muss General Lichtbann fallen!", sourceObjective = "Besiegt General Lichtbann und berichtet dann Koltira Todesweber an Bord des Kanonenboots Orgrims Hammer von Eurem Erfolg.", completion = "General Lichtbann und seine Streitkräfte sind besiegt? Ist das Schattengewölbe eingenommen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12898] = { id = 12898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengewölbe", description = "Das klingt, als hättet Ihr Euch außerordentlich gut geschlagen. Außerdem konntet Ihr dabei drei wichtige Verbündete für die Ritter der Schwarzen Klinge gewinnen.\n\n<Thassarian lässt seinen Blick zum Horizont schweifen.>\n\nIhr solltet zurückgehen. Inzwischen werden Baron Splitter und die anderen Todesritter erbittert kämpfen, um das Schattengewölbe gegen die Macht der Geißel zu verteidigen.\n\nSie werden gewiss Eure Hilfe benötigen.", sourceObjective = "Meldet Euch bei Baron Splitter im Schattengewölbe.", completion = "Schön, dass Ihr zurück seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12899] = { id = 12899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schattengewölbe", description = "Anscheinend seid Ihr sehr erfolgreich gewesen. Zudem habt Ihr im gleichen Atemzug drei sehr wichtige Verbündete für die Ritter der Schwarzen Klinge gewonnen.\n\n<Koltira blickt hinab auf die Karte am Boden.>\n\nIhr solltet zurückgehen. Mittlerweile werden Baron Splitter und die anderen Todesritter bestimmt bis zum letzten Blutstropfen darum kämpfen, das Schattengwölbe gegen den Ansturm der Geißel zu verteidigen.\n\nIch bin mir sicher, dass sie Eure Hilfe gebrauchen könnten.", sourceObjective = "Meldet Euch bei Baron Splitter im Schattengewölbe zurück.", completion = "Gut, dass Ihr zurückgekehrt seid. Wie Ihr sehen könnt, haben wir hier alle Hände voll zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[12900] = { id = 12900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschirr anfertigen", description = "Ihr wollt also reiten? Wenn Ihr es so weit geschafft habt, dann habt Ihr wohl auch einen Versuch bei den Hildarthings verdient.\n\nAber eins nach dem anderen. Zuerst müssen wir Euch ein Geschirr anfertigen.\n\nIn den Klippen im Süden streifen vereinzelte Yetigruppen herum. Ihre Haut ist zäh und hat genau die richtige Dicke. Bringt mir einige, dann können wir dafür sorgen, dass Ihr Euch auf den Weg des Bärenreiters begebt.", sourceObjective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr 3 Bälge von Eismähnenyetis besorgt.", progress = "Habt Ihr die Bälge schon gefunden? Die Yetis streifen in den Hügeln unter uns herum.", completion = "Die sollten genügen. Ich werde das Geschirr für Euch bald fertig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12901] = { id = 12901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aus nichts etwas herstellen", description = "Prinz Navarius muss gestoppt werden. Wir können nicht zulassen, dass die Geißel diese Gegend weiterhin als Werkstatt zur Zombieherstellung verwendet. Wenn wir den Panzer zum Laufen bekommen, dann könnten wir womöglich eine Chance haben. Was ich jetzt brauche, sind Ersatzteile.\n\nNordwestlich von hier befindet sich eine Gegend namens Thryms Ende. Die Armeen der Geißel benutzen diese Gegend als eine Art Basis. Über dieser Basis verteilt sind die Trümmer, die sie bei ihrer Ankunft hinterlassen haben. Überall liegt vereinzelter Metallschrott der Geißel herum. Beschafft Euch das Zeug und ich werde versuchen, es sinnvoll einzusetzen.", sourceObjective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr 10 Stück Metallschrott der Geißel beschafft.", progress = "Ich weiß wirklich nicht, ob dieser Plan funktionieren wird, {name}. Bringt mir einfach den Metallschrott und ich werde tun, was ich kann.", completion = "Was ist das für ein Schrott! Ah, verdammt! Es ist zu nichts zu gebrauchen. Das Metall der Geißel ist also nicht die Lösung. Was machen wir nur?", sourceObjectiveStatus = "unverified-source-field" }
quests[12902] = { id = 12902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Antworten", description = "Diese armen Kreaturen sind die einzigen Überlebenden.\n\nLaut dem, was ihr Häuptling sagt, seien Drakkaritrolle und Zornklauen jahrtausendelang Verbündete gewesen. Sie hätten hier über Generationen hinweg neben den Trollen gelebt und den Wandel der Welt um sie herum nicht bemerkt. Für die Zornklauen ist ein Troll ein Troll, also kam der Trollangriff auf ihren Bau überraschend.\n\nWir benötigen ein paar Antworten, {name}. Durchkämmt ihr Dorf südöstlich von hier nach Hinweisen darüber, wer oder was für diese Angriffe verantwortlich ist.", sourceObjective = "Durchsucht den Zornklauenbau nach Hinweisen darüber, wer oder was die Angriffe gegen die Wolvar der Zornklauen eingeleitet hat.", completion = "Da schwebt eine Schriftrolle über dem seltsamen Altar. Das muss genau das sein, wonach Kreuzfahrerlord Lantinga sucht!", sourceObjectiveStatus = "unverified-source-field" }
quests[12903] = { id = 12903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dafür sind Freunde da...", description = "Wir wurden von Prinz Navarius und mindestens einem Dutzend Diener der Geißel angegriffen. Ich sagte zu Dargath und den Zwillingen, dass sie im Panzer bleiben sollen, doch sie wollten nicht auf mich hören. Dargath sah mir in die Augen und sagte: \"Wenn niemand diesen Panzer verlässt, dann werden sie uns alle umbringen.\" Anschließend ließ er Schilf den Motor abstellen und griff an. Das Heldenhafteste, was ich jemals gesehen habe.\n\nIch hörte, wie der Prinz den Monstern Befehle zubrüllte. Hat sich angehört, als würde er sie in nordwestliche Richtung nach Thryms Ende schicken. Wir müssen unsere Freunde retten. Werdet Ihr nach ihnen suchen?", sourceObjective = "Kreuzfahrer MacKellar im Lager der Kreuzfahrer möchte, dass Ihr nach Kreuzfahrer Dargath, Gerk und Burr sucht.", completion = "Die drei haben ein großes Opfer gebracht, das man so bald nicht vergessen wird. Ihr Dahinscheiden wird nicht umsonst gewesen sein. Wir werden siegreich sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[12904] = { id = 12904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Licht verwehrt mir meine Rache", description = "Sie... sie haben meinen Bruder getötet.\n\n<Gerk kämpft gegen die Tränen an.>\n\nHaben ihn wie ein Tier abgeschlachtet. Nun liegt er auf einem ihrer Tische auf der anderen Seite des Lagers - bereit für ihre grauenhaften Experimente. Dargath ist auch tot. Der Paladin hat bei den Ruinen gen Nordosten eine echte Heldentat vollbracht, doch der Anführer der Vargul, Algar, war zu stark.\n\nIch bin als einziger übrig und werde auch bald tot sein. Ich... ich verwandle mich.\n\nWenn mir das Licht meine Rache verwehrt, werdet Ihr, {class}, sie mir dann gewähren? Tötet sie alle.", sourceObjective = "Gerk in Thryms Ende in Zul'Drak möchte, dass Ihr 15 Vargul tötet.", progress = "Ihr tut der Welt einen Gefallen, {class}. Diese Monster müssen aufgehalten werden!", completion = "<Gerk liegt im Sterben.>\n\nS... Sie sagen, dass diese Vargul... diejenigen sind... die der Lichkönig als unwürdig erachtete. Kön... könnt Ihr Euch... das vorstellen? Den... Denkt nur einmal daran... wie mächtig... diejenigen sein müssen, die... würdig sind...\n\nIch werde für Euch beten, Held... im Jenseits... Möget Ihr nie mehreren von ihnen begegnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12905] = { id = 12905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mildred die Grausame", description = "Abgemacht, {name}. Ihr helft mir, mich von diesen Ketten zu befreien, und ich helfe Euch, Euren kleinen grünen Freund zu finden.\n\nDie Hyldnir, die diese Mine leitet, wird Mildred die Grausame genannt und das aus gutem Grund.\n\nSagt ihr, dass Ihr geschickt wurdet, um bei der Arbeit in den Minen zu helfen. Tut, was auch immer sie von Euch verlangt, bis sie Euch die Schlüssel für meine Ketten anvertraut.", sourceObjective = "Sprecht mit Mildred der Grausamen in der Verlassenen Mine.", completion = "Ich habe auf Ersatz für einen meiner Aufseher gewartet. Wurde langsam Zeit, dass du auftauchst.\n\nNa, dann schicken wir dich mal an die Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[12906] = { id = 12906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disziplin", description = "Dann wollen wir Euch für den Anfang mal etwas Leichtes geben. Die Vrykulmänner, die für uns in den Minen schuften, tun dies gegen ihren Willen... und lediglich aus Furcht vor unseren Klingen.\n\nHin und wieder verliert einer von ihnen seine Motivation. Haltet nach denjenigen Ausschau, die nicht kooperieren wollen, und weist sie in ihre Schranken.\n\nHier, nehmt diese Disziplinarrute - Ihr wollt Schmerzen zufügen und niemanden totschlagen. Nun ja, die meiste Zeit zumindest.", sourceObjective = "Mildred die Grausame an der Verlassenen Mine möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul anwendet.", progress = "Bist du fertig? Hoffe, du hast nicht zu viele von diesen Mistkerlen totgeschlagen. Wir brauchen die Arbeitskräfte.", completion = "Für eine neue Aufseherin nicht schlecht. Ich hab' noch eine andere Aufgabe, falls du dich heute mutig fühlst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12907] = { id = 12907, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Exempel statuieren", description = "Auf jede Aktion folgt eine Gegenreaktion, Schwester. In unserem Fall sieht es wie folgt aus: Wir üben Druck auf die Männer aus und als Folge wurden neue Gerüchte über einen Aufstand laut.\n\nDas bärtige Schwein hinter diesen Hetzreden wird Garhal genannt. Schafft ihn beiseite... und sorgt dafür, dass die anderen Männer sein Ableben mitverfolgen. Sie müssen lernen, dass Ungehorsam nicht toleriert wird.", sourceObjective = "Mildred die Grausame in der Verlassenen Mine möchte, dass Ihr Garhal tötet.", completion = "Wenn ich am Anfang Bedenken bezüglich Eures Engagements hatte, dann sind diese nunmehr verflogen. Noch ein klein wenig mehr Mühe von Eurer Seite her und Ihr könntet zu einem permanenten Mitglied meiner Operation werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12908] = { id = 12908, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bestimmte Gefangene", description = "Ihr seid gnadenlos und habt Euch in dieser Gegend bewährt.\n\nIch habe eine weitere Aufgabe für Euch. Eine der gefangenen Vrykul ist zu einer größeren Belastung geworden, als vorauszusehen war.\n\nSie besaß die Frechheit, auf ihr Recht zu pochen, am Hildarthing, unserem heiligen Wettstreit der Stärke und Kampfkünste, teilnehmen zu dürfen.\n\nHier ist der Schlüssel zu ihren Fesseln. Aber macht es so schmerzlos wie möglich, denn sie ist immerhin eine Frau, wenn auch keine von uns.", sourceObjective = "Bringt Mildreds Schlüssel zu Lok'lira der Greisin in die Verlassene Mine.", progress = "Wurde auch langsam Zeit.", completion = "Ich wusste, dass Ihr zurückkommt! Befreit mich von diesen Fesseln, dann helfe ich Euch, den Goblin zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12909] = { id = 12909, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nase trauen", description = "Um Brann aufzuspüren, brauchen wir eine Kreatur mit präzisem Geruchssinn, die gut Spuren lesen kann. Zwar waren im Zeppelin keine Hunde, aber ich glaube, ich habe einen Ersatz gefunden.\n\nNach dem Absturz schickte ich Khaliisi den Osthang des Berges hinab, um zu jagen. Ihre Katze Frostbeißer kann im Schnee hervorragend Beute machen. Sagt ihr, dass sie sich vorerst von ihrer Gefährtin trennen muss. Sie kann allein jagen, aber wir haben keine andere Möglichkeit, Brann Bronzebart zu finden.", sourceObjective = "Sprecht mit Khaliisi am Fuße des Berges östlich der Absturzstelle Grom'ash.", completion = "Boktar hat Frostbeißer also eine andere Aufgabe zugedacht, was? Nun, ich hoffe wirklich für ihn, dass die Sache wichtig ist. Er weiß, dass man einen Jäger normalerweise nicht von seinem Gefährten trennt!", sourceObjectiveStatus = "unverified-source-field" }
quests[12910] = { id = 12910, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Täter ausschnüffeln", description = "Dieses Mal werde ich Boktar seinen Willen lassen, doch ich erwarte von ihm, dass er es auch wieder gut macht. Seht mich nicht so an. Boktar mag vielleicht das Kommando haben, doch niemand sagt einem Jäger, was er zu tun hat.\n\n'Dein Begleiter muss verschwinden,' sagt er. 'Mach, dass er zu Knurren aufhört.'\n\nUnd ganz plötzlich ändert er seine Meinung, so wie es ihm gerade in den Kram passt. Dann wieder beschwert er sich darüber, dass Frostbeißer ihn ein wenig gebissen haben soll. Doch keine Sorge, er wird Euch ausgezeichnete Dienste leisten und Eure Beute aufspüren. Nachdem er sein Ziel gefunden hat, liegt es an Euch, mit den Eisenzwergen, Brann oder wem auch immer Ihr finden mögt fertigzuwerden.", sourceObjective = "Schwingt Euch auf Frostbeißer und folgt der Fährte von Branns Notiz bis zu ihrem Ausgangspunkt. Beschafft anschließend Branns Kommunikator und stellt mit seiner Hilfe Kontakt mit Brann Bronzebart her.", progress = "Wer... wer seid Ihr?", completion = "<Ihr aktiviert den Kommunikator und das Bild eines Zwergen erscheint. Es kann sich nur um Brann Bronzebart handeln.>\n\n<Seinem Gesichtsausdruck nach zu urteilen, scheint Brann erschrocken darüber zu sein, Euch zu sehen, und fängt an, wie wild zu gestikulieren.>", sourceObjectiveStatus = "unverified-source-field" }
quests[12911] = { id = 12911, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Credit Test" }
quests[12912] = { id = 12912, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großer Sturm rückt an", description = "Ihr seid nicht wie die anderen, <mein Kleiner/meine Kleine>. Ihr stinkt nicht nach uraltem Tod. Womöglich kann man Euch vertrauen.\n\nIch bin Gymer, König der Sturmriesen. Ich wurde von meinem Bruder Thiassi, jetzt ein untoter Diener des Lichkönigs, hierher gelockt. Als ich erkannte, dass sein Hilferuf eine Falle ist, war es schon zu spät. Nun bin ich ein Gefangener der Geißel und ich fürchte, dass ich schon bald dasselbe Schicksal teilen werde, wie viele andere Sturmriesen.\n\nFindet einen Weg, mich aus diesem Käfig zu befreien, und ich werde Euch helfen, so gut ich kann.", sourceObjective = "Gymer, König der Sturmriesen, hat Euch gebeten, einen Weg zu finden, ihn aus seinem Käfig zu befreien. Sprecht mit Ingenieur Schilf im Lager der Kreuzfahrer.", completion = "Ein... ein Sturmriese? Ich weiß nicht so recht, {name}. Das hört sich riskant an. Auf der anderen Seite denke ich nicht, dass wir allzu viele Möglichkeiten haben.\n\nWenn ich das mache, dann müsst Ihr mir versprechen, dass Ihr Euren Freund dazu bringt, uns dabei zu helfen, mit Navarius und seinen Spießgesellen fertig zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12913] = { id = 12913, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprich Orcisch, Mann!", description = "<Brann fängt an, wie wild zu gestikulieren und in seiner Muttersprache zu faseln.>\n\nRuk MogOth red a mogoth ta eft Thros-garE Haldir.\n\nKha gor ruk khaz ta ke ruk hrim eft thros-am-kha ruk kost-um havar go kost.\n\nA modoss hine ruk bergum eft thros-am-kha ga eft Haldir ke loch Thon we lo gefrunon ta mitta.\n\nGar Ruk dagUm loch angor-magi ta har ruk!\n\n<Ein wenig später erkennt Ihr, dass das Gespräch zu nichts führt. Vielleicht wird der Schamane Moteha Windkind bei der Absturzstelle Grom'ash wissen, was zu tun ist.>", sourceObjective = "Sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", completion = "Boktar wird nicht erfreut darüber sein, dass Ihr Brann nicht gefunden habt, doch zumindest seid Ihr nicht mit leeren Händen zurückgekehrt. Nun lasst uns sehen, was wir wegen diesem plappernden Zwerg machen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12914] = { id = 12914, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gymers Rettung", description = "Ihr meint also, dass er in einen 30 Meter großen Käfig gesperrt ist, wie?\n\nWenn meine Berechnungen stimmen, dann sollten wir zumindest die Scharniere des Käfigs schwächen können, um dem Riesen genug Spielraum zum Ausbrechen zu geben.\n\nDamit das funktioniert, brauche ich ein paar Verflüssiger und Stabilisatoren.\n\nDie Essenz der Banshees sollte sich sehr gut als Verflüssiger eignen. Ihr könnt das Zeug von den Banshees in den Toten Feldern nordöstlich von hier bekommen. Die Stabilisatoren könnt Ihr von den Erdwütern im Südwesten nahe der Schwarzen Wacht bekommen.\n\nBewegt Euch!", sourceObjective = "Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr ihm 6 Essenzen der Banshees und 6 Einheiten Kieselerde bringt.", progress = "Ohne die Verflüssiger und Stabilisatoren werde ich nie den Sprengstoff herstellen können, den wir benötigen, um Euren Freund aus seinem Gefängnis zu befreien.", completion = "Glücklicherweise haben wir genug Sprengstoff gehabt. Die riesige Zephyriumladung herzustellen, sollte dank der Materialien, die Ihr mir gebracht habt, kein Problem mehr darstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12915] = { id = 12915, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zäune reparieren", description = "Wenn ich den Tempel der Schöpfer aus meines Bruders Kontrolle entreißen möchte, müssen die Dinge zwischen mir und meinen alten Verbündeten besser stehen.\n\nVielleicht wäre es ein erster Schritt zu einer neuen Freundschaft mit den Frostriesen, wenn wir zusammen einen gemeinsamen Feind vernichten würden.\n\nFjorn hat zur Belagerung von Dun Niffelem Eisenriesen eingesetzt. Er befindet sich bei Fjorns Amboss weit östlich von hier - geht dorthin und besiegt ihn. Schwächt seine Streitkräfte so weit, bis die Söhne Hodirs den Sieg davontragen.\n\nHier, {name}, nehmt diesen Glücksbringer und ruft mit ihm meine Irdenen zu Hilfe.", sourceObjective = "Thorim im Tempel der Stürme möchte, dass Ihr Fjorn und 5 Sturmgeschmiedete Eisenriesen in Fjorns Amboss östlich von Dun Niffelem tötet.\n\nMit Thorims Glücksbringer der Erde könnt Ihr seine Irdenen zur Unterstützung holen. Zum Benutzen des Glücksbringers benötigt Ihr einen Granitfelsen aus Fjorns Amboss in der Nähe.", completion = "Es ist also vollbracht.\n\nHoffen wir, dass es ausreicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12916] = { id = 12916, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unsere einzige Hoffnung", description = "Das, was ich Euch gleich geben werde, nennt sich Zephyrium. Die Substanz ist hochexplosiv und weist einige besondere Eigenschaften auf. Dank seiner Formbarkeit, werdet Ihr die Scharniere und Spalten füllen können und so maximalen Schaden anrichten.\n\nKehrt zu Eurem Freund zurück und benutzt die riesige Zephyriumladung, um ihn zu befreien.\n\nHoffen wir, dass er seinen Teil der Abmachung einhalten wird. Er ist unsere einzige Hoffnung.", sourceObjective = "Sprecht mit Gymer in Thryms Ende in Zul'Drak, nachdem Ihr mit der riesigen Zephyriumladung die Umzäunung der Geißel geöffnet habt, in welcher der Gefangene festgehalten wird.", progress = "Ich bin ein Riese meines Wortes, mein Kleiner.", completion = "FREIHEIT!\n\nHabt keine Angst, mein Kleiner. Gymer ist ein ehrenhafter Riese. Ich wünsche genauso wie Ihr und Euer Volk, dass die Geißel aus diesem Land vertrieben und der Lichkönig vernichtet wird. Ich werde Euch wie versprochen so gut wie möglich helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12917] = { id = 12917, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mit der Stimme des Windes sprechen", description = "Ich denke, mit unserem Glück hätten wir nicht erwarten sollen, Brann so leicht zu finden. Wenn wir herausfinden können, was Brann sagt, könnt Ihr ihn davon überzeugen, seinen Ort preiszugeben.\n\nDie Macht des Windes ist in diesen Bergen stark, was sich uns als äußerst nützlich erweisen könnte. Ein geübter Schamane kann den Klang aller Stimmen dieser Welt über den Wind hören.\n\nIm Nordwesten, auf der verschneiten Ebene, werdet Ihr Kreaturen des Windes finden, die Sturmreiter. Fangt ihre Stimmen ein und bringt sie zu mir.", sourceObjective = "Bringt 5 Stimmen des Windes zu Moteha Windkind an der Absturzstelle Grom'ash.", progress = "Habt Ihr die Stimmen des Windes?", completion = "Ihr solltet jetzt mit dem Zwerg sprechen können. Fragt Boktar, was er von Euch benötigt. Wir haben keine Zeit zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[12918] = { id = 12918, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine perfektionieren", description = "Ist so kalt wie der Atem eines Frostwyrms hier oben, findet Ihr nicht? Mir fehlen nicht nur die Kunden für mein Handwerk, sondern auch der Vorrat an Edelsteinen, die ich verkaufen könnte. Wenn Ihr mir einige ungeschliffene Edelsteine für meine Vorräte bringen würdet, dann könnte ich Euch beibringen, wie man Edelsteine perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", sourceObjective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Ounhulo in Valgarde.", progress = "Ihr seid zu großzügig. Das Mindeste, was ich tun kann, ist, Euch beizubringen, wie man einen Edelstein perfektioniert.", completion = "Das sind die perfekten Exemplare für meine Vorräte. Ich werde Euch nicht nur beibringen, wie man das Handwerk des Edelsteinschleifens perfektioniert, nein, ich werde außerdem einen der Edelsteine in seine perfekte Form schleifen und ihn Euch dann als Belohnung geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12919] = { id = 12919, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache des Sturmkönigs", description = "Der Lichkönig hat mein Volk dezimiert. Nun verwendet die Geißel die Leichen von Sturmriesen, um daraus entweder hirnlose Fleischriesen zu erschaffen oder noch Schlimmeres: zusammengeflickte Monstrositäten wie Thrym.\n\nIch werde vor nichts zurückschrecken, um dafür zu sorgen, dass sie alle von dieser Welt getilgt werden. Zusammen werden wir die Diener der Geißel vernichten, die Zul'Drak bedrohen.\n\nWir werden sie alle töten: Navarius, Algar und Thrym!\n\nWenn Ihr bereit seid, dann lasst es mich wissen und wir werden unsere Zerstörungsreise antreten.", sourceObjective = "Sprecht mit Gymer, um auf ihm zu reiten.\n\nVernichtet 100 Diener der Geißel und Algar den Auserwählten, Thrym und Prinz Navarius. Meldet Euch bei Kreuzfahrer MacKellar im Lager der Kreuzfahrer, falls Ihr erfolgreich sein solltet.", completion = "Unglaublich! Darüber wird man noch lange, lange Zeit reden, {name}! Ein Mann ritt auf dem Kopf des Königs der Sturmriesen und vernichtete eine ganze Armee der Geißel!\n\nUnd ich war da, als es passierte...", sourceObjectiveStatus = "unverified-source-field" }
quests[12920] = { id = 12920, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brann einholen", description = "Worauf wartet Ihr noch? Dank Moteha wurde die Sprachbarriere durchbrochen. Tretet mit Brann Bronzebart in Verbindung und versucht, so viel wie möglich darüber herauszufinden, wo er sich versteckt hält und hinter was er her ist.\n\nVielleicht lässt sich aus diesem Desaster noch etwas Gutes gewinnen.", sourceObjective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen. Erstattet anschließend Boktar Blutfurie bei der Absturzstelle Grom'ash Bericht.\n\nFalls Ihr Branns Kommunikator verlieren solltet, dann sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash.", progress = "Was habt Ihr herausgefunden?", completion = "<Boktar lauscht Eurem Bericht über Euer Gespräch mit Brann.>\n\nAn den Worten des Zwergs ist etwas Wahres dran. Vor'takhs Plan ist nicht der Stil der Horde. Wenn Brann Bronzebart einen Weg kennt, wie diese Eisenzwerge und ihre Schutzherren aufzuhalten sind, dann dient es unserer Sache, ihm zu helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12921] = { id = 12921, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tapetenwechsel", description = "Ausgezeichnet. Am östlichen Ende der Mine gibt es einen Ausgang, der nach Brunnhildar führt. Macht Euch auf den Weg dorthin. Ich werde Euch dort treffen.\n\nWir dürfen nicht gemeinsam gesehen werden, damit nicht der Verdacht entsteht, dass Ihr mir helft. Ich werde meine Magie dazu verwenden, mein Aussehen zu verändern. Macht Euch keine Sorgen, {race}. Wir werden Euren Freund im Nu gefunden haben.", sourceObjective = "Trefft Euch mit Lok'lira der Greisin in Brunnhildar.", completion = "Ihr seid hier - gut. Ich denke, dass ich jetzt weiß, wo sich Euer Goblin befindet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12922] = { id = 12922, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Veredlers Feuer", description = "Ein geheimnisvolles Schimmern tritt durch die poröse Außenfläche dieses Stück Metalls nach Außen.\n\nIhr habt das Gefühl, dass es das Klügste wäre, die Schlacke mit Fjorns Amboss wegzubrennen.\n\nWährend Ihr gerade darüber nachdenkt, wo Ihr in dieser gefrorenen Einöde etwas finden könntet, das heiß genug dafür wäre, läuft Euch ein Feuerklagegeist über den Weg...", sourceObjective = "Ihr müsst 10 wütende Funken von den wutentbrannten Klagegeistern auf dem Frostfeldsee sammeln und anschließend den Amboss bei Fjorns Amboss verwenden.", progress = "Die Oberfläche des Ambosses ist glühend heiß, im scharfen Gegensatz zu der winterlichen Luft, die ihn umgibt.", completion = "Ihr legt das Metall auf den Amboss und sofort, nachdem Ihr die Funken dazugegeben habt, fangen sie an, das Erz wie wild zu bearbeiten.\n\nAls die Funken schließlich verglüht sind, ist nur noch ein großes Stück Metall übrig, das auf besondere Art und Weise schimmert.", sourceObjectiveStatus = "unverified-source-field" }
quests[12924] = { id = 12924, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bündnis schließen", description = "<Thorim lächelt zum ersten Mal, seitdem Ihr ihn kennt.>\n\nLangsam fängt es an, so auszusehen, als hätte das Schicksal seine Finger im Spiel, {race}.\n\nEure Entdeckung stellt die Überbleibsel meiner Rüstung dar, die ich vor langer Zeit in einem Anflug von Trauer abgeworfen und den Elementen überlassen habe. Nur die Söhne Hodirs können sie neu schmieden - sie sind die eigentlichen Erbauer.\n\nWomöglich habt Ihr genug getan, um ihren Hass mir gegenüber zu beschwichtigen. Sucht ihren König Jokkum auf, falls er noch lebt.\n\nVersucht, seine Gunst zu gewinnen, und erbittet seine Hilfe.", sourceObjective = "Ihr sollt nach Dun Niffelem gehen und König Jokkum darum bitten, Thorims Rüstung neu schmieden zu lassen. Nachdem Ihr Jokkums Aufgabe abgeschlossen habt, sollt Ihr mit Njormeld in Dun Niffelem sprechen.", completion = "Es scheint, als wäre meine Technik erheblich besser geworden. Entweder ist es das oder die Legenden, die diesen Amboss umranken, sind wahr.\n\nDiese Rüstung ist besser als die alte und hat weniger Materialien benötigt.\n\nMit dem, was übrig geblieben ist, konnte ich etwas für Euch anfertigen - als Bezahlung für Eure Unterstützung.", sourceObjectiveStatus = "unverified-source-field" }
quests[12925] = { id = 12925, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missgeburten", description = "Der Lichkönig hat uns zu drei verschiedenen Gelegenheiten Botschafter geschickt. Alle drei wurden auf der Stelle vernichtet.\n\nUnsere Schwestern in Valkyrion waren unseren Traditionen nicht so treu und gingen auf die Annäherungsversuche der Geißel ein. Anstatt die wilden Drachen zu fangen, lassen sie sie nun aus der Verseuchung und dem Schmutz auferstehen, in dem sich die Geißel suhlt.\n\nNehmt das Frostöl, das die Valkyrion von Hyldnir bei sich tragen, und lasst damit alle Eier, die Ihr findet, gefrieren. Gerüchten zufolge gibt es dort, wo die Eier aufbewahrt werden, auch einen verrotteten Tümpel der Verseuchung.", sourceObjective = "Thyra Kvinnshal in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören.", completion = "Wir sind Euch sehr dankbar, Schwester, denn wir können nicht zulassen, dass mit unseren wichtigen Traditionen gebrochen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[12926] = { id = 12926, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile des Rätsels", description = "Wir konnten mitverfolgen, wie die Eisenzwerge und ihre Konstrukte die Steinwesen, die Brann die Irdenen nennt, gemeinsam mit ihren verbündeten Riesen angriffen. Tretet mit ihm in Verbindung und helft ihm so gut Ihr nur könnt und vergesst nicht, dass alles, was Ihr von ihm und seiner Suche erfahren könnt, uns bei unserem Kampf gegen die Eisenzwerge und ihren Meister eine Hilfe sein könnte.", sourceObjective = "Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen.", progress = "Habt Ihr die Scheibe zusammengefügt?", completion = "Das ging aber schnell! Nun, da wir die Scheibe haben, müssen wir herausfinden, wie wir zur ersten Hälfte des Archivschlüssels gelangen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12927] = { id = 12927, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Daten schürfen", description = "Diese Scheibe, die Ihr zusammengebaut habt... sie ist leer! Bewahrer Mimir, der Tüftler, der diese Bibliothek errichtet hat, muss die Informationen irgendwo anders versteckt haben. Seht Euch in der Bibliothek des Erfinders um; sind dort irgendwelche Datenbanken?\n\nVielleicht ist das der Zweck dieser Scheibe. Versucht, sie in der Nähe einer dieser Datenbanken einzusetzen. Vielleicht kann man darauf die Informationen speichern. Meldet Euch erneut bei mir, wenn Ihr das ausprobiert habt, und lasst mich wissen, was Ihr herausfinden konntet. In der Zwischenzeit werde ich versuchen, die andere Hälfte des Archivschlüssels zu finden.", sourceObjective = "Nutzt die Scheibe des Erfinders, um 7 versteckte Daten aus den Datenbanken zu beschaffen.", progress = "Habt Ihr die Scheibe ausprobiert? Was habt Ihr gefunden?", completion = "<Brann sieht die Scheibe in Eurer Hand an.>\n\nIch weiß nicht, ob darauf etwas gespeichert ist oder nicht! Ihr müsst mir sagen, was passiert ist.\n\n<Ihr beschreibt den Datenbeschaffungsprozess.>\n\nEs hat also funktioniert? Zumindest kann man sich darauf verlassen, dass Mimir systematisch vorgeht.", sourceObjectiveStatus = "unverified-source-field" }
quests[12928] = { id = 12928, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Norgannons Schale", description = "Scheibe des Erfinders wird aufgeladen.\n\nProzess abgeschlossen.\n\nNotfallprotokoll Gamma in Bearbeitung.\n\nLadevorgang von Notfallprotokoll abgeschlossen. Bitte zum Aktivieren von Archivar Mechaton, den Wächter von Norgannons Schale, aufgeladene Scheibe verwenden. Scheibe wird von Archivar Mechaton freigegeben, sobald Eure Identität verifiziert wurde.\n\nEuch ein angenehmes Jahrtausend.", sourceObjective = "Beschafft Euch Norgannons Schale von Archivar Mechaton.", progress = "Habt Ihr Norgannons Schale gefunden?", completion = "Das ist sie! Das ist die erste Hälfte von Norgannons Schlüsselstein. Gut gemacht, {name}. Archäologe Andorin hat schon sehr lange nach Hinweisen darauf gesucht, wo diese Schale zu finden ist. Er wird mir nie glauben, dass stattdessen ein mutiger {race} sie gefunden hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12929] = { id = 12929, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Irdenen von Ulduar", description = "Die Irdenen, die einst Ulduar bauten, bewohnten und verwalteten, wurden aus ihrem Zuhause vertrieben, als Loken die Stadt einnahm. Seitdem wurden die Verbannten von den Eisenzwergen ununterbrochen angegriffen.\n\nSie haben in einem alten Gebäude der Titanen an der Bergwand westlich der Bibliothek des Erfinders Zuflucht gefunden und ihm den Namen \"Bergfels' Zuflucht\" gegeben. Bergfels und seine Brüder kämpfen dagegen an, dass die Eisenzwerge ihren Zufluchtsort überrennen, doch sie können nicht mehr lange standhalten. Findet sie und helft ihnen, {name}.", sourceObjective = "Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht.", completion = "Ihr kennt also Brann Bronzebart, wie? Er ist unser engster Verbündeter unter denen, die aus Fleisch sind. Wir sind Blutsbrüder im Kampf mit Loken und seinen Anhängern, im Kampf um Ulduar.", sourceObjectiveStatus = "unverified-source-field" }
quests[12930] = { id = 12930, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltene Erde", description = "Es scheint schon so lange her zu sein, dass diese Hämmer Stein anstatt Eisen schlugen. Als wir aus Ulduar vertrieben wurden, mussten die schwächsten von uns sterben - die stärksten unserer Handwerker wurden zu Kriegern.\n\nDoch als die Eisenzwerge uns zurückschlugen, mussten selbst die Stärksten ihre Niederlage eingestehen.\n\nWir können nur wenig für die Verwundeten tun, außer uns stünde ein Vorrat an verzauberter Erde zur Verfügung. Einst bauten wir die Vorkommen an den steilen Klippen gen Nordwesten ab, aber der ständige Kampf hat uns davon abgehalten, unsere Vorräte wieder aufzufüllen. Würdet Ihr bitte helfen?", sourceObjective = "Baut mit der Spitzhacke der Irdenen 7 Klumpen verzauberte Erde ab. Bringt anschließend die Erde und 5 Einheiten Froststoff zu Bergfels dem Steinformer in Bergfels' Zuflucht.", progress = "Habt Ihr ein bisschen Erde finden können?", completion = "Das wird uns erlauben, noch mehr der Gefallenen zusammenzuflicken. Im Namen aller Verteidiger der Zuflucht möchte ich Euch danken, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12931] = { id = 12931, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurückschlagen", description = "Die Verteidiger der Zuflucht haben ihr Bestes gegeben, um die Angriffe der Eisenzwerge abzuschwächen, doch wir müssen weiterhin Stück für Stück vor ihnen zurückweichen. Meine Männer sind zäh, aber nicht unermüdlich. Ohne Verstärkung ist es nur eine Frage der Zeit, bis wir überrannt werden.\n\nWürdet Ihr uns mit Eurem Können bei der Verteidigung der Zuflucht zur Seite stehen? Die Moral der Verteidiger würde dadurch erheblich gesteigert werden und ihnen, wie auch mir, Hoffnung auf einen Gegenschlag geben.\n\nTötet jeden der Sturmgeschmiedeten, der Euch außerhalb der Zuflucht über den Weg laufen sollte. Vernichtet auch ihre Kreationen.", sourceObjective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 10 sturmgeschmiedete Angreifer tötet und anschließend zu ihm zurückkehrt. Ihr könnt entweder sturmgeschmiedete Räuber oder Häscher töten.", completion = "Ihr habt den Verteidigern etwas gegeben, über das sie sich freuen können. Zu sehen, wie der Feind durch Eure Hand fällt, hat ihnen neue Kraft verliehen und ihren Mut gestärkt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12932] = { id = 12932, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Yggdras!", description = "Ich sag Euch mal was, <Freundchen/meine Gute>, zwischen diesem Ort hier und den rollenden Ebenen von Nagrand ist ein großer Unterschied. Die Trolle hier sind zwar dreckiger als Oger - aber sein wir doch mal ehrlich: Ich geh' dorthin, wo es Gold gibt! Seid also willkommen in Zul'Drak, <Kollege/Kollegin>.\n\nIhr macht das erste Mal bei diesem Spektakel mit - na, dann lasst mich Euch erstmal erzählen, was Sache ist. Ich bin der Kampfveranstalter und dieser quirlige Troll neben mir ist Wodin, mein Leibwächter. Ihr seid die Unterhaltung. Wenn Ihr kämpfen wollt, dann sagt mir Bescheid und ich werde einen Kampf für Euch organisieren.\n\nWenn Ihr bereit seid und eine Gruppe Leute mitgebracht habt, dann können wir anfangen! Was meint Ihr dazu?", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Nicht schlecht, Herr Specht. Ihr könntet hier sogar ein wenig Gold machen - falls Ihr am Leben bleiben solltet, natürlich.", sourceObjectiveStatus = "unverified-source-field" }
quests[12933] = { id = 12933, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Magnataur!", description = "Der nächste Kampf ist erste Sahne, <mein Freund/meine Beste>! Anscheinend will so ein Magnataur aus der Drachenöde ein Stück vom Kuchen abbekommen. Habt Ihr schon mal gegen einen von denen gekämpft? Alles, was ich Euch sagen kann, ist, hoch zu zielen!\n\nGebt mir ein Zeichen und wir bringen die Party ins Rollen.", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Stinkbart! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Wow! Als ich Stinkbart zum ersten Mal gesehen hab, dachte ich, dass Ihr geliefert wärt! Gute Arbeit!", sourceObjectiveStatus = "unverified-source-field" }
quests[12934] = { id = 12934, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Aus einer anderen Welt!", description = "Ich werde Euch nicht belügen, <Kumpel/meine Dame>. Könnte sein, dass Ihr dem hier nicht gewachsen seid. Euer nächster Gegner kommt aus den Elementarebenen! Ich weiß nicht mal, was genau in der Arena auftauchen wird!\n\nHinein mit Euch, falls Ihr denkt, dass Ihr das schaffen könnt, und gebt ihnen Saures!", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt einen der Elementarlords! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Unglaublich! Als das Ding auftauchte, dachte ich zuerst, dass der ganze Laden hier in die Luft gehen würde! Ihr habt diese Runde wirklich dominiert!", sourceObjectiveStatus = "unverified-source-field" }
quests[12935] = { id = 12935, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Tuskarrmageddon!", description = "Euer nächster Gegner hat eine fiese, schaurige Art zu kämpfen, <Kleiner/Kleine> - die Art zu kämpfen, die man nur drauf haben kann, wenn man einmal die Radieschen von unten gesehen hat. Er ist kampfeshungrig und wird alle Register ziehen, um zu gewinnen. Passt auf! Ich habe gehört, dass er zur Übung mit Yetis kämpft!\n\nWir fangen an, wenn Ihr bereit seid.", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Orinoko Hauerbrecher! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Ich hab' mir schon ein wenig Sorgen gemacht, {name}. Als er die Seehunde und Pinguine auf Euch losgelassen hat... nun, da wusste ich nicht so recht, was ich davon halten sollte. Hat so ziemlich lächerlich ausgesehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12936] = { id = 12936, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Korrak der Blutrünstige!", description = "Ihr werdet das nicht glauben, {class}. Euer nächster Kampf wird gegen Korrak den Blutrünstigen sein! Sieht so aus, als würden die Drakkaritrolle die Muskeln spielen lassen! Und lasst es mich Euch sagen: Er hat vom Saft der Tiergötter genippt. Er ist gut und dazu bereit, Euch in den Boden zu stampfen.\n\nSeid Ihr bereit?", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Korrak den Blutrünstigen! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", completion = "Verdammt, ich kenne Korrak noch von ganz früher, als ich noch jünger war und für den Frostwolfklan arbeitete. Er konnte nie die Klappe halten! Ich denke, dass Ihr der Welt gerade einen großen Gefallen getan habt, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[12937] = { id = 12937, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unterstützung für die Gefallenen", description = "Die Verteidiger der Zuflucht kämpfen tapfer, aber sie sind dem eisernen Ansturm einfach nicht gewachsen.\n\nAus der von Euch gesammelten Erde kann ich Bandagen anfertigen, die helfen werden, die Wunden einiger Gefallener zu heilen. Je mehr Verteidiger wir zusammenflicken können, umso länger werden wir hier draußen durchhalten.\n\nHier, nehmt diese Packungen und wendet sie auf die Wunden der gefallenen Verteidiger außerhalb der Zuflucht an. Bringt so viele in die Schlacht zurück, wie Ihr nur könnt, {name}. Jeder Verlust ist ein Verlust zu viel.", sourceObjective = "Heilt mithilfe der Vulkanschlammpackung 8 gefallene Irdene Verteidiger und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", completion = "Die Krieger, die Ihr geheilt habt, werden helfen, die Linie noch länger zu halten. Wenn wir die Bedrohung durch die Eisernen wirklich loswerden wollen, dann müssen wir einen Weg finden, sie hinter den Linien anzugreifen", sourceObjectiveStatus = "unverified-source-field" }
quests[12938] = { id = 12938, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Herzog", description = "Wir brauchen Eure volle Konzentration, {name}. Wir können das Schattengewölbe zurzeit kaum halten. Wie Ihr sehen könnt, haben wir den Lichkönig erfolgreich geärgert.\n\n<Der Baron kichert.>\n\nIch möchte, dass Ihr mit Herzog Lankral sprecht. Er hat hier jetzt das Kommando. Ihr findet ihn innerhalb des Gewölbes.\n\nWenn ich Ihr wäre, würde ich ihn nicht warten lassen.", sourceObjective = "Sprecht mit Herzog Lankral im Schattengewölbe.", completion = "Ich freue mich, Euch endlich kennenzulernen, {name}. Wir schulden Euch viel, aber noch seid Ihr nicht fertig hier.\n\nEs gibt eine Vrykulstadt hinter den Bergen im Westen, die Jotunheim genannt wird.\n\nDie dortigen Vrykul stehen andauernd vor der Herausforderung 'aufzusteigen'. Die Gewinner gehen nach Ymirheim, um dem Lichkönig als dessen Elitekriegerkaste zu dienen, den Ymirjar, während die Verlierer zu Verseuchten Vargul reduziert werden.\n\nIhr werdet dafür sorgen, dass mehr Vargul als Ymirjar daraus hervorgehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12939] = { id = 12939, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrenhafte Herausforderung", description = "Der erste Schritt, den wir machen werden, findet an einem Ort in Jotunheim statt, den man Wilde Klippe nennt. Er liegt gleich hinter den Bergen im Westen.\n\nAuf der Klippe trainieren die Vrykul-Krieger und werden von den Männern ihres Thans in der hohen Kunst des Kampfes ausgebildet.\n\nIch möchte, dass Ihr diese Flagge nehmt und einige von ihnen herausfordert. Wir sollten sie mit 'simplen' Fähigkeiten demoralisieren, findet Ihr nicht, {race}?\n\n<Der Herzog grinst und seine verrotteten Zähne blitzen im trüben Licht des Gewölbes.>", sourceObjective = "Herzog Lankral vom Schattengewölbe bittet Euch, die Herausforderungsflagge zu nutzen und 6 Mjordinkrieger zu besiegen.", completion = "Ich habe bereits von Euren Fortschritten auf der Wilden Klippe gehört. Großartig, {name}... wirklich großartig!\n\n\n\nUnd nun ist es Zeit, einen Erlass an den Than aufzusetzen, dessen Vrykul Ihr derart leicht besiegen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12940] = { id = 12940, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12941] = { id = 12941, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie diesen hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12942] = { id = 12942, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reißt ihnen die schwarzen Schwingen aus", description = "Verräter. Wir Hyldnir können sie nicht leiden.\n\nDie Bewohner von Valkyrion sind schon viel zu lange ungeschoren davongekommen. Während wir Thorim treu geblieben sind, wurden sie zu Schoßhündchen des Lichkönigs!\n\nSie nennen diejenigen, die sein Geschenk empfangen haben, die Val'kyr. Sie fliegen mit gefiederten Flügeln, wie es Harpyien nun einmal so tun.\n\nIhr findet Valkyrion weit im Nordwesten hinter dem Tempel der Stürme. Erschlagt diese geflügelten Wölfinnen, Schwester. Erschlagt sie und ich werde Euch mit einem meiner wertvollsten Besitztümer belohnen.", sourceObjective = "Iva die Rachsüchtige in Brunnhildar möchte, dass Ihr nach Valkyrion geht und 12 werdende Val'kyr erschlagt.", completion = "Die Val'kyr sind lediglich die Schoßhündchen des Lichkönigs. Sie werden getötet werden, diese Miststücke. Sie haben ihre Wahl getroffen, nun müssen sie sich den Konsequenzen stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12943] = { id = 12943, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erlass des Schattengewölbes", description = "Than Ufrang der Mächtige residiert in seiner Halle mit Blick über die Wilde Klippe. Ich habe ihn beobachtet. Der Than ist ein geduldiger Vrykul, der Sinn für Strategie und die Kriegsführung besitzt. Er hat außerdem eine Neigung dafür gezeigt, abzuwarten und es in der anhaltenden Schlacht nicht zu übertreiben.\n\nEr muss sterben!\n\nIch habe einen Erlass aufgesetzt. Stellt Euch vor den Than und lest ihn laut vor.\n\n<Der Herzog zieht amüsiert eine Augenbraue hoch.>\n\nDas sollte ihn... zumindest reizen.", sourceObjective = "Herzog Lankral vom Schattengewölbe hat angeordnet, dass Ihr den Erlass des Schattengewölbes laut vor Than Ufrang dem Mächtigen vorlest und ihn dann tötet.", completion = "<Herzog Lankral nickt zustimmend, als Ihr ihm von Eurem Erfolg berichtet.>\n\nWir haben es mit einem Gegner zu tun, der uns nicht nur körperlich, sondern auch zahlenmäßig zusetzt. Wenn wir den Kampf um Eiskrone gewinnen wollen, dann müssen wir ihn überlisten!\n\nUfrangs Tod verschafft uns in Jotunheim einen Vorteil. Sehen wir einmal, ob wir ihn nutzen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[12944] = { id = 12944, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12945] = { id = 12945, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
