quests[12947] = { id = 12947, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12948] = { id = 12948, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Champion der Agonie", description = "Das ist das Ende, <mein Freund/meine Beste>! Euer letzter Gegner wird Eure größte Herausforderung sein. Es handelt sich um einen Vrykulchampion von den eisigen Weiten des Eiskronengletschers und er will Blut sehen! Besiegt ihn und Ihr werdet zum Champion des Amphitheaters der Agonie gekrönt! Dieser Kampf wird uns beide reich machen!\n\nSagt mir Bescheid, wenn Ihr bereit seid, und wir fangen an.", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Vladof den Metzger! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Ihr habt es geschafft, {name}! Das war der aufregendste Kampf, den ich bisher gesehen habe! Was werdet Ihr mit Euren Belohnungen machen? Was - ich? Ich werde zur Schattenseite in Dalaran gehen und dort alles verprassen. Da unten geht's heiß zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12949] = { id = 12949, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Besorgt den Schlüssel", description = "{class}, Instrukteur Hroegar da draußen hat sich den Schlüssel zu meinen Ketten um den Hals gehängt.\n\nVielleicht könntet Ihr ihn ja besorgen, indem Ihr einfach seinen Kopf von den Schultern trennt?", sourceObjective = "Vaelen der Geschundene in Ufranggs Halle hat Euch gebeten, den Schlüssel zu Vaelens Ketten zu besorgen.", progress = "Habt Ihr ihn?", completion = "Vielen Dank, {race}. Gebt mir den Schlüssel einfach, ich helf' mir dann selber weiter.", sourceObjectiveStatus = "unverified-source-field" }
quests[12950] = { id = 12950, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eimer mit Süßigkeiten", sourceObjective = "Süßigkeiteneimer wie dieser hier gibt es in jeder Gaststätte zu finden. Na los... greift zu!", sourceObjectiveStatus = "unverified-source-field" }
quests[12951] = { id = 12951, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gebt dem Baron Bescheid", description = "Ihr müsst jetzt unbedingt ins Schattengewölbe zurückkehren und Baron Splitter wissen lassen, dass ich versagt habe.\n\nWisst Ihr, diese Vrykul-Teufel haben nicht nur mich gefangen genommen, sondern auch mein ganzes Regiment aus Todesrittern.\n\nIch hätte die Falle erkennen müssen, bevor sie zuschnappte, aber was geschehen ist, ist nun mal geschehen.\n\nGeht nun, bevor sie Euch auch noch erwischen! Wir sehen uns dann im Gewölbe.", sourceObjective = "Sprecht mit Baron Splitter im Schattengewölbe.", completion = "Was?! Wir können auf keinen einzigen Todesritter verzichten und erst recht nicht auf ein ganzes Regiment!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[12952] = { id = 12952, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine perfektionieren", description = "Meine Fähigkeiten sind an diesem verflixten Ort zu nichts nütze. Ich habe nichts zu tun! Und dabei habe ich viele Jahre damit verbracht zu lernen, wie Edelsteine geschliffen werden müssen, damit sie eine perfekte Form erhalten. Ihr seht wie jemand aus, der mir ein paar Edelsteine finden könnte, und falls Ihr das für mich tätet, würde ich Euch im Gegenzug beibringen, wie man Edelsteine perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", sourceObjective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Carter Tiffens im Hafen der Vergeltung.", progress = "Das dürfte reichen. Ich werde Euch beibringen, wie man einen Edelstein perfektioniert.", completion = "Das wird reichen müssen. Ich kann Euch beibringen, wie man die Kunst des Edelsteinschleifens perfektioniert. Außerdem werde ich Euch als Beweis für meine Fähigkeiten einen von meinen Edelsteinen geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12953] = { id = 12953, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valkyrion muss brennen", description = "Die Kiste ist mit Brandharpunen gefüllt. Ihr könnt Euch erinnern, draußen Harpunenkanonen und trockene Heuhaufen gesehen zu haben.\n\nVielleicht wird Iva Euch für die zusätzliche Mühe belohnen.", sourceObjective = "Benutzt die Harpunenkanone von Valkyrion, um 6 trockene Heuhaufen anzuzünden.", completion = "Das nenne ich Engagement! Diese Verräterinnen mögen jetzt vielleicht eine neue Meisterin haben, doch sie werden niemals vergessen, mit welchem Geschenk sich ihre Schwester von ihnen verabschiedet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12954] = { id = 12954, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Amphitheater der Agonie: Yggdras!", description = "Hab mich schon gefragt, wann Ihr auftauchen würdet, {name}! Jemanden hier zu haben, der einmal Champion des Rings des Blutes gewesen ist, wird ein Kassenschlager werden! Wir werden reich sein, <mein Freund/meine Beste>! REICH!\n\nWie dem auch sei, dieses Dreckloch nennt sich Zul'Drak. Die ganzen Eistrolle scheinen den Ort als Toilette zu benutzen. Ich weiß nicht, die ganze Gegend hier scheint mir nicht mehr ganz dicht zu sein, wenn Ihr mich fragt! Doch wen juckt's, stimmt's? Wir sind hier, um etwas Gold zu machen!\n\nIhr kennt ja die Leier, {name}. Wenn Ihr bereit seid, dann lasst es mich wissen und die Show kann losgehen!", sourceObjective = "Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen.", progress = "Es wird erst bezahlt, wenn der Kampf zu Ende ist, Mann.", completion = "Hey! Ich kenne Euch. Euer Sieg im Ring des Blutes war noch monatelang in aller Munde! Zu dumm nur, dass Ihr den Titel habt abgeben müssen, als Ihr nicht aufgetaucht seid, um ihn zu verteidigen! Wie gewonnen, so zerronnen, wie? Zumindest seid Ihr noch am Leben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12955] = { id = 12955, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eliminiert die Konkurrenz", description = "Hrchrmmm...\n\n<Der Springer räuspert sich.>\n\nEntschuldigung. Manchmal ist es schwer, mich zu verstehen. Ihr wisst ja, wie das ist.\n\nIch wollte sicherstellen, dass, wenn Ihr Euch an der Wilden Klippe hinter den Bergen im Westen wiederfindet, Ihr den dortigen Wettbewerb eliminiert.\n\nIm Besonderen würde ich es begrüßen, wenn Ihr Sigrid Eiskind, Efrem den Treuen, Onu'zun und Tinky Dochtpfiff zu Duellen herausfordern und sie vor den Augen der Vrykul demütigen würdet.", sourceObjective = "Der Springer beim Schattengewölbe möchte, dass Ihr Duelle austragt und Sigrid Eiskind, Efrem den Treuen, Onu'zun und Tinky Dochtpfiff besiegt.", completion = "Das war sehr wichtig, {name}. Indem Ihr sie verjagt habt, haltet Ihr sie auch davon ab, Euch bei dem, was auch immer Ihr dort unten zu erledigen habt, in die Quere kommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12956] = { id = 12956, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Funken Hoffnung", description = "Offensichtlich ist dies mehr als nur ein gewöhnliches Stück Metall.\n\nEs ist anders als jedes Erz, das Ihr kennt, hart und dabei keineswegs brüchig und es glüht selbst, wenn es kalt ist.\n\nBei näherer Betrachtung könnt Ihr erkennen, dass etwas durch die Oberfläche hindurchleuchtet. Es handelt sich um eine von Thorims Runen...", sourceObjective = "Ihr sollt das veredelte glänzende Erz zu Thorim in den Tempel des Sturms bringen.", progress = "Was habt Ihr denn da, kleines Wesen?", completion = "Ihr bemerkt, wie sich Thorims düsterer Gesichtsausdruck aufhellt, als Ihr ihm das Erz zeigt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12957] = { id = 12957, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sklaven der Sturmgeschmiedeten", description = "Gen Südwesten an der westlichen Seite der Verschneiten Ebenen haben die Eisenzwerge eine Mine in einen Hügel gegraben. Für den Erzabbau verwenden sie dort gefangene Mechagnome, Hüter Mimirs Diener.\n\nIch weiß nicht, woher diese Mechagnome gekommen sind, und auch nicht, was sie mit ihrer Freiheit anstellen würden, doch vielleicht können wir sie für uns gewinnen.\n\nGeht zur Gefrorenen Mine, {name}, und befreit diese Kreaturen aus ihrer Knechtschaft. Fragt sie, ob sie an unserer Seite in den Kampf gegen die tyrannischen Eisenzwerge ziehen möchten.", sourceObjective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 6 gefangene Mechagnome befreit und 3 sturmgeschmiedete Zuchtmeister tötet.", completion = "Ich hatte gehofft, dass sich mehr Gefangene uns anschließen würden, kann's ihnen jedoch nicht verübeln. Leute, die sich uns bereitwillig anschließen, sind Mangelware, und wir sind Euch dankbar, dass Ihr uns Euren Schwertarm geliehen habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12958] = { id = 12958, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: Blutrotes Nephritamulett", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung Blutjadeamulette für den Verkauf in Lorenhall beantragt. Falls Ihr mir eins bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert ein Vrykulamulett mit einem Nephrit und einem Blutstein, um ein blutrotes Nephritamulet herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.\n\nVrykulamulette könnt Ihr von jedem Vrykul in Nordend erhalten.", progress = "Habt Ihr ein blutrotes Nephritamulett für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12959] = { id = 12959, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: leuchtende Elfenbeinfigur", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung leuchtender Elfenbeinfiguren für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert Elfenbein aus Nordend mit einem Chalzedon und einem Schattenkristall, um eine leuchtende Elfenbeinfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nElfenbein aus Nordend könnt Ihr von jedem Schaufelhauer oder Mammut in Nordend erhalten.", progress = "Habt Ihr eine leuchtende Elfenbeinfigur für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12960] = { id = 12960, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: tückische Sonnenbrosche", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung tückischer Sonnenbroschen für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert eine eisenzwergische Brosche mit einem Riesencitrin und einem Sonnenkristall, um eine tückische Sonnenbrosche herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nEisenzwergische Broschen könnt Ihr von jedem Eisenzwerg in Nordend erhalten.", progress = "Habt Ihr eine tückische Sonnenbrosche für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12961] = { id = 12961, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: aufwändige Knochenfigur", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung aufwändiger Knochenfiguren für den Verkauf in Lorenhall beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert einen Protodrachenknochen mit einem Sonnenkristall und einem Nephrit, um eine aufwändige Knochenfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nProtodrachenknochen könnt Ihr von jedem Protodrachen in Nordend erhalten.", progress = "Habt Ihr eine aufwändige Knochenfigur für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12962] = { id = 12962, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: helles Rüstungsrelikt", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung heller Rüstungsrelikte für den Verkauf in Lorenhall beantragt. Falls Ihr mir eins bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert den Rest einer Elementarrüstung mit einem Blutstein und einem Riesencitrin, um ein helles Rüstungsrelikt herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.\n\nDie Reste einer Elementarrüstung könnt Ihr von jedem Klagegeist in Nordend erhalten.", progress = "Habt Ihr ein helles Rüstungsrelikt für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12963] = { id = 12963, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung: unbeständige Sonnenkuriosität", description = "Ein wohlhabendes Lieferungsunternehmen hat eine Sammlung unbeständiger Sonnenkuriositäten für den Verkauf in Undermine beantragt. Falls Ihr mir eine bringen könntet, würde ich Euch mit einem Juwelierssymbol von Dalaran belohnen.", sourceObjective = "Kombiniert eine Geißelkuriosität mit einem Sonnenkristall und einem Schattenkristall, um eine unbeständige Sonnenkuriosität herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.\n\nGeißelkuriositäten könnt Ihr von jedem Diener der Geißel in Nordend erhalten.", progress = "Habt Ihr eine unbeständige Sonnenkuriosität für meine Lieferung nach Undermine dabei?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Kommt morgen wieder zurück. Ich bin mir sicher, dass ich dann einen anderen Gegenstand von Euch brauchen werde!", sourceObjectiveStatus = "unverified-source-field" }
quests[12964] = { id = 12964, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das dunkle Erz", description = "Im westlichen Teil der Verschneiten Ebenen errichteten die Sturmgeschmiedeten Eisenzwerge die Gefrorene Mine; eine Mine, in der sie ausschließlich Sklaven schuften lassen.\n\nSie befindet sich weit hinter feindlichen Linien, weswegen wir nicht viel darüber herausfinden konnten, was dort drinnen vor sich geht. Meine Späher haben mir jedoch davon berichtet, dass sie Unmengen von blass-dunklem Erz aus der Mine schaffen.", sourceObjective = "Bringt 5 Erzproben zu Bergfels dem Steinformer in Bergfels' Zuflucht.", progress = "Was habt Ihr über das Erz herausgefunden?", completion = "<Bergfels streckt seine Hand nach dem Erz aus, schreckt dann jedoch zurück.>\n\nDieses Erz... ich kann es nicht anfassen. Es brodelt regelrecht vor unnatürlicher Energie. Kein Steinwesen wird es bearbeiten können. Was wollen sie damit nur anfangen?", sourceObjectiveStatus = "unverified-source-field" }
quests[12965] = { id = 12965, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokens Gaben", description = "Der Eine, der die sturmgeschmiedeten Eisenzwerge befehligt, wird Runenseher Valduran genannt. Es heißt, sein Meister, Bewahrer Loken, der Ulduar übernommen hat, habe Valduran mächtige Titanenartefakte überlassen, die ich allerdings nie mit eigenen Augen gesehen habe.\n\nDas würde erklären, warum die Sturmgeschmiedeten Krieger laut meinen Männern derart stark und wild geworden sind.\n\nValdurans Basis Nidavelir liegt im Südwesten jenseits der Verschneiten Ebenen. Begebt Euch dorthin, {name}, und neutralisiert seine Macht. Zerstört diese Gaben von Loken und helft uns, von der Stärke seiner Anhänger zu profitieren.", sourceObjective = "Zerstört Lokens Wut, Lokens Kraft und Lokens Gunst und kehrt dann zu Bergfels dem Steinformer nach Bergfels' Zuflucht zurück.", completion = "<Bergfels nickt grimmig.>\n\nIhr habt die Sturmgeschmiedeten stark geschwächt, aber sie werden weiterkämpfen. Ihre Verluste interessieren sie nicht, wohingegen mehr und mehr unserer Verteidiger fallen. Selbst wenn sie einhundert oder eintausend Gefallene zu beklagen haben, werden sie weiterkämpfen, bis sie uns zu Kies zermahlen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[12966] = { id = 12966, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr könnt ihn nicht verpassen", description = "<Jokkum hört Euch geduldig zu, als Ihr ihm Eure Bitte schildert, und scheint gründlich darüber nachzudenken, bevor er Euch schließlich antwortet.>\n\nAlso Ihr seid es, bei dem wir uns für Fjorns Ableben bedanken müssen?\n\nEs mag vielleicht stimmen, dass Ihr uns in Zeiten der Not geholfen habt, doch es gibt noch immer viel zu tun, um die Beziehung zwischen Thorim und uns wieder ins Reine zu bringen.\n\nFürs Erste werde ich Njormeld erlauben, die Rüstung, die wir dem Sturmherren vor vielen, vielen Zeitaltern schenkten, neu zu schmieden. Betrachtet es als Bezahlung dafür, dass Ihr uns gegen Fjorn geholfen habt.\n\nNjormeld wurde entsandt, um Fjorns Amboss zurückzubringen. Ihr solltet ihn dort vorfinden können.", sourceObjective = "König Jokkum in Dun Niffelem möchte, dass Ihr zu Fjorns Amboss geht und Njormeld sucht.", completion = "Thorims Rüstung neu schmieden? Es ist möglich.\n\nDoch zunächst wäre da noch die Sache mit dem Amboss...", sourceObjectiveStatus = "unverified-source-field" }
quests[12967] = { id = 12967, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kampf gegen die Elemente", description = "Snorri war einst der Stolz unserer Nation. Viele Gegner mussten unter der Keule dieses großen Kriegers ihr Leben lassen.\n\nAuch wenn er nicht mehr das ist, was er einmal war, verehren wir ihn immer noch. Das Alter fordert seinen Tribut, trübt seine Sinne und raubt ihm die Kräfte. Dennoch hat er sich wie eh und je seinen Stolz bewahrt und lässt keine Gelegenheit aus, um sich in die Schlacht zu stürzen.\n\nWo wir schon bei Schlachten sind: Wir kühlen Fjorns Amboss, damit er nach Hause zurückgebracht werden kann. Die verbliebenen Feuerklagegeister leisten noch etwas Widerstand. Helft Snorri dabei, seine ruhmreichen Tage erneut zu durchleben, {race}. Führt ihn gegen diesen Gegner in die Schlacht.", sourceObjective = "Njormeld wünscht, dass Ihr Snorri zu Fjorns Amboss begleitet und ihm dabei helft, 10 wutentbrannte Klagegeister zu töten.", progress = "Ist es Euch gelungen, Snorri zu einem weiteren Sieg zu führen, {class}?", completion = "Das war eine ehrenwerte Leistung, {race}. Ich sollte dem König von Eurer Mithilfe berichten.\n\nDer Amboss ist fast ausreichend abgekühlt. Wir werden uns bald in Dun Niffelem wiedersehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12968] = { id = 12968, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yuldas Torheit", description = "Die Hexe, mit der alles angefangen hat, Yulda die Sturmwirkerin, ist in unser Dorf gekommen. Sie hat es gewagt, unsere noblen Traditionen zu beleidigen und die vergifteten Versprechungen des Lichkönigs von sich zu geben.\n\nSie hätte uns von einem Schwert durchbohrt wieder verlassen sollen, aber ihre Magie war zu stark und sie konnte entkommen.\n\nIhr findet sie im größten Gebäude in Valkyrion. Zeigt ihr, dass man sich mit uns lieber nicht anlegen sollte.", sourceObjective = "Iva die Rachsüchtige aus Brunnhildar möchte, das Ihr Yulda die Sturmwirkerin in Valkyrion tötet.", completion = "Yulda hatte es nicht anders verdient. Wer das Hildarthing beleidigt, kommt nicht ungeschoren davon; nicht einmal eine von uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[12969] = { id = 12969, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ist das Euer Goblin?", description = "Ich glaube, das ist der kleine grüne Freund, nach dem Ihr gesucht habt. An Eurer Stelle würde ich eingreifen, bevor diese Hyldnir ihn in zwei Hälften zerteilt.\n\nIhr seid während des Hildarthings eingetroffen, daher müssen alle Herausforderungen von den Teilnehmern angenommen werden. Nichts hält Euch davon ab, den Platz Eures grünen Freundes einzunehmen.", sourceObjective = "Fordert Agnetta Tyrsdottar heraus, um Zeev Zischelfunken zu retten. Kehrt ins Dorf Brunnhildar zu Lok'lira der Greisin zurück, wenn Ihr erfolgreich wart.", progress = "Ihr seid zurück.", completion = "Das habt Ihr gut gemacht. Wie es scheint, wurde unsere Abmachung für beide Seiten zufrieden stellend erfüllt.", sourceObjectiveStatus = "unverified-source-field" }
quests[12970] = { id = 12970, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Hildarthing", description = "Ich weiß nicht, ob es Euch aufgefallen ist, aber durch den Sieg über Euren ersten Hyldnir habt Ihr Euch für das Hildarthing qualifiziert - den großen Kampf Hyldnir gegen Hyldnir, um festzustellen, wer an Thorims Seite herrschen wird.\n\nDas Hildarthing ist der Grund, warum man mich eingesperrt hat, denn ich wollte daran teilnehmen, obwohl ich viel zu alt und zu schwach bin, um den Hyldnir gewachsen zu sein.\n\nWenn Ihr interessiert seid, hätte ich einen Vorschlag für Euch.", sourceObjective = "Hört Euch den Vorschlag von Lok'lira der Greisin an.", completion = "Dann ist es abgemacht. Ihr werdet das Hildarthing beenden und mit meiner Hilfe dafür sorgen, dass Thorim seinen rechtmäßigen Platz zurückerhält.", sourceObjectiveStatus = "unverified-source-field" }
quests[12971] = { id = 12971, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sich allen Herausforderern stellen", description = "Dann kommen wir mal in die Gänge. Die gute Nachricht ist, dass Ihr Euch durch Euren Sieg über Agnetta einen Platz in der nächsten Kampfrunde ergattert habt.\n\nDie schlechte Nachricht ist, dass all Eure Gegner auch jemanden in der ersten Runde besiegt haben - wird also kein Kinderspielchen.", sourceObjective = "Lok'lira die Greisin in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt.", completion = "Ihr habt es geschafft, {name}. Ihr habt einige der stärksten Kämpferinnen besiegt, die das Volk der Hyldnir zu bieten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[12972] = { id = 12972, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihr werdet einen Bären brauchen", description = "In den ersten Runden des Hildarthings war Euch das Glück hold. Um weiterzukommen, braucht Ihr einen eigenen Kriegsbären.\n\nDummerweise geben die Hyldnir nicht einfach irgendwem ihre Bären, nein: Ihr müsst Euch erst in einem wahren Kampf als siegreich erweisen, nicht nur in einem Gladiatorenwettbewerb.\n\nDie Hyldnir von Brunnhildar sind momentan in eine Fehde gegen die Söhne Hodirs verwickelt, Thorims einstige Verbündete. Sprecht mit Brijana, die Ihr direkt außerhalb des Dorfes antreffen könnt, und fragt sie, wie Ihr helfen und Euch gleichzeitig beweisen könnt.", sourceObjective = "Sprecht mit Brijana, die sich außerhalb von Brunnhildar aufhält.", completion = "Denkt Ihr, wir würden Euch einfach so einen Bären geben? Ihr müsst Euch schon beweisen, bevor wir Euch irgendetwas überlassen.\n\nUnd werdet bloß nicht übermütig, nur weil Ihr beim Hildarthing einige Herausforderer besiegen konntet.", sourceObjectiveStatus = "unverified-source-field" }
quests[12973] = { id = 12973, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Gebrüder Bronzebart", description = "Das war's! Wir haben endlich den Schlüsselstein... Er ist schön! Ich bin schon mehr als einmal um die ganze Welt gereist, aber wegen dieses Dings war ich wieder so aufgeregt wie ein kleines Kind. Allerdings dürfte jetzt wohl nicht der richtige Zeitpunkt sein, um durchzuatmen und den Stein zu bewundern. Wir müssen von hier verschwinden.\n\nSteigt auf meine Flugmaschine und sorgt für Deckung, damit wir bei unserer Flucht vor diesen Eisenzwergen geschützt sind!", sourceObjective = "Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung.", progress = "Tut mir leid, Kamerad! Ich war so konzentriert, dass ich Euch gar nicht gesehen habe.", completion = "König Sturmherz möchte Euch seinen aufrichtigsten Dank dafür aussprechen, dass Ihr ihn und seine Brüder wieder zusammengebracht habt. Es scheint, als wäre er losgezogen, um eine Rechnung zu begleichen. Vielleicht werdet Ihr ihn vor Arthas' Türschwelle wiedertreffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12974] = { id = 12974, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruf des Champions!", description = "Pff, was hier unten vor sich geht, hat nichts mit Kämpfen zu tun. Es sind ein paar Leute, die um eine Flagge herumtanzen, mehr nicht.\n\nSucht Ihr nach einem echten Kampf? Denn, falls dem so ist, dann habe ich hier die besten Karten weit und breit.\n\nHabt Ihr schon mal von Gurgthock und Wodin gehört? Dem Goblin und dem Troll, die den Ring des Blutes in der Scherbenwelt geleitet haben? Nun, sie sind jetzt hier in Nordend und haben drüben in Zul'Drak einen komplett neuen Kampfring eröffnet. Falls Ihr Interesse haben solltet, dann geht nach Zul'Drak östlich des Kristallsangwalds. Ihr findet sie in der großen Arena im Zentrum. Sagt ihnen, dass Schufti Vickers Euch schickt!", sourceObjective = "Sucht Gurgthock im Amphitheater der Agonie in Zul'Drak auf.", completion = "Schufti hat Euch geschickt, wie?", sourceObjectiveStatus = "unverified-source-field" }
quests[12975] = { id = 12975, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Gedenken an", description = "Mit Sicherheit hat Thorim Euch von der Tragödie erzählt, die uns trennt.\n\nIn Donnerfall, nordöstlich von hier, haben die Dinge ihren Lauf genommen. Die gefrorenen Fossilen dort erinnern an den schwarzen Tag, ebenso wie die Geister, die jenen Ort heimsuchen.\n\nDamit mein Volk Thorim vergeben kann, muss der Ort ein anderes Aussehen erhalten. Ein Denkmal muss errichtet werden, damit unsere Herzen wieder Frieden finden.\n\nBegebt Euch dorthin, {race}. Sammelt die Teile von Hodirs Horn ein, das an jenem Tag zertrümmert wurde.", sourceObjective = "König Jokkum in Dun Niffelem wünscht, dass Ihr nach Donnerfall geht und 8 Hornfragmente einsammelt.", progress = "Konntet Ihr die Teile von Hodirs Horn finden?", completion = "Eine weitere gute Tat, die Ihr für Thorim vollbracht habt, {class}.\n\nDas wird dazu beitragen, dass die Herzen meines Volkes gegenüber Thorim milde gestimmt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12976] = { id = 12976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Monument für die Gefallenen", description = "Bringt diese Teile zu Njormeld. Er wird die einzelnen Teile dieses heiligen Relikts für den Bau eines mächtigen Monuments verwenden.\n\nMöge es die Schmerzen lindern und die Wunden verheilen lassen, die mein Volk in diesen vielen Jahren auf sich nehmen musste.\n\nMöge seine Gegenwart dabei helfen, ein neues Zeitalter herbeizuführen, in dem wir erneut glorreiche Schlachten an Thorims Seite führen werden.\n\nGeht jetzt, {class}. Njormeld erwartet Euch.", sourceObjective = "König Jokkum wünscht, dass Ihr Hodirs Hornfragmente zu Njormeld in Dun Niffelem bringt.", progress = "Habt Ihr Hodirs Hornfragmente dabei, {race}?", completion = "<Njormelds Augen beginnen sichtlich zu glänzen, als er den Inhalt des Beutels auf dem Amboss entleert.>\n\nHodirs Horn...\n\nEs handelt sich dabei um ein heiliges Geschenk an unser Volk von Hodir höchstpersönlich, {race}. Es ist für uns ein Relikt von größter Wichtigkeit.\n\nWenn Ihr das nächste Mal in unsere Feste zurückkehrt, werdet Ihr die Früchte Eurer Arbeit zu Gesicht bekommen.\n\nLebt wohl.", sourceObjectiveStatus = "unverified-source-field" }
quests[12977] = { id = 12977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Ruf", description = "Ihr habt den Riesen von Dun Niffelem einen großen Dienst erwiesen. Ohne Euch würde dieses Monument nicht mehr existieren.\n\nWährend Ihr schweigend über dessen Bedeutung nachdenkt, überfluten Emotionen Euer Herz. Die Gefühle überschwemmen Euren Geist mit Gedanken und Bildern... und auch einem Gefühl der Dringlichkeit.\n\nDie Empfindungen verblassen und hinterlassen in Euch das Gefühl, dass Ihr wisst, was zu tun ist. Die ruhelosen Geister am Donnerfall müssen vernichtet werden.\n\nAls Ihr aufbrecht, stellt Ihr fest, dass Ihr ein astrales Horn in den Händen haltet.", sourceObjective = "Lasst Hodirs Horn bei 5 Vorfahren der Niffelem und 5 ruhelosen Frosterben in Donnerfall erklingen.", progress = "Ein heftiger Wind wirbelt um das Horn herum. Sein Klang hallt von den umgebenden Bergen wieder.\n\nFür jemanden, der dies nicht weiß, würde es so aussehen, als bliese das Horn sich selbst...", completion = "Ein Gefühl der Ruhe und Zufriedenheit erfüllt Euch nun, und Ihr wisst, dass die einst gequälten Geister des Donnerfalls nun in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12978] = { id = 12978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im Angesicht des Sturms", description = "Wie Bergfels habe auch ich einst den Hütern als Handwerker in Ulduar gedient, aber nach Lokens Verrat habe ich meinen Hammer gegen unsere neuen Gegner erhoben.\n\nWenn wir genug Mann abstellen konnten, habe ich Überfälle gegen Nidavelir angeführt, um den Druck auf unsere Verteidiger zu verringern. Allerdings stehen unsere Linien kurz vor dem Zusammenbruch.\n\nIhr habt Euch als fähiger Kämpfer und loyaler Verbündeter erwiesen. Vielleicht würdet Ihr ja unter unserem Banner den Kampf gegen Nidavelir aufnehmen - die Feste der Eisenzwerge im Südwesten auf der anderen Seite der verschneiten Ebene.", sourceObjective = "Bruor Eisenbann in Bergfels' Zuflucht bittet Euch, 10 Sturmgeschmiedete in Nidavelir zu töten. Tötet Sturmgeschmiedete Champions, Sturmgeschmiedete Magier oder Sturmgeschmiedete Kriegsgolems.", completion = "Vielleicht gibt es noch Hoffnung auf den Sieg, {name}. Es ist uns nie gelungen, einen Angriff auf die Sturmgeschmiedeten aufrecht zu erhalten, aber mit Euren Bestrebungen könnte Valduran dennoch fallen!", sourceObjectiveStatus = "unverified-source-field" }
quests[12979] = { id = 12979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rüstung der Dunkelheit", description = "Diese Rüstungsplatte ist im Vergleich zum Rest der Verteidigung des Golems dick und übergroß. Eine schnelle Untersuchung seines Leichnams hat ergeben, dass diese schwerere Platte nachträglich angebracht wurde, vielleicht als unausgegorene Aufrüstung.\n\nWarum haben die Eisenzwerge diese überflüssige und nicht passende Rüstung an ihren Kriegsgolems anbringen lassen?\n\nVielleicht hätte Bruor Eisenbann eine Idee, wenn er die Gelegenheit bekäme, einige dieser Platten von den Sturmgeschmiedeten Kriegsgolems zu untersuchen.", sourceObjective = "Bringt 4 Dunkle Rüstungen zu Bruor Eisenbann in Bergfels' Zuflucht.", progress = "Was habt Ihr da?", completion = "Seid vorsichtig. Haltet diese Platte so weit wie möglich von mir fern. Selbst wenn man nur in ihrer Nähe ist, erleidet man Schmerzen.\n\nAber Ihr habt Recht, {name}, das sind riesige Rüstungsplatten für einen Kriegsgolem normaler Größe. Was würden die Sturmgeschmiedeten nur mit ihnen vorhaben? Es gibt nur einen Weg, das herauszufinden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12980] = { id = 12980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geheimnisse der Rüstung", description = "Seltsam, dass diese Plattenrüstung hier ist, doch wir müssen versuchen, so viel wie möglich mit ihrer Hilfe herauszufinden. Sie könnte Teil eines von Valdurans Plänen sein.\n\nEr hat ziemlich viel Zeit und Kraft darin investiert, das Erz für dieses Metall zu schürfen, es zu veredeln, das Metall zu schmieden und es auszutesten.\n\nAn der nördlichen Bergwand gen Osten befindet sich ein Gebäude namens Mimirs Werkstatt. Es ist schon seit langer Zeit nicht mehr in Gebrauch, doch wenn wir Glück haben, funktionieren ein paar von den Knechten noch. Bringt Eure Plattenrüstung dorthin und versucht, so viel wie möglich herauszufinden.", sourceObjective = "Bringt die dunkle Plattenrüstung zu Mimirs Werkstatt und bittet Tock den Knecht, sie sich näher anzusehen. Kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück, wenn Ihr fertig seid.", progress = "Was habt Ihr herausgefunden?", completion = "<Bruor lauscht Eurem Bericht über das, was Ihr in der Werkstatt herausgefunden habt.>\n\nValdurans Meister hat ihm also dieses unheimliche Metall gegeben, um damit die riesige Waffe zu bauen? Das muss es sein, was er für seinen letzten Schlag gegen uns einsetzen will! Wir müssen ihn aufhalten, bevor er die Waffe fertigbauen und einsetzen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12981] = { id = 12981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heiß und kalt", description = "Ihr starrt den Amboss an und vor Eurem innerem Auge spielen sich wieder die Szenen Eurer kürzlichen Errungenschaften ab; ganz besonders jene, die geholfen haben, dieses Artefakt hierherzubringen.\n\nEs fällt Euch ein, dass noch mehr getan werden muss. Im Osten verstreut liegt qualmender Schrott herum, Schrapnelle der einst dort gefochtenen Schlacht.\n\nKönnte man ihn auf irgendeine Art und Weise kühlen und einsammeln, stünde den Frostriesen mehr als genug Metall zur Verfügung und in der Region würden keine Kriegsüberbleibsel mehr herumliegen.", sourceObjective = "Ihr sollt zum Frostfeldsee gehen, die zerbrechlichen Klagegeister dort vernichten und die Essenz des Eises auf den qualmenden Schrott bei Fjorns Amboss anwenden. Anschließend sollt Ihr 6 Trümmer gefrorenen Eisenschrotts sammeln und zu Fjorns Amboss in Dun Niffelem zurückkehren.", progress = "Der Amboss wird von einem strahlenden blauen Schein umgeben.", completion = "Ihr habt das Gefühl, etwas erreicht zu haben, als Ihr erkennt, dass durch Euer Handeln die wiedererweckten Bande zwischen Thorim und den Söhnen Hodirs weiter gestärkt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[12982] = { id = 12982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefangene der Schwarzen Klinge", description = "Jetzt, da ich zurück bin, wird der Baron sicher wollen, dass ich meine Männer zurückhole. Wie ich sehe, können wir uns hier kaum halten. Die Streitkräfte des Lichkönigs sind im Begriff durchzubrechen und ohne meine gefangenen Todesritter werden wir nicht durchhalten.\n\nKönnt Ihr mir ein weiteres Mal beistehen, {name}?\n\nGeht zurück nach Jotunheim und befreit sie aus diesen Käfigen. Macht diese verdammten Schlösser auf. Wie, spielt für mich keine Rolle. Die Vrykul sind höchstwahrscheinlich im Besitz der Schlüssel.\n\nBefreit einfach nur meine Männer!", sourceObjective = "Vaelen der Geschundene im Schattengewölbe bittet Euch, 8 Gefangene der Schwarzen Klinge zu befreien. Ihr findet sie in den Käfigen in der weiteren Umgebung von Jotunheim.", completion = "Mein Dank ist Euch gewiss, {class}. Mit den von Euch befreiten Todesrittern werden wir die Stellung halten können... vorerst.", sourceObjectiveStatus = "unverified-source-field" }
quests[12983] = { id = 12983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Letzte ihrer Art", description = "Solange ich zurückdenken kann, waren unsere besten Bären die aus der Überwinterungshöhle im Osten.\n\nDiese Zeiten könnten nun endgültig vorbei sein. Die Höhle wurde von gefräßigen Jormungar überrannt und fast alle wilden Bären wurden dabei getötet.\n\nWenn Ihr jedoch eine überlebende Matriarchin finden könntet, verspreche ich Euch, dass sie besser kämpfen wird als irgendeiner von diesen Bären, die in Gefangenschaft geboren wurden.\n\nBringt diesen Harnisch zur Überwinterungshöhle und rettet eine überlebende Matriarchin. Viel Glück bei der Suche.", sourceObjective = "Astrid Björnrittar in Brunnhildar wünscht, dass Ihr eine Eisschlundmatriarchin aus der Überwinterungshöhle rettet.", completion = "Ich bin beeindruckt. Ich hätte nicht gedacht, dass ich jemals wieder eine Eisschlundmatriarchin zu Gesicht bekommen würde - besonders nicht in dieser Größe.", sourceObjectiveStatus = "unverified-source-field" }
quests[12984] = { id = 12984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valduran der Sturmgeborene", description = "Wir haben keine Wahl, {name}. Das, was Ihr in Mimirs Werkstatt herausgefunden habt, bedeutet, dass wir handeln müssen, bevor Valduran seine Waffe fertigbauen und einsetzen kann.\n\nSelbst in diesem Moment erkämpfen uns die Verteidiger der Zuflucht Zeit, damit wir uns um Valduran den Sturmgeborenen kümmern können.\n\nIhr müsst nach Nidavelir jenseits der südlich gelegenen Verschneiten Ebenen gehen, Valduran finden und ihm entgegentreten. Doch Ihr werdet nicht alleine sein. Nehmt dieses Kriegshorn mit Euch und lasst es erschallen, bevor Ihr Euch dem Anführer unserer Feinde stellt. Bruor und ich werden Euch bei diesem Kampf zur Seite stehen.", sourceObjective = "Benutzt Bergfels' Kriegshorn, sobald Ihr Valduran den Sturmgeborenen gefunden habt. Besiegt ihn und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", completion = "Valduran ist endlich tot und die Sturmgeschmiedeten geschwächt; doch falls etwas Wahres an seiner Prahlerei dran sein sollte, dann müssen wir die Chance nutzen und die Sturmgeschmiedeten bekämpfen, jetzt, da er nicht mehr da ist. Die Waffe, die sie bauen, könnte unser Ende sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[12985] = { id = 12985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einen Kopf schmieden", description = "Grüße, {race}.\n\nIch habe eine Aufgabe, für die König Jokkum Euch geeignet hält, falls Ihr noch immer unsere Gunst gewinnen wollt.\n\nIch habe Pläne für ein anderes Artefakt entwickelt; eines, das unserer Festung Hodirs Segen des Schutzes gewähren wird. Ich habe fast alles, was ich zum Bau benötige. Das Einzige, was noch fehlt, sind die Augen, ja, die Augen unserer gefallenen Feinde.\n\nHier, nehmt dieses Werkzeug und löst mit ihm die Augen der toten Eisenriesen heraus, die überall auf unseren Feldern verstreut herumliegen.", sourceObjective = "Njormeld in Dun Niffelem möchte, dass Ihr mithilfe der Hacke mit Diamantspitze 8 Sturmgeschmiedete Augen von den toten Eisenriesen auf dem Frostfeldsee beschafft und dann anschließend zu ihm zurückkehrt.", progress = "Habt Ihr die letzten benötigten Komponenten mitgebracht, {race}?", completion = "Es ist fast vollbracht.\n\nMit diesem Artefakt wird Dun Niffelem vor kommenden Gefahren gewarnt werden, bevor sie hier auftauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12986] = { id = 12986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Schicksal der Titanen", description = "Norgannons Kern befindet sich nicht an diesem Ort, und ich bin mir nicht sicher, warum Ihr danach sucht, {race}. Ebenso unsicher bin ich mir darüber, ob Ihr wirklich wisst, welchen Nutzen der Gegenstand hat, nach dem Ihr sucht.\n\nIch möchte, dass Ihr mir helft, bevor ich darüber nachdenke, Euch meine Hilfe anzubieten. Vor Kurzem habe ich etwas über den Behüter Thorim erfahren. Seine Machtposition wird ihm streitig gemacht und sein weiteres Schicksal steht in den Sternen. Das beunruhigt mich, weil ich nichts über die anderen Behüter weiß. Macht Euch diese Datenbank zu Nutze, um ihre Tempel gen Nordosten zu durchsuchen, und setzt mich über das Ergebnis in Kenntnis.", sourceObjective = "Creteus in den Fußmarschen möchte, dass Ihr zum Tempel des Erfindungsreichtums, Tempel des Winters, Tempel des Lebens und zum Tempel der Ordnung reist und mithilfe der Datenbank jeden Bereich untersucht.", progress = "Seid Ihr mit den Informationen zurückgekehrt, um die ich Euch gebeten habe, {race}?", completion = "Die Neuigkeiten, die Ihr mir überbringt, wiegen in der Tat schwer. Das Schicksal der verbliebenen Behüter ist ungewiss, aber ihre Abwesenheit verheißt für alle Länder Azeroths nichts Gutes.\n\nIch muss Eure Informationen aus der Datenbank auswerten und versuchen, mir einen Überblick über die Lage zu verschaffen. Ich glaube, ich bin im Besitz von Informationen, die für Euch im Augenblick wichtiger sind. Daher werde ich Euch zuerst an den besagten Informationen teilhaben lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12987] = { id = 12987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Helm platzieren", description = "Der Helm wurde geschmiedet.\n\nEure Mühen sind nicht unbemerkt geblieben, kleines Wesen. Es gibt zwar noch viel zu tun, doch wir, die Söhne Hodirs, sind Euch dankbar für das, was Ihr erreicht habt.\n\nIm Gegenzug biete ich Euch die Möglichkeit, unserem König und unseren Brüdern Hodirs Helm zu präsentieren.\n\nFliegt zur glitzernden Spitze des kleinen Eisstachels vor mir und rezitiert für mein Volk die Worte auf dieser Tafel.\n\nGenießt dieses Privileg, {class}. Niemals zuvor wurde einem Außenstehenden solch eine Ehre gewährt.", sourceObjective = "Njormeld möchte, dass Ihr zur Spitze der nördlich gelegenen Eisspitze in Dun Niffelem fliegt und die Worte auf den Tafeln der Verkündung rezitiert.", progress = "Habt Ihr Hodirs Helm schon platziert, {race}?", completion = "<Njormeld richtet seinen Blick hoch auf Hodirs Helm und ist sichtlich bewegt.>\n\nDas genügt, kleiner {race}.\n\nDas genügt...", sourceObjectiveStatus = "unverified-source-field" }
quests[12988] = { id = 12988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotiert die Schmieden!", description = "In meiner Torheit dachte ich, dass Valdurans Projekt in Narvirs Wiege - ein großes Baugebiet im Süden - nichts weiter sei als ein groteskes Monument für \"Hüter\" Lokens Grausamkeit.\n\nJetzt kennen wir die Wahrheit: Es sollte als Waffe gegen uns und die Allianz dienen. Wir dürfen nicht zulassen, dass dieser Eisenkoloss fertiggestellt wird, {name}, da dies das Ende der Zuflucht bedeuten würde.\n\nBegebt Euch zu Narvirs Wiege, findet die von den sturmgeschmiedeten Handwerkern genutzten Blitzschmieden und sabotiert sie.", sourceObjective = "Sabotiert die Nordblitzschmiede, die Zentralblitzschmiede und die Südblitzschmiede mit Bergfels' Bomben. Kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", completion = "Ausgezeichnete Arbeit! Zwar wird das die Eisenzwerge nicht aufhalten, aber es wird sie wertvolle Zeit kosten, diese Schmieden wieder aufzubauen. Ich wage zu behaupten, dass wir nun im Vorteil sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[12989] = { id = 12989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die schleimige Dunkelheit", description = "Die niederträchtigen Jormungar haben den größten Teil der Überwinterungshöhle eingenommen. Widerwärtige Kreaturen... Kinder von Loken, Thorims verfluchtem Bruder.\n\nAls Thorims Untertanen sind wir es uns schuldig, diesen Abschaum zu töten, wo auch immer er uns unterkommt. Ihr findet die Höhle gleich östlich von hier, außerhalb des Dorfes.", sourceObjective = "Astrid Björnrittar wünscht, dass Ihr 8 gefräßige Jormungar in der Überwinterungshöhle östlich des Dorfes Brunnhildar tötet.", completion = "Die Jormungar sind abscheuliche Kreaturen. Ihr tatet gut daran, sie zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[12990] = { id = 12990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Wurmloch", description = "Bringt mir die Materialien und ich werde Euch zeigen, wie Euer Wurmlochgenerator funktioniert.Ihr erlernt:", sourceObjective = "Bringt Jonathan LeCraft die gesuchten Materialien, um einen schnellen Tod zu vermeiden, und erhaltet einen coolen neuen Zauberspruch.", sourceObjectiveStatus = "unverified-source-field" }
quests[12991] = { id = 12991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie treffen, wo es wehtut", description = "Bergfels hat vor, die Pläne der Eisenzwerge in Narvirs Wiege zu durchkreuzen, und ich habe mir dazu auch so meine Gedanken gemacht. Die Arbeit am Eisenkoloss würde ohne Fachleute zum Erliegen kommen.\n\nNarvirs Wiege liegt auf der Südseite des Hügels, der Bergfels' Zuflucht überragt. Geht dorthin und vernichtet alle sturmgeschmiedeten Konstrukteure, die Euch über den Weg laufen. Zwar sind sie nicht anders, als wir früher gewesen sind, aber sie bauen eine Waffe, die eine Gefahr für uns alle darstellt.", sourceObjective = "Tötet 10 Sturmgeschmiedete Konstrukteure und kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück.", completion = "Früher hätte ich niemanden um das bitten können, was Ihr getan habt, aber meine Erlebnisse mit den Eisenzwergen haben diese Gefühle erstickt. So haben wir sichergestellt, dass der Feind nicht allzu bald vorrücken kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[12992] = { id = 12992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tötet die Vrykul!", description = "Die Vrykul in Jotunheim müssen plattgemacht werden!\n\nUnd zwar richtig platt, {name}!", sourceObjective = "Ekel im Schattengewölbe möchte, dass Ihr 15 beliebige Vrykul in der weiteren Umgebung von Jotunheim tötet.", completion = "{name} ist mein bester, kleiner {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[12993] = { id = 12993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine kolossale Bedrohung", description = "Ihr habt Großes geleistet, als Ihr die Arbeiten beim Bau des Eisenkolosses verzögert habt. Allerdings fürchte ich, dass wir die Sturmgeschmiedeten dadurch nur noch entschlossener gemacht haben, den Bau ihrer Waffe zu vollenden.\n\nSelbst jetzt schicken sie immer noch neue Arbeiter und die Aufseher treiben sie an ihr Äußerstes. Am Ende können wir vielleicht nicht verhindern, dass sie den Koloss erwecken. Kehrt zurück zu Narvirs Wiege im Süden und findet die Dokumente, die mehr über die offensiven und defensiven Fähigkeiten des Kolosses verraten könnten. Sie sollten sich in der Nähe der Zelte und Schmieden auf der niedrigsten Ebene befinden.", sourceObjective = "Gelangt an die Informationen über die Angriffs- und Verteidigungsfähigkeiten des Kolosses und bringt sie zu Bergfels dem Steinformer in Bergfels' Zuflucht.", progress = "Konntet Ihr die Dokumente finden, nach denen wir suchen?", completion = "<Bergfels wirft mit großen Augen einen Blick auf die Dokumente.>\n\nIch hätte niemals gedacht, dass die so etwas zustande bringen können! Unsere Männer werden gegen dieses Ungetüm keine Chance haben, wenn es erst einmal fertiggestellt ist. Glücklicherweise fehlt ihnen scheinbar noch eine wichtige Komponente.", sourceObjectiveStatus = "unverified-source-field" }
quests[12994] = { id = 12994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jagd auf Spione", description = "Eure aufkeimende Beziehung zu den Einwohnern von Dun Niffelem hat zu einigen unerwarteten Entdeckungen geführt.\n\nBeispielsweise seid Ihr nun aus irgendeinem Grund in der Lage, das gutturale Knurren und die Scherze der Höhlenmutter zu verstehen, zumindest bildet Ihr Euch das ein.\n\nOffenbar spürt sie die Gefahr außerhalb der Feste und möchte, dass Ihr deswegen etwas unternehmt.\n\nMit der Vorderpfote streift sie sich die Kette vom Hals und legt sie Euch zu Füßen. Als Ihr sie aufhebt, bemerkt Ihr, dass ein Reißzahn daran befestigt ist...", sourceObjective = "Ihr müsst 3 Sturmgeschmiedete Spitzel im Uralten Wintertal besiegen.\n\nVerwendet den Fangzahn eines astralen Worgs bei der Leiche des gefallenen Worgs und beschwört damit einen astralen Frostworg, mit dessen Hilfe Ihr versteckte Feinde entlarven könnt. Wenn das Tal von den Spionen befreit wurde, sollt Ihr zur Frostworghöhlenmutter in Dun Niffelem zurückkehren.", progress = "Die Frostworghöhlenmutter sieht Euch neugierig an.", completion = "Als Ihr der Höhlenmutter die Kette wieder um den Hals legt, leckt sie Euer Gesicht wohlwollend ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[12995] = { id = 12995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt ein Zeichen", description = "Wir müssen den Vrykul von Jotunheim auf vielerlei Arten begegnen. Pure Gewalt ist natürlich angebracht, aber ich bevorzuge eine intelligentere Herangehensweise.\n\nIch möchte, dass Ihr sie zermürbt.\n\nMeine Männer haben einige Banner für Euch angefertigt. Nehmt sie und rammt sie in den Boden neben den Leichen gefallener Vrykul.\n\nLasst die Banner zu einer dauerhaften Mahnung gereichen, dass sie einer akuteren Bedrohung gegenüberstehen als dem Zorn des Lichkönigs.", sourceObjective = "Baron Splitter im Schattengewölbe wünscht, dass Ihr 15 Banner der Schwarzen Klinge in die Nähe der Vrykulleichen steckt, die Ihr in der weiteren Umgebung von Jotunheim findet.", completion = "Gut gemacht, {name}. Mögen sie die geschändeten Leichen ihrer gefallenen Kameraden erblicken und es sich lieber zwei Mal überlegen, uns anzugreifen!\n\nWenn Ihr morgen wieder kommt, werde ich dafür Sorge tragen, dass weitere Banner für Euch bereitstehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12996] = { id = 12996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Aufwärmen", description = "Ihr hattet großes Glück, Schwester. Dies ist eine Matriarchin, wie wir sie seit Jahren nicht mehr gesehen haben.\n\nEin guter Bär würde Euch nicht viel bringen, wenn Ihr nicht auf ihm reiten könnt.\n\nIch werde Euch auf Kirgaraak einiges zeigen. Er ist der größte Yeti, den wir je fangen konnten, also seid lieber vorsichtig. Und geht ruhig weg, wenn er Euch verprügeln will... denn wir halten ihn aus gutem Grund an einer Kette.", sourceObjective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr die Zügel der Kriegsbärenmatriarchin nutzt, um Kirgaraak zu besiegen.", progress = "Wie ist es mit dem Yeti gelaufen?", completion = "Nicht übel. Ich hatte gehofft, dass Euch Kirgaraak den Hals bricht, damit ich Euren Bären behalten kann.\n\nDas war bloß ein Scherz, Schwester. Nun... zumindest teilweise. Ihr habt da einen wirklich schönen Bären.", sourceObjectiveStatus = "unverified-source-field" }
quests[12997] = { id = 12997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In die Grube", description = "Einen angebundenen Gegner zu bezwingen, ist eine Sache; gegen ebenbürtige Bärenreiter zu kämpfen, eine andere.\n\nBegebt Euch in die Reißzahngrube und wendet das an, was Ihr gelernt habt, um Eure Gegner zu besiegen. Viel Glück, Schwester.\n\nRuhm erwartet Euch, falls Ihr siegen solltet.", sourceObjective = "Astrid Björnrittar aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Kriegsbärenmatriarchin 6 Kriegsbären des Hildarthings besiegt.", progress = "Seid gegrüßt, Schwester.", completion = "Ihr habt es wirklich geschafft! Und Ihr seid bei bester Gesundheit. Wenn man von der Bärin doch nur dasselbe sagen könnte.\n\nEs wird eine Weile dauern, bis sie sich wieder erholt hat. Zum Glück werdet Ihr sie vorerst nicht brauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12998] = { id = 12998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz des Sturms", description = "Laut den Dokumenten, die Ihr aus Narvirs Wiege erbeuten konntet, ist der Eisenkoloss fast fertiggestellt. Es fehlt nur noch ein wichtiger Bestandteil - das Herz des Sturms.\n\nOhne diese Komponente wären die Waffen des Eisenkolosses weitaus schwächer als im Konzept dieses Ungetüms vorgesehen. Wenn wir Aufseher Narvir daran hindern, an das Herz zu gelangen, können wir den Koloss vielleicht besiegen!\n\nNotizen auf dem Dokument, das Ihr gefunden habt, besagen, dass sich das Herz in Uldis befindet, einer Titanenanlage weit im Süden. Den Eingang findet Ihr auf der südlichen Seite eines großen Berges, der den Strom Bors Atem überragt.", sourceObjective = "Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr nach Uldis reist und versucht, Aufseher Narvir daran zu hindern, an das Herz des Sturms zu gelangen.", completion = "Das Herz in Narvirs Besitz wird dem Koloss seine volle Stärke verleihen! Wir werden keine andere Wahl haben als zu versuchen, uns dagegen zur Wehr zu setzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[12999] = { id = 12999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Knochenhexe", description = "Ihr erinnert Euch doch noch an Lady Nachtwald, oder? Sie hat Euch auf jeden Fall nicht vergessen. Sie ist die verzweifelte und sehr erzürnte Banshee, die Ihr 'gerettet' habt, als Ihr auch Ekel und mich von der Herrschaft des Lichkönigs befreit habt.\n\nDie Lady ist nach Jotunheim gegangen und hat ihre Knochenhexe unter ihre Kontrolle gebracht. Sie will bei den Vrykul von innen heraus Chaos und Verwüstung anrichten.\n\nSie möchte, dass Ihr sie aufsucht. Ihr findet sie in der Höhle auf der südlichen Seite des Dorfes Njorndar im Südwesten von Jotunheim.", sourceObjective = "Sprecht mit der Knochenhexe in der Höhle des Dorfes Njorndar.", completion = "{name}, Ihr seid gekommen.\n\nIch habe schon von Euren Taten auf der Wilden Klippe gehört. Das ist gut. Ich bin froh, dass Ihr mir anscheinend dabei helfen wollt, die Vrykul hier in Jotunheim zu untergraben.\n\n\n\nWir beide werden mit ihnen eine Menge Spaß haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[13000] = { id = 13000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notfallmaßnahmen", description = "In diesen Bergen herrscht eine unerbittliche Kälte. Uns bleiben noch ein oder zwei Tage, bis das Holz des Wracks für das Feuer aufgebraucht ist.\n\nIn der Höhle gleich östlich von hier haben wir Worgs gesehen. Findet die Höhle und bringt von dort einige Felle mit. Das klingt zwar nicht nach einer viel versprechenden Beute, könnte jedoch den Unterschied zwischen Erfrieren und Weiterleben ausmachen.\n\nWorgs jagen nicht alleine, daher gebe ich Euch ein Leuchtfeuer. Es sollte Euch ein wenig Zeit verschaffen, falls Ihr gegen die Worgs in Unterzahl seid.", sourceObjective = "Blutwache Lorga bittet Euch, zu Gimoraks Bau im Osten zu gehen und von dort 6 Worgfelle mitzubringen.", progress = "Habt Ihr die Felle?", completion = "Diese Felle sind ziemlich... groß. Die Worgs, die Ihr dafür erlegen musstet, möchte ich nur ungern zu Gesicht bekommen.\n\nWir sind Euch sehr dankbar. Es wird nämlich schon kälter.", sourceObjectiveStatus = "unverified-source-field" }
quests[13001] = { id = 13001, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hodirs Speer schmieden", description = "Die Zeit ist gekommen, <kleiner/kleine:c> {class}. Die Sterne haben diesen Tag vorausgesagt.\n\nIch erhielt eine Eingebung vom mächtigen Hodir persönlich, die mir das Geheimnis zum Bau eines mächtigen Artefakts offenbarte.\n\nWir müssen gehorchen! Wenn wir dieses Geschenk nicht anzunehmen wissen, droht uns sicher der Untergang.\n\nIch appelliere an Euch, mir bei diesem heiligen Unterfangen zur Seite zu stehen.\n\nBegebt Euch zur Überwinterungshöhle auf der anderen Seite des Tals und sammelt im eisigen Krater dort Immerfrostsplitter. Danach sammelt Bälge von den Mammuts außerhalb der Höhle.", sourceObjective = "Wissenshüter Randvir aus Dun Niffelem möchte, dass Ihr 3 Immerfrostsplitter aus den Tiefen der Überwinterungshöhle sowie 3 Bälge ruhiger Mammuts aus dem Uralten Wintertal holt.", progress = "Konntet Ihr die Materialien für den Speer besorgen, {race}?", completion = "Tretet zurück, {race}, und werdet Zeuge der Erfüllung einer Prophezeiung!", sourceObjectiveStatus = "unverified-source-field" }
quests[13002] = { id = 13002, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine perfektionieren", description = "Willkommen in der Kälte, Mann. Der Ort hier is' vielleicht nicht gerade der wärmste, doch ich habe gelernt, wie man den perfekten Edelstein schleift. Alles, was ich dazu brauche, sind ein paar Edelsteine, an denen ich arbeiten kann.\n\nBring mir ein paar Edelsteine und ich werde dir beibringen, wie man Edelsteine perfektioniert. Das wird dir dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn du einen Edelstein aus Nordend von seltener Qualität schleifst.", sourceObjective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Geba'li in der Kriegshymnenfeste.", progress = "Danach habe ich gesucht. Jetzt werde ich dir beibringen, wie man Edelsteine perfektioniert.", completion = "Die sind perfekt, Mann. Nun werde ich dir beibringen, wie man Edelsteine perfektioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[13003] = { id = 13003, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachentöten leicht gemacht", description = "Hodirs Speer ist ein Symbol für großen Heldenmut im Kampf.\n\nSchon seine bloße Anwesenheit ruft in jedem, der nach Dun Niffelem kommt, das Verlangen nach Ruhm hervor. Ihr wart bloß in seiner Nähe und saht Euch berufen, Eure Fertigkeiten auf die Probe zu stellen.\n\nIhr sucht den Horizont ab und erblickt einen vorbeifliegenden Wildwyrm.\n\nEs ist entschieden. Von Euch beiden wird nur einer den nächsten Sonnenaufgang erleben...", sourceObjective = "Ihr sollt mit Hodirs Speer einen Wildwyrm im Uralten Wintertal herausfordern. Wenn Ihr ihn getroffen habt, muss es zu einem Kampf auf Leben und Tod kommen.", completion = "Es ist vollbracht.\n\nIhr habt dem sicheren Tod ins Auge geblickt und seid siegreich daraus hervorgegangen.\n\nIndem Ihr allein eine solch mächtige Bestie besiegt habt, konntet Ihr Dun Niffelem eine große Ehre erweisen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13004] = { id = 13004, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Edelsteine perfektionieren", description = "Es ist Krieg und jeder von uns muss seinen Teil dazu beitragen! Meine Aufgabe ist das Schleifen von Edelsteinen. Ich kann nicht nur normale Edelsteine schleifen, sondern auch perfekte. Wenn Ihr Euren Beitrag leisten wollt und mir ein paar ungeschliffene Edelsteine bringt, kann ich Euch auch beibringen, wie man sie perfektioniert. Das wird Euch dann erlauben, in manchen Fällen einen perfekten Edelstein mit erhöhten Boni herzustellen, wenn Ihr einen Edelstein aus Nordend von seltener Qualität schleift.", sourceObjective = "Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Alestros in der Valianzfeste.", progress = "Eure Spende wird sehr geschätzt. Lasst mich Euch beibringen, wie man Edelsteine perfektioniert.", completion = "Habt Dank. Ich werde Euch eine Schleiftechnik beibringen, mit der Ihr Edelsteine perfektionieren könnt, und Euch einen von meinen perfekt geschliffenen Edelsteinen geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13005] = { id = 13005, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eid der Irdenen", description = "Jahrelang vernachlässigte ich meine Pflichten, erging mich in Pein und Selbstmitleid.\n\nNicht so die tapferen Irdenen. Ihr Eid, diesen Grund und Boden unter Einsatz ihres Lebens zu beschützen, blieb ungebrochen.\n\nSelbst jetzt bekämpfen sie die Verderbnis des Eisens selbstlos und warten auf den Augenblick, an dem sich das Blatt wendet.\n\nDieser Augenblick ist gekommen. Wir müssen die Kräfte aller verbliebenen Irdenen Verteidiger bündeln und sie zu einem glorreichen Sieg führen. Lasst das Horn der Sturmgipfel ertönen, um sie an Eure Seite zu rufen und die Terrasse der Schöpfer zurückzuerobern.", sourceObjective = "Thorim, auf der Terrasse der Schöpfer, wünscht, dass Ihr in das Horn der Sturmgipfel blast und die Irdenen ruft, damit sie 20 Eisenzwerge und 7 Eisenschildwachen besiegen.", progress = "Seid gegrüßt, {name}! Welche Neuigkeiten bringt Ihr mir?", completion = "Das ist ein guter Anfang. Aber es wird nicht lange dauern, bis sich die Streitkräfte meines Bruders neu formiert haben. Unser Sieg muss ein alles entscheidender Sieg werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13006] = { id = 13006, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine schmierige Säuberung", description = "Als Ihr Euch dem Helm nähert, merkt Ihr, dass die eisige Umgebung der Oberfläche des Artefaktes bereits zugesetzt hat. Schon jetzt bedeckt ihn eine dünne Eisschicht, doch schon bald wird er komplett eingefroren sein.\n\nDa Ihr nicht wollt, dass all Eure Anstrengungen vergebens waren, entschließt Ihr Euch, in der Gegend nach einer Lösung zu suchen.\n\nAls Ihr Euch gerade abwenden wollt, blitzen die Augen des Helms auf und ein Bild der nahegelegenen Überwinterungshöhle erscheint in Eurem Geist.", sourceObjective = "Ihr müsst Euch in die Überwinterungshöhle westlich von Dun Niffelem begeben und 5 Einheiten viskoses Öl vom Rohöl dort besorgen.\n\nKehrt dann nach Dun Niffelem zurück und tragt das Öl auf Hodirs Helm auf.", progress = "Ihr beobachtet, wie sich auf dem Helm eine dicke Schicht Eis und an seinen Kanten Eiszapfen bilden...", completion = "Als Ihr den Helm mit einer dünnen Ölschicht benetzt, verschwindet das Eis und die Oberfläche beginnt zu glänzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13007] = { id = 13007, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eisenkoloss", description = "Wir konnten leider nicht verhindern, dass der Eisenkoloss fertiggestellt wird, {name}, und das bedeutet, dass wir keine andere Wahl haben, als uns ihm im Kampf zu stellen.\n\nBruor hat einen Plan, wie wir die einzige Schwäche des Kolosses ausnutzen können.\n\nWie robust seine Panzerung auch sein mag, so vermag Jormungar-Säure sie doch zu schädigen. Übernehmt mithilfe der Kugeln am Nordrand der Verschneiten Ebenen die Kontrolle über einen Jormungar und setzt die Säure ein, um den Eisenkoloss auf der verschneiten Ebene zu vernichten. Falls Ihr Hilfe bei der Kontrolle Eurer Kreatur benötigt, sprecht mit einem der Tierführer in der Nähe.", sourceObjective = "Nutzt einen gezähmten Jormungar, um den Eisenkoloss zu besiegen, und kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück.", completion = "Wir haben es geschafft, es ist wirklich vollbracht! Die Zuflucht wurde verschont und die Sturmgeschmiedeten sind besiegt! Wir müssen Brann warnen, bevor Loken auf die Idee kommt, seine Truppen neu aufzubauen. Wir können diesen Sieg, den Ihr heute für uns errungen habt, nur sichern, indem wir nach Ulduar gehen und Loken ein für alle Mal besiegen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13008] = { id = 13008, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Taktik der Geißel", description = "Das Überraschungsmoment war auf unserer Seite! Wir sprengten einen Durchgang in die Bergwand und fielen in Geißelholme ein. Die Streitkräfte der Geißel kämpften erbittert und es dauerte nicht lange, bis wir überwältigt wurden. Wir wurden ins Tal zurückgedrängt und begannen damit, mit Artillerie auf die Verfolger der Geißel zu schießen. Wir konnten sie dadurch einige Zeit aufhalten, bis... diese Monster damit begannen, unsere Kreuzfahrer als lebende Schutzschilde zu missbrauchen. Aus Angst, unsere eigenen Soldaten zu töten, mussten wir den Beschuss einstellen.\n\nBefreit unsere Kreuzfahrer, die auf dem Feld außerhalb des Camps gefangen sind, {class}!", sourceObjective = "Kreuzzugskommandant Entari in der Argentumvorhut von Eiskrone bittet Euch, 5 eingesponnene Kreuzfahrer zu befreien.", completion = "Nach wie vor befinden sich viele Argentumkreuzfahrer dort draußen auf dem Feld und in Geißelholme, {name}. Für Eure Hilfe sei Euch gedankt, aber es gibt immer noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13009] = { id = 13009, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Neuanfang", description = "Es steht weiterhin in den Sternen, ob unser Volk jemals wieder die Sympathie aufleben lassen kann, die es Thorim einst entgegenbrachte.\n\nMöge diese Rüstung - wenn schon nichts anderes - ihn an die Tage erinnern, als wir gemeinsam unbesiegbar und ehrenvoll auf dem Schlachtfeld standen.", sourceObjective = "Njormeld wünscht, dass Ihr die neugeschmiedete Rüstung zu Thorim im Tempel der Stürme bringt.", progress = "Waren Eure Bemühungen erfolgreich, {class}?", completion = "<Als Ihr Thorim die neugeschmiedete Rüstung übergebt, ist er sichtlich ergriffen ob ihres Glanzes.>\n\nDas habt Ihr gut gemacht, {race}, aber es gibt noch viel zu tun.", sourceObjectiveStatus = "unverified-source-field" }
quests[13010] = { id = 13010, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krolmir, Hammer der Stürme", description = "Eine Aufgabe bleibt noch, bevor ich mein Heim an der Terrasse der Schöpfer zurückerobern kann.\n\nKrolmir muss gefunden werden.\n\nAn diesem schicksalhaften Tag warf ich ihn mit all meiner Macht und voller Zorn auf die Erde, worauf es zu einer gewaltigen Explosion kam.\n\nAll die Jahre dachte ich, ich hätte ihn verloren, aber nun muss ich Gewissheit haben.\n\nKehrt zu König Jokkum zurück und findet heraus, ob er etwas über das Schicksal meines Hammers weiß.", sourceObjective = "Thorim möchte, dass Ihr mit König Jokkum in Dun Niffelem sprecht und in Erfahrung bringt, was er über Krolmir weiß.", progress = "Schon zurück, kleiner {race}?", completion = "Ich bin Euch wirklich sehr dankbar, {class}.\n\nIhr habt mir ehrenvoll gedient. Bitte nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13011] = { id = 13011, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jorkuttar töten", description = "Mir schwebt da eine Möglichkeit vor, wie Ihr unter meinesgleichen Anerkennung finden könntet, vorausgesetzt, Ihr seid erfolgreich.\n\nDie Jormungar sind eine Plage, um die man sich am besten schnell kümmern sollte. Wenn man sie auch nur ein wenig in Ruhe lässt, dann vermehren sie sich wie die Hasen und verbreiten sich wie Feuer.\n\nSie sind südwestlich von hier aufgetaucht, in der Überwinterungshöhle. Wenn Ihre Brutmutter nicht schon bald getötet wird, werden sie sich in unserer Gegend festsetzen.\n\nEtwas zu fressen kann sie nicht verschmähen. Nehmt dieses Messer, geht zu der Höhle und besorgt Euch die Flanke eines toten Bären. Legt das Fleisch in die Nähe ihres Kraters und tötet sie, wenn sie gerade dabei ist, sich satt zu fressen.", sourceObjective = "König Jokkum in Dun Niffelem möchte, dass Ihr in die Überwinterungshöhle geht und Jorkuttar niederstreckt.", progress = "Habt Ihr Jorkuttar getötet?", completion = "Es ist also vollbracht.\n\nJorkuttars Schreie sind durchs ganze Tal gehallt.\n\nIhr habt meinem Volk heute einen großen Dienst erwiesen, kleiner {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13012] = { id = 13012, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Sardis", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren. Ich wünsche Euch alles Gute, {name}, und biete Euch diese Marke als Geschenk...", sourceObjectiveStatus = "unverified-source-field" }
quests[13013] = { id = 13013, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Beldak", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
