quests[13033] = { id = 13033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Arp", sourceObjective = "Ich spüre das Feuer des Lebens in Euch, {class}. Ich akzeptiere Eure Ehrerbietung! Nehmt dies als Zeichen meiner Dankbarkeit...", sourceObjectiveStatus = "unverified-source-field" }
quests[13034] = { id = 13034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zeuge und der Held", description = "Als ich meine Reisen in Nordend angetreten hatte, besuchte ich die Boreanische Tundra und traf zum ersten Mal mit den Taunka zusammen. Dort erzählte mir Windzähmerin Barah die Geschichte von Sturmhuf und seinem Kampf gegen den Nordwind, dem uralten Gegner seines Volkes.\n\nIch machte mich auf zu den Sturmgipfeln, um mehr über diesen Helden in Erfahrung zu bringen, aber seltsamerweise scheinen die Leute in Tunka'lo nichts über ihn zu wissen.\n\nVielleicht werden uns die eigenen Aufzeichnungen des Camps mehr Aufschluss darüber geben. Findet und lest die historischen Schriftrollen, die verteilt im ganzen Lager aufbewahrt werden und berichtet mir anschließend, was Ihr erfahren habt.", sourceObjective = "Xarantaur im Camp Tunka'lo möchte, dass Ihr Euch die erste, zweite und dritte historische Schriftrolle durchlest.", completion = "Äußerst merkwürdig... das klingt nicht nach der Geschichte, die Windzähmerin Barah mir erzählt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13035] = { id = 13035, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lokens Lakaien", description = "Für meinen Bruder war der Angriff auf die Terrasse der Schöpfer keine halbherzige Aktion: Er entsandte eine Legion von Eisenzwergen und einige seiner mächtigsten Leutnants dorthin.\n\nBenutzt das Horn der Sturmgipfel, um die Irdenen zu Hilfe zu rufen und Lokens Diener zu vernichten.\n\nIm Inneren der Halle des Formers gen Norden werdet Ihr den Riesen Eisenfaust finden. Die anderen befinden sich tiefer im Inneren der Terrasse der Schöpfer, jenseits der Treppen im Nordwesten.", sourceObjective = "Thorim möchte, dass Ihr Eisenfaust in der Halle des Formers erschlagt. Außerdem sollt Ihr Halefnir den Zischenden und Duronn den Runenbesetzten auf der Terrasse der Schöpfer töten.", progress = "Es ist gut, Euch wiederzusehen, {name}.", completion = "Einer nach dem anderen sind sie gefallen, die Diener meines Bruders. Lokens Aufstand wird schon bald ein Ende finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13036] = { id = 13036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehre über alles", description = "Es war ein langer, beschwerlicher Weg bis zu unserer Errettung, <junger/junge:c> {class}. Wir sind bei unseren Kämpfen durch ganze Kontinente, ja sogar Welten gezogen, um an diesen Punkt zu gelangen. Jetzt stehen wir vor unserer größten Herausforderung: Die Vernichtung des Lichkönigs und seiner Geißel.\n\nAber leider müssen wir diese Schlacht getrennt voneinander durchstehen. Die Horde und die Allianz stehen kurz vor einem Krieg und können uns keine Unterstützung zusichern. Wir müssen in unserer Sache unnachgiebig bleiben! Was bleibt uns auch anderes übrig?\n\nWerdet Ihr Euch unserer Sache anschließen? Lasst uns Eure Stärke zuteilwerden, {class}! Mein Kommandant Entari erwartet Euch auf seinem Posten.", sourceObjective = "Meldet Euch bei Kreuzzugskommandant Entari in der Argentumvorhut in Eiskrone.", completion = "Wo sowohl die Allianz als auch die Horde scheiterten, war der Argentumkreuzzug erfolgreich. Allerdings war dieser Erfolg nur von kurzer Dauer. Unser Vorstoß nach Eiskrone war schnell und gewaltsam... zurückgeschlagen worden...\n\nDer Vergeltungsschlag des Lichkönigs kam unverzüglich und mit brutaler Härte. Jetzt sind wir in der Defensive.", sourceObjectiveStatus = "unverified-source-field" }
quests[13037] = { id = 13037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erinnerungen an Sturmhuf", description = "Als mir der bronzene Drachenschwarm die Unsterblichkeit schenkte und mich auf den Weg des Zeugen schickte, vertraute mir Nozdormu den Lehrenhammer an.\n\nDie Reaktion des Hammers auf Euren Fund sagt mir, dass die Zeit hier nicht richtig verlaufen ist und wir die richtige Zeitlinie wiederherstellen müssen.\n\nWir müssen sie finden. Im Nordwesten liegt die Frostschollentiefe, eine uralte Begräbnishöhle der Krieger von Tunka'lo. Sucht den Geist von Häuptling Schnellspeer, Sturmhufs Bruder. Fragt ihn, was ihm vom Kampf seines Bruders gegen den Nordwind in Erinnerung geblieben ist.", sourceObjective = "Sprecht mit Häuptling Schnellspeer in der Frostschollentiefe und kehrt dann zu Xarantaur ins Camp Tunka'lo zurück.", completion = "Sogar der Häuptling beginnt, seine Erinnerungen zu verlieren? Die Vergangenheit wird vor unseren Augen neu geschrieben, und wenn wir nicht herausfinden, wer dahintersteckt, dann könnte Sturmhufs Erbe für immer verloren sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13038] = { id = 13038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verzerrungen in der Zeit", description = "Dieses Grab der Tunka'lo-Krieger sollte ein ruhevoller Ort sein, der vor den Schrecken der Elemente geschützt ist.\n\nDie Frostschollentiefe wurde von einer seltsamen Kraft befallen, die die Geister der Gefallenen in Unruhe versetzt und die Erinnerungen an mein Leben durcheinander bringt.\n\nEs ist, als würden unsere Taten und Erinnerungen aus der Geschichte getilgt.\n\nZu Lebzeiten war dieses Totem ein Zeichen meiner Autorität. Es ist die letzte wirkliche Verbindung, die ich noch zu dieser Welt habe. Nehmt es und nutzt es, um die Ruhe dieses Grabes wiederherzustellen, und bringt es danach ins Camp Tunka'lo zurück.", sourceObjective = "Nutzt das Totem des Häuptlings, um 4 Frostschollenklüfte zu schließen, und bringt es danach zu Xarantaur ins Camp Tunka'lo.", progress = "Was habt Ihr aus dem Grab mitgebracht?", completion = "Der Geist des Häuptlings hat Euch gesagt, dass Ihr mir das hier bringen sollt?\n\n<Xarantaur untersucht das Totem.>\n\nAh, jetzt verstehe ich, was er beabsichtigt hat. Als er Euch auftrug, Ihr sollt mit diesem Totem die Klüfte in der Tiefe schließen, hat er uns einen Hinweis darauf gegeben, was mit der Zeitlinie geschieht. Schnellspeer ist ein weiser Häuptling, der noch im Tode über sein Volk wacht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13039] = { id = 13039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Vorhut verteidigen", description = "Wir können nicht in dem Tempo weitermachen. Sobald die Bresche in die Luft gesprengt wurde, öffneten sich die Fluttore. Seitdem fällt die Geißel über uns her, und es nimmt kein Ende!\n\nWir brauchen jede fähige Hand, um die Angreifer abzuwehren. Geht da raus und leistet Euren Beitrag, Freund. Tötet so viele Monster, wie Ihr nur könnt!", sourceObjective = "Kreuzfahrerlord Dalfors von der Argentumvorhut in Eiskrone hat Euch gebeten, 15 Neruber der Vergessenen Tiefen zu töten.", progress = "Gebt nicht auf, {name}!", completion = "Wie viele von ihnen gibt es denn noch? Wir haben genug getötet, um zehn Friedhöfe zu füllen, und trotzdem kommen immer mehr. Die Lage sieht ernst aus, Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[13040] = { id = 13040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heilmittel für das Unheilbare", description = "Täglich steigt die Anzahl verwundeter Soldaten. Sie werden von einer Art Gift niedergestreckt, das uns bisher gänzlich unbekannt ist. Was auch immer diese Neruber da in ihren Giftdrüsen haben, es ist unheilbar und bringt den Tod! Bisher konnten wir nur die Verbreitung des Gifts im Körper des Opfers verlangsamen. Wir müssen jedoch ein Heilmittel finden!\n\nWagt Euch in Richtung Nordwesten zum Tal außerhalb des Vorpostens und tötet die Neruber der Vergessenen Tiefen. Nehmt ihre Giftdrüsen und bringt sie zu mir.", sourceObjective = "Vater Gustav aus der Argentumvorhut in Eiskrone bittet Euch, ihm 10 Giftdrüsen der Vergessenen Tiefen zu bringen.", progress = "Konntet Ihr die Giftdrüsen beschaffen, {race}?", completion = "Habt Dank, {name}. Ich werde sofort mit der Untersuchung dieser Proben beginnen. Ich hoffe, dass bald ein Heilmittel gefunden werden kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13041] = { id = 13041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Lieferung abfertigen", description = "Freut mich, dass Ihr hier seid! Eine Lieferung leuchtender Elfenbeinfiguren muss so schnell wie möglich nach Lorenhall geschickt werden und mir fehlt noch ein Chalzedon für das Auge der letzten Statuette.\n\nBringt mir einen davon und ein Juwelierssymbol von Dalaran gehört Euch.", sourceObjective = "Bringt einen Chalzedon zu Jonas Timotheus in Dalaran.", progress = "Habt Ihr schon einen Chalzedon gefunden?", completion = "Hier, wie versprochen: Euer Juwelierssymbol von Dalaran. Bei mir gehen die ganze Zeit Lieferungen raus, schaut also ab und zu vorbei und seht nach, was ich so brauche.", sourceObjectiveStatus = "unverified-source-field" }
quests[13042] = { id = 13042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tief im Inneren des Kellergewölbes", description = "Tief im Inneren des Kellergewölbes im Nordosten heckt ein verrückter Wissenschaftler, bekannt unter dem Namen Dr. Maböse, etwas aus, das seinem Namen alle Ehre macht.\n\nDer Doktor bekam die Erlaubnis des Lichkönigs, Experimente mit Varguls durchzuführen - den Vrykul, die im Kampf fallen, als unwürdig erachtet werden und dann der Geißel anheim fallen.\n\nWir müssen seiner Arbeit ein Ende machen, meine Wahrsager konnten ihn jedoch nicht aufspüren. Allerdings hat er einen Assistenten.\n\nPrügelt aus seinem Lehrling alle Informationen heraus und lasst ihn dann verschwinden.", sourceObjective = "Die Knochenhexe aus Njorndar bittet Euch, Informationen bezüglich der Pläne von Dr. Maböse aus Lehrling Osterkilgr herauszuprügeln.\n\nTötet den Lehrling anschließend.", completion = "Interessant. Wie es scheint, konntet Ihr den Auftrag zu meiner vollsten Zufriedenheit erledigen. Es überrascht mich, dass der Doktor einen Vargul als Assistenten hatte, wenn man bedenkt, mit welchen Kreaturen er experimentierte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13043] = { id = 13043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ganze ist größer als die Summe seiner Teile", description = "Ihr öffnet den Folianten und erblickt verschiedene widerwärtige Illustrationen dessen, was der Doktor \"die ultimative Waffe\" nennt!\n\nDer Prototyp Nergeld ist offenbar der gewaltige Fleischriese, der am Ende der naheliegenden Hallen des Grauens steht.\n\nWürde eine Armee dieser Kreationen gebaut, dann wäre das der sichere Untergang. Wir können nur sicherstellen, dass dies nicht geschieht, indem wir Dr. Maböse vernichten!\n\nVielleicht zeigt sich der Doktor, wenn Ihr die Kontrolle über dieses Konstrukt übernehmt?", sourceObjective = "Besteigt Nergeld und übernehmt die Kontrolle. Verteidigt ihn vor den Bewohnern der Hallen des Grauens, bis sich Dr. Maböse zeigt.\n\nNutzt Nergeld, um den Doktor zu vernichten, und kehrt dann zur Knochenhexe nach Njorndar zurück.", progress = "Ihr habt das Buch des Doktors mitgebracht, ihn aber nicht mithilfe des Fleischriesen vernichtet?\n\nGeht sofort zurück und tötet ihn, bevor es zu spät ist!", completion = "Ihr habt die Machenschaften des Doktors enttarnt und ihnen ein Ende bereitet.\n\n<Die von der Banshee besessene Hexe lächelt und legt Euch sanft ihre große Hand auf die Schulter.>\n\nDa haben wir dem Lichkönig aber einen schönen Schlag versetzt, allerdings denke ich, dass wir das noch besser können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13044] = { id = 13044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Falls es Überlebende gibt...", description = "Jenseits des Tals der Echos westlich von hier und auf der anderen Seite der Bresche liegt das erste Lager der Geißel in Eiskrone, das Geißelholme genannt wird. Wir haben dort gut gekämpft und viele Krieger der Geißel getötet, aber letzten Endes wurden wir zum Rückzug gezwungen. Dabei mussten wir viele Soldaten zurücklassen, über deren Schicksal uns nichts bekannt ist.\n\nFalls es Überlebende gibt, müssen wir versuchen, sie zu retten. Wenn Ihr diesen Südostpfad nehmt, gelangt Ihr zu Penumbrius, einem Verbündeten des bronzenen Drachenschwarms und Hüter der Protodrachenbrut. Sucht ihn auf und bittet ihn um Hilfe.", sourceObjective = "Sprecht mit Penumbrius in der Argentumvorhut in Eiskrone.", completion = "<Penumbrius nickt.>\n\nMein Volk wird Euch helfen. Gemeinsam werden wir gegen den Lichkönig und seine untoten Legionen kämpfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13045] = { id = 13045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ins wilde Grün", description = "Wir werden tun, was wir können, um Euch zu helfen, {name}. Die Protobrut hat sich bereit erklärt, Euch durch die Bresche nach Geißelholme zu fliegen. Rettet alle gefangenen Argentumkreuzfahrer, die Ihr findet. Bringt sie sodann ins Feldlazarett der Vorhut, das sich inmitten dieser Basis befindet.\n\nWählt eine der Argentumhimmelsklauen aus dem Gatter hinter mir aus und fliegt los!\n\nGeißelholme liegt nordwestlich von hier auf der anderen Seite des Tals der Echos, jenseits der großen Bresche.", sourceObjective = "Rettet 3 gefangene Argentumkreuzfahrer aus Geißelholme und bringt sie ins Feldlazarett im Zentrum des Argentumvorpostens. Berichtet Hochlord Tirion Fordring danach von Eurem Erfolg.", progress = "Mit jeder Minute, die verstreicht, sinkt ihre Chance zu überleben.", completion = "Arthas... Er schlägt rücksichtslos zu - ohne nachzudenken oder Vorsicht walten zu lassen. Wir konnten ihn überrumpeln.\n\n<Hochlord Tirion Fordring hält gedankenverloren inne.>\n\nWir werden unsere Verteidigung verstärken und dem Sturm trotzen.\n\nWie gut könnt Ihr mit einer Kanone umgehen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[13046] = { id = 13046, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Arngrim füttern", description = "Arngrims Hunger war legendär.\n\nSogar im Tode gleicht sein Gesichtsausdruck dem eines Hungernden. Ihr stellt fest, dass Euer Magen anfängt zu knurren, wenn Ihr ihn auch nur anseht.\n\nEs heißt, dass er im Leben nie wirklich satt war und dass es absolut nichts gab, was er nicht gegessen hätte. Ihr fragt Euch, ob es einen Weg gibt, den alten König zu füttern.\n\nWährend Ihr noch überlegt, fällt einer von Arngrims gewaltigen gefrorenen Zähnen aus, prallt von seinem Bart ab und landet in Eurer Hand.", sourceObjective = "Ihr sollt 5 körperlose Jormungar an Arngrim verfüttern und dann zu Arngrims gefrorenem Abbild in Dun Niffelem zurückkehren.\n\nIhr müsst ins Uralte Wintertal gehen und Arngrims Zahn auf die dort herumstreunenden Jormungar anwenden. Sobald sie eine körperlose Form angenommen haben, müsst Ihr sie bekämpfen, bis sie geschwächt sind.", completion = "Als Ihr den Zahn in Arngrims Kiefer verankert, habt Ihr den Eindruck, dass Eure Bemühungen den Hunger des alten Königs gestillt haben... vorerst zumindest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13047] = { id = 13047, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Abrechnung", description = "Loken hat meine Frau getötet und meine Anhänger gegen mich aufgewiegelt. Er hat mir alles genommen, was ich hatte, doch heute... wird sich das ändern.\n\nHeute werden wir unseren geheiligten Boden zurückerobern. Heute... wird Loken sterben.\n\nTrefft mich auf der Brücke in der Nähe des Tempels der Weisheit gleich südwestlich von Ulduar. Ich werde dies zu Ende bringen, so oder so.\n\nIch brauche Euch als Zeugen. Ihr werdet mir nicht helfen - das ist eine persönliche Angelegenheit.\n\nBenachrichtigt Jokkum, den König der Frostriesen, sobald die Sache erledigt ist. Er ist ein guter Freund und wird wissen, was zu tun ist.", sourceObjective = "Trefft Euch mit Thorim in der Nähe des Tempels der Weisheit. Berichtet König Jokkum in Dun Niffelem, wie der Kampf ausgegangen ist.", completion = "Nein... das darf nicht wahr sein...\n\nNiemand kann Thorim im Einzelkampf besiegen - weder Riese noch Bestie... niemand! Ganz besonders nicht sein feiger Bruder.\n\nBei den Namen meiner Vorväter schwöre ich...\n\nLoken wird dafür büßen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13048] = { id = 13048, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo die Zeit aus dem Ruder lief", description = "Der Lehrenhammer kann uns helfen, den Schaden, den die Zeitlinie genommen hat, zu korrigieren, aber dafür müssen wir erst herausfinden, wo die Geschichte das erste Mal verändert wurde.\n\nDank Häuptling Schnellspeer und Eurer Erkenntnisse aus der Frostschollentiefe wissen wir, dass die Veränderung etwa zur Zeit von Sturmhufs Tod stattfand.\n\nNun müsst Ihr zur Heulenden Senke nördlich des Lagers gehen und die Grabstätten untersuchen, die von den Dienern des Nordwinds schon zerstört wurden. Der Lehrenhammer wird auf die Artefakte aus Sturmhufs Zeit reagieren und sich selbst auf die richtige Zeit einstellen.", sourceObjective = "Setzt den Lehrenhammer bei den Taunka-Relikten ein, um ihn an Sturmhufs Zeit anzupassen. Kehrt zu Xarantaur nach Camp Tunka'lo zurück, wenn er auf 6 Relikte aus Sturmhufs Zeit eingestimmt wurde.", progress = "Habt Ihr den Lehrenhammer auf Sturmhufs Zeit eingestimmt?", completion = "<Xarantaur nimmt Euch den Lehrenhammer ab.>\n\nZumindest konnten wir bestimmen, zu welcher Zeit Sturmhuf gelebt hat. Mit diesem Wissen können wir die Zeitachse wiederherstellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13049] = { id = 13049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Waffen des Helden", description = "Noch wurden nicht alle Aufzeichnungen des Lagers manipuliert. Meine Helfer haben mir dabei geholfen, diese Aufzeichnungen mit der wahren Zeitfolge zu finden.\n\nSie stimmen darin überein, dass Sturmhuf ein Ehrenbegräbnis bei den Dorfältesten unten in der Heulenden Senke im Norden bekam.\n\nDie meisten der dortigen Gräber wurden bereits zerstört und ihr Inhalt als Trophäen von den Wesen des Nordwinds entnommen. Begebt Euch in die Senke und versucht, Sturmhufs Rüstung und Speer von den Saaten des Sturms zu erlangen, die diese Dinge für sich beansprucht haben.", sourceObjective = "Findet Sturmhufs Rüstung und Speer und bringt die Gegenstände zu Xarantaur in Camp Tunka'lo zurück.", progress = "Habt Ihr Sturmhufs Rüstung und Speer gefunden?", completion = "Wir sind froh, dass Ihr diese Gegenstände unversehrt zurückbringen konntet, {name}. Mit ihrer Hilfe kann ich den Lehrenhammer benutzen, um Euch in die Zeit zurückzuschicken, als der Nordwind damit begonnen hatte, die wahre Zeitlinie zu manipulieren. Das ist die einzige Möglichkeit, wie wir den wahren Geschichtsverlauf dieses Ortes wiederherstellen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13050] = { id = 13050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Veranus", description = "Wenn ich die Armee meines Bruders angreifen will, muss ich irgendwie um sie herumkommen.\n\nIch habe meinen Reitdrachen schon vor Jahren freigelassen. Veranus war prächtig, die Anführerin ihrer eigenen Brut - zu der sie jetzt zurückgekehrt ist.\n\nEs wird sehr schwer werden, sie zu finden, aber es gibt vielleicht eine Möglichkeit. Aus Stolz hat sie ihr altes, leeres Nest behalten. Sie ist nur noch vom Namen her eine Brutmutter, da sie das Brutalter bereits überschritten hat.\n\nBringt mir kleine Eier aus den anderen Nestern in der Nähe von Brunnhildar. Ich habe da so eine Idee.", sourceObjective = "Thorim aus dem Tempel der Stürme möchte, dass Ihr ihm 5 kleine Eier von den Protodrachen bringt, die auf den Gipfeln in der Umgebung von Brunnhildar hausen.", progress = "Habt Ihr die Eier, {name}?", completion = "Ja... die sollten reichen. Hoffen wir, dass mein Plan aufgeht, {name}.\n\nVeranus ist ein großer Drache und ich würde mich nur ungern mit einem niederen zufrieden geben müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13051] = { id = 13051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territoriale Vergehen", description = "Veranus ist stolz wie kein anderes Tier, das ich je gekannt habe. Sie hat noch immer ihr altes Nest und achtet darauf, dass es nicht von einem jüngeren Protodrachen in Besitz genommen wird.\n\nLegt die Eier, die Ihr gesammelt habt, in ihr Nest. Ihr findet es auf dem kleinen Gipfel südöstlich von hier.\n\nIch müsste sie unter Kontrolle haben, bevor sie Euch aus lauter Wut umbringt; zumindest hoffe ich das.", sourceObjective = "Legt die gestohlenen Protodracheneier in das Nest der Brutmutter und kehrt dann zu Thorim in den Tempel der Stürme zurück.", progress = "Grüße, {name}!", completion = "Ich freue mich, dass meine alte Freundin zurück ist. Es scheint fast so, als würde sich das Blatt langsam wenden... und das habe ich allein Euch zu verdanken, kleiner Freund.", sourceObjectiveStatus = "unverified-source-field" }
quests[13052] = { id = 13052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Luftüberwachung", description = "Ihr wart Wes eine große Hilfe, als Ihr mit ihm diese Flugmaschine wieder zum Laufen gebracht habt.\n\nWenn Ihr uns weiterhin helfen wollt: Es gibt da eine ungewöhnliche, von Nordwesten aufziehende Wettererscheinung. Ich verfüge bereits über einen einsatzbereiten Piloten, aber er braucht leider einen Copiloten.\n\nWenn Ihr Euch dem gewachsen fühlt, könnt Ihr den Flug zum Landeplatz am See nehmen. Sagt Vic, dass ich Euch geschickt habe.", sourceObjective = "Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht.", sourceObjectiveStatus = "unverified-source-field" }
quests[13053] = { id = 13053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suche nach Überlebenden", description = "Gretchen Zischelfunken möchte meine Flugmaschine nutzen, um nach Überlebenden ihrer Expedition zu suchen. Offenbar glaubt sie, dass diese im Dorf im Norden gefangen gehalten werden.\n\nDas Problem ist, dass ich keinen Copiloten habe. Wenn Ihr mir aushelfen wollt, dann zeige ich Euch gern ein oder zwei hilfreiche Tricks.\n\nWas sagt Ihr, {name}? Abgemacht?Ihr erlernt:", sourceObjective = "Helft Zak Wackelspross, den Testflug zu beenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13054] = { id = 13054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der vermisste Fährtenleser", description = "Ich kann Euch nicht guten Gewissens in die Worghöhle gehen lassen, ohne Euch zu warnen, dass wir zuvor schon jemanden dorthin geschickt haben, der jedoch nicht zurückgekehrt ist.\n\nWir rechnen mit dem Schlimmsten, aber vielleicht ist er auch noch am Leben. Solltet Ihr ihm helfen können, zu uns zurückzukehren, wären wir Euch sehr dankbar - Fährtenleser Val'zij ist einer unserer wenigen Jäger.", sourceObjective = "Sucht in Gimoraks Bau östlich der Absturzstelle Grom'ash nach Fährtenleser Val'zij.", completion = "Das tut wirklich weh, Mann. Ich weiß nicht, ob ich es schaffen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[13055] = { id = 13055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höhlenmedizin", description = "Wie schön, ein freundliches Gesicht zu sehen, vielleicht das Letzte, das ich seh'n werde.\n\nEiner dieser Jormungar hat mich gestochen, bevor ich entkommen konnte. Mein Körper fühlt sich schon ganz taub an, Mann.\n\nIch brauch'ne Giftdrüse, um ein Gegengift herzustellen, und außerdem einige der Höhlenpilze, die hier wachsen... sie werden das Gift verlangsamen.\n\nBitte beeil dich - hab nich' mehr viel Zeit.", sourceObjective = "Fährtenleser Val'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt.", progress = "Du bist wieder da, Mann?", completion = "Danke dir, Mann. Vielleicht lebe ich doch noch 'n bisschen länger.", sourceObjectiveStatus = "unverified-source-field" }
quests[13056] = { id = 13056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für Rache ist immer Zeit", description = "Ich müsste vorerst zurechtkommen, {name}. Aber ich möchte dich noch um 'nen Gefallen bitten.\n\nIch wäre diesen Würmern nie in die Hände gefallen, wenn meine Windnatter Heesha nicht vom gemeinsten Worg, den ich seit langer Zeit gesehen habe, getötet worden wäre.\n\nMach dir um mich keine Sorgen; mir wird es besser gehen, wenn der Worg keinen Atemzug mehr von sich gibt. Du solltet ihn weiter drinnen in der Höhle finden", sourceObjective = "Fährtenleser Val'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet.", progress = "Hast du diesen dreckigen Bastard schon gefunden, {name}?", completion = "Es geht mir schon viel besser, Mann. Ich weiß nicht, ob es an dem Gegengift liegt oder daran, dass der dreckige Worg bekommen hat, was er verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[13057] = { id = 13057, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse der Schöpfer", description = "Es ist Zeit, {name}. Ich bin jetzt bereit, mich Loken zu stellen.\n\nBegeben wir uns nun zur Terrasse der Schöpfer, wo wir auf die Truppen meines Bruders treffen werden. Der Narr wird noch bereuen, sich je mit mir angelegt zu haben.", sourceObjective = "Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem.", completion = "Wir sind da, {name}. Heute werden die Truppen meines Bruders erfahren, wie es ist zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13058] = { id = 13058, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Windrichtung ändern", description = "Zu guter Letzt haben wir alles, was wir brauchen, um das wieder gut zu machen, was der Nordwind und seine Anhänger angerichtet haben. Ihr habt den Lehrenhammer auf Sturmhuf selbst und seine Zeit ausgerichtet.\n\nHier, nehmt wieder den Hammer an Euch, geht zum Tempel des Lebens, schlüpft mit seiner Hilfe in Sturmhufs Rolle und stellt Euch dem Nordwind. Doch wisset: Um die Zeitlinie wieder herzustellen, muss Sturmhuf sterben, sobald der Nordwind geschwächt ist.\n\nSobald dies geschehen ist, müsst Ihr das Horn des Elementarfurors an Euch bringen und mit ihm den Nordwind vernichten.", sourceObjective = "Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallengelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka'lo zurück.", progress = "Habt Ihr es getan? Ist die echte Zeitlinie wiederhergestellt?", completion = "Was Ihr heute getan habt, wird dafür sorgen, dass Sturmhuf und seine Geschichte niemals in Vergessenheit geraten werden. Außerdem habt Ihr Euren Namen in die Geschichtsbücher Azeroths geschrieben. Ich werde mich für alle Ewigkeit an Euch und das, was Ihr geleistet habt, erinnern.", sourceObjectiveStatus = "unverified-source-field" }
quests[13059] = { id = 13059, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache für die Vargul", description = "Ich habe zur Herrin des Schwertes gebetet, auf dass jemand kommen und meinen Gegner vernichten möge. Than Illskar muss dafür büßen, was er mir angetan hat!\n\nIch war einst der Champion von Than Ufrang dem Mächtigen. Während meines Kampfes um die Vormachtstellung in Valhalas hat mich Illskar mit dunkler Magie sabotiert, woraufhin ich verloren habe und zu dem wurde, was ich jetzt bin.\n\nDer Than und seine Champions befinden sich unten im Kreis des Leidens. Fordert ihn in meinem Namen heraus. Besiegt ihn.\n\nBringt ihm die Qualen bei, die auch ich ertragen muss!", sourceObjective = "Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten.", completion = "Danke, {class}... habt Dank!\n\nIhr habt mir zu der Genugtuung und Gewissheit verholfen, dass dieser Feigling, der mir das angetan hat, bis in alle Ewigkeit genau so dahinsiechen wird wie ich.\n\nNun geht hinfort, bevor ich die Beherrschung verliere und Euch niederstrecke.", sourceObjectiveStatus = "unverified-source-field" }
quests[13060] = { id = 13060, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wenn alles andere versagt", description = "Also... also ich denke nicht, dass wir in diesen Bergen gut Fuß fassen werden.\n\nGlaubt mir, ich bin sicherlich niemand, der schnell aufgibt... doch wenn ich an gefrorene Motoren, gemeine Vrykulweiber, territoriale Möchtegerndrachen und das halbe Dutzend anderer Widerlinge in der Gegend denke, dann muss ich wirklich sagen: daraus wird nichts.\n\nLasst Euch davon jedoch nicht entmutigen! Nur weil wir nicht Fuß fassen können, heißt das noch lange nicht, dass wir Euch nicht dorthin bekommen werden... Reisen ohne Wiederkehr sind ziemlich einfach, wenn man die Sache nur richtig angeht.\n\n<Ricket deutet mit einem Nicken in Richtung einiger in der Nähe befindlicher Raketen.>", sourceObjective = "Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen.", completion = "<Olut zuckt zusammen.>\n\nDas hat schmerzhaft ausgesehen. War aber ein ziemlich eindrucksvoller Auftritt.\n\nSeid Ihr hier, um uns dabei zu helfen, einen Weg zum Eiskronengletscher zu finden? Unser erster Abstecher in diese Richtung endete nicht sehr eindrucksvoll. Ich denke, dass wir besser damit beraten wären, den Durchbruch von der anderen Seite her zu versuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13061] = { id = 13061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bereit für den Ruhm", description = "Das war's dann also. Ich werde mich jetzt um Euren Bären kümmern, Ihr werdet ihn nicht mehr benötigen. Der große Drakkensryd wird Eure nächste Herausforderung sein.\n\nSagt Euren Freunden Lebewohl und bringt alles ins Reine, bevor Ihr loszieht. Denn Ihr werdet entweder siegreich zurückkehren... oder gar nicht.", sourceObjective = "Sprecht mit Lok'lira der Greisin in Brunnhildar.", completion = "Ihr habt es wirklich bis hierher geschafft. Niemals hätte ich gedacht, dass Ihr so schnell bei den Hyldnir aufsteigen würdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13062] = { id = 13062, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok'liras Abschiedsgeschenk", description = "Ihr wart uns eine großartige Mitstreiterin, {name}. Doch nun kommt Eure wahre Prüfung. Dazu werdet Ihr Können, Mut und ein wenig Glück benötigen.\n\n<Lok'lira flicht eine Haarsträne in Euer Haar ein.>\n\nNun könnt Ihr nicht mehr versagen, Schwester. Sprecht mit Gretta der Schiedsfrau. Sie wird sich um Eure Abreise kümmern.", sourceObjective = "Sprecht mit Gretta der Schiedsfrau in Brunnhildar.", completion = "Bereit, loszureiten, Schwester? Es wird kein Zurück geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13063] = { id = 13063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für würdig befunden", description = "Ihr hattet dort Erfolg, wo viele versagten, Schwester. Ob es nun Eurer Stärke, Eurem Mut oder einfach nur Eurem Glück zu verdanken ist, wird sich noch zeigen.\n\nGeht zurück zum Dorf und sucht nach Astrid Bjornrittar. Erzählt ihr, was Ihr erreicht habt. Doch seid gewarnt: Sie ist nicht so leicht zu beeindrucken.", sourceObjective = "Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht.", completion = "So, Schwester, Ihr denkt also, dass ein paar so einfache Aufgäbelchen Euch zur Heldin machen?\n\nIhr werdet es noch lernen...", sourceObjectiveStatus = "unverified-source-field" }
quests[13064] = { id = 13064, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rivalität unter Geschwistern", description = "Sif? Bist du es wirklich?\n\nNein? Nur <ein/eine:r> {race}? Aber einen Augenblick lang...\n\nGenug davon! Die Visionen meiner Sif haben mich schon viel zu lange gequält. Es wird Zeit, sie zu rächen und ihr Andenken zu ehren.\n\nMein Bruder muss bezahlen!", sourceObjective = "Thorim möchte, dass Ihr Euch seine Geschichte anhört.", completion = "Ihr wisst jetzt ein wenig über die Geschichte dieses Landes... meines Landes.\n\nIch bitte Euch, mir zu helfen, das Unrecht wieder gutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13065] = { id = 13065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Ohanzee", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13066] = { id = 13066, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Yurauk", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13067] = { id = 13067, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Urahne Chogan'gada", sourceObjective = "Es ist gut zu wissen, dass die Bewohner dieser Welt noch immer die alten Völker verehren und sie nicht vergessen haben. Ich erbiete Euch meinen Respekt, {name}. Nehmt dies als Zeichen meiner Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13068] = { id = 13068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Erzählung von Heldenmut", description = "Ist es möglich, dass Ihr die Lobpreisungen an unseren verschollenen Helden gehört habt?\n\nKreuzfahrer Bridenbrad hat den Angriff gegen die Geißel an der Zerbrochenen Front unterstützt, als die Armee der Untoten über sie hereinbrach. Die Masse der Verbündeten floh, aber Bridenbrad allein kehrte zurück und trug mehr als ein Dutzend Männer in Sicherheit, einen nach dem anderen, inmitten des Gemetzels.\n\n{class}, er ist seitdem nicht wieder zurückgekehrt. Man hat gesehen, wie er weit nach Nordosten zog, Richtung Stille Nachtwache. Bringt ihn wieder hierher, damit ich ihm für seinen Mut Respekt zollen kann.", sourceObjective = "Hochlord Tirion Fordring auf dem Kreuzfahrerturm wünscht, dass Ihr den Helden Kreuzfahrer Bridenbrad in der Stillen Nachtwache im Nordosten der Eiskrone aufspürt. Seine Feuergrube wird aus der Luft gesehen wahrscheinlich der deutlichste Hinweis auf seinen Aufenthaltsort sein.", completion = "Zurück! Seht Euch vor! Die Seuche hat von mir Besitz ergriffen und ich werde nicht zulassen, dass sie auf Euch oder andere überspringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13069] = { id = 13069, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schießt sie ab!", description = "Jotunheim verfügt über Luftabwehr, sowohl Protodrachenreiter als auch Harpunenkanonen. Sie haben diese an ihren nördlichen und westlichen Verteidigunszonen konzentriert, weil sie dort am verwundbarsten sind.\n\nLasst uns ihre Verteidigung gegen sie selber richten!\n\n<Der Springer starrt Euch mit seinem einen Auge durchdringend an und kichert hysterisch.>\n\nBringt eine Harpunenkanone auf den Plattformen, welche die Klippen auf jeder Seite von Valhalas gen Südwesten überragen, unter Eure Kontrolle. Kümmert Euch um die Protodrachen und ihre Reiter. Schießt sie ab!", sourceObjective = "Der Springer beim Schattengewölbe möchte, dass Ihr eine Schnellfeuerharpune von Jotunheim dazu verwendet, 15 Protodrachen von Jotunheim mitsamt ihren Reitern abzuschießen.", completion = "Ihr seid ein wahrer Held für unsere Sache, {name}!\n\nKommt Ihr bitte morgen wieder bei mir vorbei? Ich bin mir sicher, dass es dann wieder mehr von diesen fiesen Protodrachen abzuschießen gibt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13070] = { id = 13070, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Kaltfront nähert sich", description = "Der Frost des Todes regt sich im Westen und droht, unsere Herzen und Seelen in dieser Ödnis einzufrieren, uns an ihren dunklen Meister zu binden. Aber wir werden nicht weichen und wir werden kämpfen!\n\nDie Vorbereitungen sind angelaufen. Meldet Euch bei Belagerungsmeister Fezzik am Haupttor für Euren Auftrag.", sourceObjective = "Meldet Euch bei Belagerungsmeister Fezzik bei der Argentumvorhut in Eiskrone.", completion = "Wir müssen schnell sein, sonst wird uns die Geißel holen! Wir haben wirklich keine Zeit für Instruktionen, {race}. Ihr werdet wohl einfach hineinhüpfen und auf das Beste hoffen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13071] = { id = 13071, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ekel mag Feuer!", description = "Ekel mag Feuer! Ekel mag Protodrachen!\n\n<Die Monstrosität klatscht aufgeregt in die Hände.>\n\nKleiner {name} jetzt gehen nach Jotunheim un' stehlen schöne Protodrache in Njorndar. Lass' Protodrache schöööne Feuers auf Häuser von Jotunheim machen!", sourceObjective = "Ekel im Schattengewölbe möchte, dass Ihr einen Protodrachen von Njorndar stehlt und ihn benutzt, um 8 Vrykulgebäude in der weiteren Jotunheimregion in Brand zu setzen.\n\nDie Festung Balargarde kann aufgrund ihrer Beschaffenheit nicht in Flammen gesetzt werden.", completion = "Hurra, hurra! {name} ist allerbeste Protodrachen-Klauer.\n\nDu kommen zurück morgen und wir machen meeehr Feuer!!!", sourceObjectiveStatus = "unverified-source-field" }
quests[13072] = { id = 13072, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Held verbleibt", description = "Ich weiß, warum Ihr gekommen seid... sie haben Euch geschickt um mich zurückzubringen, aber das darf nicht geschehen. Ich trage die Seuche des Todes in mir, {class}, und werde mein Schicksal nicht mit jenen teilen, die mir nahe stehen. Nein, ich werde hier bleiben. \n\nIch bedaure nur, was aus mir werden wird, wenn der Tod Besitz von mir ergriffen hat. Den Tod selbst fürchte ich nicht, aber ich verabscheue den Gedanken daran, dem Verräter Arthas zu dienen.\n\nVerlasst mich... und stellt sicher, dass niemand anderes nach mir suchen wird. Ihr würdet mir einen wahren Undienst erweisen, wenn Ihr jemanden der Seuche, die ich trage, aussetzen würdet.", sourceObjective = "Bringt die Neuigkeiten von Kreuzfahrer Bridenbrads Schicksal zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", completion = "Bridenbrad wurde von der Seuche befallen? Ich kann mir kein schlimmeres Schicksal für jemanden vorstellen, der sein Leben dem Weg des Lichts gewidmet hatte; noch kann ich mir vorstellen, ihn sterbend zurückzulassen und dabei tatenlos zuzusehen.\n\nNein, der Untod soll sein Schicksal nicht sein. Wir werden einen Weg finden, diesem Helden beizustehen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13073] = { id = 13073, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Bitte an den Bewahrer", description = "Es gibt jene in dieser Welt, die auf Kräfte stoßen, die frei sind von den Grenzen unserer sterblichen Hüllen - Kräfte der Wiederherstellung, des Lebens und des Lichts. Und Bridenbrad? Das ist kein durchschnittlicher Mann... sein Heldenmut und seine Hingabe sind ein leuchtendes Vorbild. Wir können nur hoffen, dass eines dieser Wesen einschreiten wird und diesen Helden vor einem Schicksal, das schlimmer als der Tod ist, bewahren wird.\n\nGeht nun und sprecht mit der Erzdruidin Lilliandra in der Argentumvorhut... erbittet den Zugang zur Mondlichtung und ersucht Bewahrer Remulos um Hilfe.", sourceObjective = "Hochlord Tirion Fordring im Kreuzfahrerturm hat Euch gebeten, dass Ihr bei der Erzdruidin Lilliandra Zugang erbittet und mit Bewahrer Remulos redet.", completion = "Hallo, mein Kind.\n\nIch verstehe Tirions Bitte und habe Vertrauen in sein Urteilsvermögen. Wir werden sehen, was wir für Kreuzfahrer Bridenbrad tun können. Wonach Ihr fragt, ist keine Leichtigkeit - die Geißel ist nicht von dieser Welt und viele sind im Laufe der Jahre bei dem Versuch gescheitert, ihre Verderbnis zu durchbrechen.\n\nBei einem Lebewesen von Erhabenheit und Licht ist jedoch nicht alle Hoffnung verloren.", sourceObjectiveStatus = "unverified-source-field" }
quests[13074] = { id = 13074, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hoffnung im Smaragdgrünen Alptraum", description = "Was wir brauchen, gibt es nur im Smaragdgrünen Traum... Eicheln, die mit einem mächtigen, regenerativen Zauber durchtränkt sind. Viele Orte in diesem heiligen Sumpf sind eng mit dem Traum verbunden und mein Schrein ist einer davon.\n\nIch werde Euch in den Traum schicken, um ein paar jener Eicheln zu besorgen. Seid aber gewarnt, {class}, denn diese Methode, den Traum zu betreten, ist gefährlich, und es ist recht wahrscheinlich, dass Ihr von Alpträumen heimgesucht werdet.\n\nBeeilt Euch und findet ein paar Eicheln. Verlasst anschließend meinen Schrein oder kneift Euch selbst in den Arm, um in unsere Welt zurückzukehren.", sourceObjective = "Bewahrer Remulos auf der Mondlichtung hat Euch aufgetragen, den Smaragdgrünen Traum zu betreten und 3 Smaragdgrüne Eicheln zu besorgen.\n\nVerlasst die nähere Umgebung des Schreins von Remulos, um nach Azeroth zurückzukehren.", progress = "Gut zu sehen, dass Ihr in Sicherheit seid. Habt Ihr alle Eicheln gefunden?", completion = "Hervorragende Arbeit, mein Junge.", sourceObjectiveStatus = "unverified-source-field" }
quests[13075] = { id = 13075, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Remulos' Segen", description = "Ich werde ein Portal öffnen, das Euch zu dem Druiden, der Euch hergesandt hat, zurückbringen wird. Meine besten Wünsche begleiten Euch und Euren Kreuzfahrer. Ich hoffe, diese Eichel wird ihn läutern und somit vor dem abscheulichen Schicksal der Seuche bewahren können.\n\nLebt wohl, {race}.", sourceObjective = "Kehrt mit der Smaragdeichel zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", progress = "Seid gegrüßt, {class}. Ich wusste, dass Ihr zurückkehren würdet, ungeachtet meiner Warnungen... Aber ich bin froh, dass Ihr meiner Bitte nachkommt, niemand anderen zu gefährden.\n\nWarum seid Ihr zurückgekehrt?", completion = "Tirion hat Euch zu Remulos gesandt? Ich... fühle mich geehrt. Man richtet nicht leichtfertig seine Bitten an Wesen von solcher Macht, ganz gleich, wie edel und uneigennützig sie sein mögen. Ich danke Euch, dass Ihr derartige Mühen meinetwegen auf Euch genommen habt.\n\nPflanzt den Samen ein... Ich bin bereit.", sourceObjectiveStatus = "unverified-source-field" }
quests[13076] = { id = 13076, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es bleibt noch Zeit", description = "Ich fühle mich erfrischt... erneuert... aber die Seuche hält mich immer noch in ihrer eisigen Umklammerung. Ich bin Euch dennoch auf ewig dankbar für die Mühen, die Ihr für mich, einen völlig Fremden, auf Euch genommen habt. Zumindest habt Ihr mir so einige wertvolle Stunden verschafft, während derer ich nicht als grässlicher Untoter die Welt verpeste.\n\nIch danke Euch, {class}. Bitte richtet auch Tirion meinen Dank aus und lasset ihn wissen, dass es mir eine Ehre war, an seiner Seite zu dienen.", sourceObjective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten der Smaragdeichel.", completion = "Es erfüllt mich mit Trauer, dass es nicht funktioniert hat. Aber kein Grund zur Verzweiflung, ich habe noch andere Wesen des Guten getroffen, die uns noch immer helfen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13077] = { id = 13077, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Berührung eines Aspekts", description = "Die Drachenkönigin, Alexstrasza, besitzt Magien über das gesamte Sein. In der Vergangenheit hat sie große Feuer benutzt, um Untote zu verbrennen und frisches, neues Leben an ihrer Stelle zu erschaffen. Ihre Kräfte sind vielleicht in der Lage, auch unseren Bridenbrad zu retten.\n\nAlexstrasza hat sich im Wyrmruhtempel in der Drachenöde eingerichtet. Bitte geht zu Ihr und bittet sie demütigst in meinem Namen um Hilfe.", sourceObjective = "Erbittet die Hilfe von Alexstrasza der Lebensbinderin im Wyrmruhtempel.", completion = "Ich grüße Euch, {race}.\n\nDie Sorge steht Euch ins Gesicht geschrieben. Sagt mir, was Euch bedrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13078] = { id = 13078, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dahlias Tränen", description = "In dieser dunklen Stunde werde ich nicht diejenige sein, die einen Helden des Lichts im Stich lässt.\n\nWir werden etwas Heiliges brauchen, um auf die Rettung Eures Bridenbrads hoffen zu können... Das Überbleibsel eines frommen Wesens, das Opfer eben dieser Seuche wurde.\n\nGeht nun zum heiligen Boden in den Gängen außerhalb meines Rubindrachenschreins, dorthin, wo der Kampf stattfinden wird. Meine Rubinhüter werden herabfliegen und den Boden unter untoten Füßen mit Flammen überziehen. Ihr werdet dann Zeuge neuen Lebens sein. Dieses neue Leben wird auch Dahlias Tränen bergen - bringt sie mir.", sourceObjective = "Alexstrasza die Lebensbinderin im Wyrmruhtempel verlangt von Euch, dass Ihr Dahlias Tränen aus dem Boden bergt, der von den Flammen der Rubinbehüter frisch geläutert ist.", progress = "Ah, liebste Dahlia. Ich vermisse dich so...", completion = "Mithilfe von Dahlias Tränen und uralter Magie kann ich Euch ein kleines bisschen Hoffnung für Euren großen Kreuzfahrer verschaffen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13079] = { id = 13079, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alexstraszas Segen", description = "Ihr müsst verstehen, <junger/junge :r> {race}, dass das Läutern eines Körpers zugunsten des Lebens etwas ist, das durchaus in meiner Macht liegt... die Seuche des Untodes zu entfernen, ohne den Körper in Mitleidenschaft zu ziehen, entzieht sich jedoch meiner Kontrolle.\n\nWenn dieser Bridenbrad das Leuchtfeuer des Lichts ist, wie Ihr es beschwört, wird er vielleicht die Läuterung überstehen und sich erholen, aber ich kann nicht mit Gewissheit sagen, ob dies die Erlösung sein wird, nach der Ihr strebt. Nehmt sie und geht mit all meinem Segen.", sourceObjective = "Bringt den Atem von Alexstrasza zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone.", progress = "Ihr seid schon wieder hergekommen, {class}. Warum setzt Ihr Euch diesem Risiko aus?", completion = "Der Atem von Alexstrasza... Ihr seid zur Drachenkönigin höchstpersönlich gegangen? Ich bin Euch unsäglich dankbar.\n\nIch bin mir der Risiken einer solchen Läuterung bewusst und bin bereit. Fahrt fort, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13080] = { id = 13080, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Hoffnung stirbt zuletzt", description = "<Bridenbrad erhebt die Hand zum Gruße, während er wieder zu Atem kommt.>\n\nEs war fast so schmerzhaft, wie es ausgesehen hat, aber es fühlte sich an, als wäre ein Teil der Verderbnis aus meinem Körper gebrannt worden. Anscheinend ist die Seuche jedoch so einfach nicht zu bezwingen.\n\n{class}, danke für alles, was Ihr getan habt. Eure selbstlosen Taten haben meine Hoffnung genährt, dass es noch immer viel Gutes in der Welt gibt...Ich kann nun gehen, ohne Furcht davor, dass die Dunkelheit in meiner Abwesenheit obsiegen wird.\n\nIhr könnt nun ohne Bedenken gehen.", sourceObjective = "Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten des Atems von Alexstrasza.", completion = "Die Seuche der Geißel ist kein leicht zu bezwingender Feind. Alexstraszas Worte legen nahe, dass wir unseren treuen Bridenbrad noch immer vor dem unvorstellbaren Schicksal des Untodes bewahren könnten, sollte er fallen, aber so leicht gebe ich ihn nicht auf.\n\nEs gibt noch einen Weg des Lichts, den ich gerne beschreiten würde. Ein weiteres Wesen, das dieses schreckliche Schicksal abwenden könnte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13081] = { id = 13081, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Wille der Naaru", description = "Ich bin dankbar für alles, was Ihr für uns getan habt, {name}. Ich habe noch einen letzten Auftrag für Euch... ein letztes Glimmen der Hoffnung für einen Paladin, der jede Erlösung verdient, die wir ihm bieten können.\n\nGeht nun nach Shattrath und sprecht mit dem Naaru A'dal. Er ist seit langem ein Leuchtfeuer des Lichts und mächtiger Verbündeter der Paladine. Berichtet ihm von Bridenbrad und erbittet jede Hilfe, die er Euch zu geben vermag.\n\nIch kann nicht genug betonen, wie wichtig es ist, dass Ihr Euch beeilt... Ich befürchte, dass unserem Kreuzfahrer nicht mehr viel Zeit in dieser Welt verbleibt.", sourceObjective = "Erbittet die Hilfe von A'dal in Shattrath in den Wäldern von Terokkar.", completion = "<Ein sanftes Klingen erfüllt Euren Kopf, als Ihr Euch dem Naaru nähert.>\n\nIch weiß, warum Ihr hergekommen seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[13082] = { id = 13082, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A'dals Segen", description = "Ich bin erfreut, dass Ihr zu mir gekommen seid, {name}. Ich weiß von Kreuzfahrer Bridenbrad und von Euren Reisen, um ihn zu erretten. Bridenbrads Heldenmut hat eine bemerkenswerte Selbstlosigkeit in Euch zum Vorschein gebracht, und das ist an sich schon ein Wunder.\n\nDas Licht wird sich um die Seinen kümmern. Ich werde Bridenbrad meinen Segen zuteilwerden lassen, auf dass er die Verderbnis des Untodes nicht länger zu ertragen braucht. Ich werde Euch zurück nach Dalaran schicken und Ihr werdet zu ihm zurückkehren. Wisset, dass ich stets bei Euch sein werde.", sourceObjective = "Kehrt zu Kreuzfahrer Bridenbrad in die Stille Nachtwache in Eiskrone zurück.", completion = "<Als Ihr Euch Kreuzfahrer Bridenbrad nähert, müsst Ihr feststellen, dass seine Haut eine fahle Farbe angenommen hat und sein Atem sehr flach geht. Es ist klar, dass er nicht mehr lang zu leben hat.>\n\nIhr seid zu mir zurückgekehrt, {class}. Ich muss zugeben... dass es gut ist, Euch wiederzusehen... Euer Antlitz erneuert meine Hoffnung, dass dieses Land eines nicht zu fernen Tages von Arthas' eisigem Griff befreit sein wird. Ich bin stolz darauf, Euch gekannt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13083] = { id = 13083, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Licht im Dunkeln", description = "<Kreuzfahrer Bridenbrads Wappenrock liegt am Boden der Truhe und beginnt leicht zu flattern, als der heulende Wind seinen Weg hineinfindet.>\n\nTirion wird dieses letzte Überbleibsel des großen Kreuzfahrers an sich nehmen wollen.", sourceObjective = "Bringt Kreuzfahrer Bridenbrads Wappenrock zu Hochlord Tirion Fordring in den Kreuzfahrerturm.", progress = "Er ist also von uns gegangen, nicht wahr? Ich habe gespürt, wie das Land um etwas Licht ärmer geworden ist.", completion = "Ich bin froh, dass Ihr ihn vor dem Untode bewahren konntet. Mit dem Segen A'dals wird ihm im Jenseits kein Übel widerfahren.\n\nWir werden uns ein Beispiel an seinem leuchtenden Vorbild und an Eurer Selbstlosigkeit nehmen. Ich danke Euch für alles, was Ihr getan habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13084] = { id = 13084, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Demoliert Jotunheim", description = "Lasst uns doch mal sehen, ob wir noch weiter die Entschlossenheit der Vrykul schwächen können, {name}.\n\nIch möchte, dass Ihr jeden Tag nach Jotunheim geht und ihre Banner verbrennt. Das mag sich nach einer unbedeutenden Sache anhören, aber wenn sie ihre Heimatstadt jeden Tag demoliert sehen, wird dies ihre Moral weit mehr schwächen, als es jede physische Gewaltmaßnahme je könnte.\n\nZumindest aber... kann es nicht schaden.", sourceObjective = "Herzog Lankral beim Schattengewölbe möchte, dass Ihr 10 Banner der Vrykul verbrennt.", completion = "<Der Herzog schaut Euch einen Moment lang an, dann nickt er.>\n\nIhr richtet ein verheerendes mentales Trauma unter den Vrykul von Jotunheim an. Es ist der Ort, an dem sie das erste Mal wiedererweckt wurden. Ein Ort von herausragender Bedeutung für sie, übertroffen nur von Ymirheim.\n\nIhr müsst den Druck dort aufrechterhalten, während ich die Streitkräfte des Lichkönigs vom Schattengewölbe abhalte.", sourceObjectiveStatus = "unverified-source-field" }
quests[13085] = { id = 13085, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vaelen ist zurückgekehrt", description = "Ich habe soeben diesen inkompetenten Narren, Vaelen den Geschundenen, gesehen, wie er in das Schattengewölbe geschlichen ist.\n\nGeht und stellt sicher, dass er seinen Fehler wieder gutmacht und mir meine Todesritter zurückbringt!", sourceObjective = "Redet mit Vaelen dem Geschundenen im Schattengewölbe.", completion = "Ich denke, ich weiß, warum Ihr hier seid, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13086] = { id = 13086, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Verteidigungslinie", description = "Ich habe die Verteidigungen der Basis aktiviert, {class}! Auf jedem der vier Türme der Vorhut ist eine einziehbare Kanone des Argentumkreuzzugs angebracht, von Vater Gustav persönlich geweiht. Ihr müsst zu einer der Kanonen fliegen und sie bemannen. Benutzt sie, um den Ansturm der Geißel zu vernichten, den der Lichkönig hergesandt hat.\n\nEine Warnung noch, die Geißel wird zweifelsohne ihre Frostwyrms schicken, um die Türme zu belagern. Blast sie vom Himmel! Wenn sie die Türme und Wälle der Basis zerstören, sind wir geliefert!", sourceObjective = "Benutzt eine Argentumkanone, um 100 Angreifer der Geißel zu vernichten. Außerdem müsst Ihr 3 Frostbrutzerstörer töten.\n\nSolltet Ihr erfolgreich sein, kehrt zu Belagerungsmeister Fezzik zurück.", progress = "Die Schreie der Sterbenden werden mich mein Leben lang verfolgen! Helft ihnen!", completion = "Ihr habt die Kanone wie ein echter Goblinkanonier geführt, Freund. Ihr habt die Vorhut und den Argentumkreuzzug gerettet... und dabei den Hochlord selbst auf dem Schlachtfeld unterstützt. Unglaublich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13087] = { id = 13087, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Also was machen wir denn da, wenn Ihr keinen Eintopf für mich habt? Ich hab' HUNGER! Ihr könnt mir zumindest ein wenig kühles Fleisch bringen, damit ich mir selbst 'nen Eintopf machen kann! Wenn Ihr das macht, dann kann ich Euch ein Rezept geben, damit Ihr Euren eigenen machen könnt. JETZT GEHT UND BRINGT MIR EIN BISSCHEN FLEISCH!", sourceObjective = "Bringt 4 Stück kühles Fleisch zu Brom Bräugießer in Valgarde. Jede Bestie in Nordend verfügt über dieses Fleisch.", progress = "WO IST MEIN FLEISCH!", completion = "Du hast mein Fleisch! Hier ist dein Rezept - ich hab' zu kochen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13088] = { id = 13088, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Wir haben eine Menge neuer Rekruten hier und die Jungs sind hungrig! Wenn Ihr mir ein wenig kühles Fleisch für einen Eintopf besorgen könntet, würde ich Euch beibringen, wie Ihr selbst einen für Euch kochen könnt.", sourceObjective = "Bringt Rollick MacKreel in der Valianzfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Die Jungs brauchen Fleisch für ihren Eintopf.", completion = "Das wird unsere Rekruten satt halten! Hier ist das Kochrezept dafür.", sourceObjectiveStatus = "unverified-source-field" }
quests[13089] = { id = 13089, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Nichts wärmt die Knochen besser, als ein aus lebenden Wesen zubereiteter Eintopf. Bringt mir etwas von dem kühlen Fleisch der hiesigen jämmerlichen Bestien und ich werde Euch zeigen, wie man einen warmen Eintopf zubereitet.", sourceObjective = "Bringt 4 Stück kühles Fleisch zu Thomas Kolichio im Hafen der Vergeltung. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Der Eintopf wartet...", completion = "Wir können das Fleisch im Handumdrehen zu Eintopf verarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13090] = { id = 13090, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kochkunst des Nordens", description = "Die Krieger der Kriegshymnenoffensive brauchen etwas in ihren Bäuchen, um stark zu bleiben. Falls Ihr mir ein wenig kühles Fleisch von den Rhinozerossen oder den anderen Bestien besorgt, könnte ich ein bisschen Eintopf für sie kochen. Wenn Ihr mir helft, werde ich Euch das Rezept verraten.", sourceObjective = "Bringt Orn Zarthuf in der Kriegshymnenfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch.", progress = "Wenn das Fleisch hier ist, wird der Eintopf gekocht.", completion = "Ihr habt meinen Dank.", sourceObjectiveStatus = "unverified-source-field" }
quests[13091] = { id = 13091, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst, ein Wasserschrecken zu sein", description = "Die Wasserschleuse vor meiner Höhle wimmelt nur so von Elementaren, die von den Vrykulzauberern erst noch gezähmt werden müssen. Ich werde Euch einen Trick zeigen, wie man für kurze Zeit Besitz von ihnen ergreifen kann, und Ihr werdet sie dafür einsetzen, Chaos und Zerstörung in Jotunheim anzurichten!\n\n<Die Banshee-verseuchte Vrykul entzieht der Luft Magie und berührt Eure Stirn.>\n\nGeht nun und öffnet die Tür zur Schleuse. Ein Wasserschrecken wird hervorkommen und Ihr werdet ihn kontrollieren, um unsere Feinde zu zerstören!", sourceObjective = "Die Knochenhexe in Njorndar möchte, dass Ihr Besitz von einem Wasserschrecken ergreift und ihn dazu benutzt, 10 Vrykul in der Umgebung von Jotunheim zu töten.\n\nIn Frage kommende Vrykul sind Schlafwächter, Krieger von Jotunheim, Wassermagier der Mjordin, Speerschwestern von Njorndar und Varguls von Valhalas.", progress = "Die Knochen verraten mir, dass Ihr noch nicht ganz fertig seid.", completion = "Noch nie habe ich in den Augen eines Vrykuls solches Entsetzen gesehen - und sie halten sich für die Herren ihrer Welt.\n\nWir beide werden beweisen, dass sie falsch liegen... sehr falsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[13092] = { id = 13092, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen lesen", description = "Einer der Vorteile davon, Besitz von dieser Kreatur zu ergreifen, ist, dass ich Zugriff auf all ihre Kräfte habe. Als Knochenhexe und Runenleserin hat sie die Macht, Knochen auszuwerfen und daraus jemandes Schicksal zu lesen.\n\n<Die Knochenhexe schmunzelt.>\n\nGut für Euch, dass es in meiner Macht steht, das Resultat zu beeinflussen.\n\nBringt mir die Knochen von Vrykul, die Ihr hier in Jotunheim tötet, und ich werde sie so werfen, dass Ihr Euer Schicksal bestimmen könnt.", sourceObjective = "Die Knochenhexe in Njorndar hat Euch aufgetragen, 15 Vrykulknochen zu besorgen.", progress = "Ich finde es bemerkenswert, dass diese Wesen jemals die Welt beherrschen konnten, wo sie lediglich über solch primitive Magie verfügten.", completion = "Nun werden wir sehen, was die Zukunft für Euch bereithält.\n\n<Die Knochenhexe wirft die Knochen auf den Teppich vor sich.>\n\nWählt Euer Schicksal, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[13093] = { id = 13093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Knochen lesen", progress = "Bringt noch mehr Vrykulknochen und wir werden dafür sorgen, dass sich das Schicksal zu Euren Gunsten wendet.", completion = "Wählt Euer Schicksal, {name}." }
quests[13094] = { id = 13094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schämen sie sich denn nicht?", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Horde darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, {class}. Bitte beschafft das Buch.", sourceObjective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", progress = "Bitte, {name}, sagt mir, dass Ihr das Buch gefunden habt...", completion = "Ihr habt es gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13095] = { id = 13095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schämen sie sich denn nicht?", description = "Erzmagier Berinand hat mir seine Forschungsergebnisse über das Arkanomikon geliehen - eine Art Karte, die Malygos versucht zusammenzufügen.\n\nIch habe den Fehler begangen, mich mit einer Gruppe Abenteurer der Allianz darüber zu unterhalten, und nun ist es weg!\n\nSie müssen es gewesen sein, {class}. Bitte beschafft das Buch.", sourceObjective = "Abbild von Kriegsmagierin Kaitlyn möchte, dass Ihr Berinands Forschungsergebnisse beschafft.", progress = "Bitte, {name}, sagt mir, dass Ihr das Buch gefunden habt...", completion = "Ihr habt es gefunden?! Ja, ja, alles ist da.\n\nHier, bitte, nehmt dies als Zeichen meines Dankes.", sourceObjectiveStatus = "unverified-source-field" }
quests[13096] = { id = 13096, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gal'darah muss bezahlen", description = "Hast du's gesehen, Mann?\n\nEs muss wohl das Furchtbarste gewesen sein, das ich jemals gesehen hab'. Der große Akali: vor meinen Augen getötet. Schrecklich...\n\nIch habe geschworen, mich nicht in die Sache hier verwickeln zu lassen. Ich soll nur beobachten. Doch das kann so nicht hingenommen werden! Gal'darah muss dafür bezahlen!\n\nGeh nach Gundrak und such ihn auf. Komm zu mir zurück, sobald Akalis Tod gerächt wurde, Mann.", sourceObjective = "Tol'mar in Dubra'Jin möchte, dass Ihr Gal'darah in Gundrak erschlagt.", completion = "Du hast es getan?! Gal'darah gibt es nich' mehr?\n\nHier, Mann, nimm. Ist'n Geschenk dafür, dass du diesem Mistkerl seine gerechte Strafe erteilt hast.", sourceObjectiveStatus = "unverified-source-field" }
quests[13097] = { id = 13097, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Offene Rechnungen", description = "Der Prophet von Akali mag diese Welt zwar nicht mehr belästigen, doch es gibt noch immer Arbeit zu tun.\n\nAkalis Blut - ein Großteil davon - hat jemand anderem Macht verliehen und es ist dieser jemand, von dem die eigentliche Gefahr ausgeht.\n\nSchnell, {name}, macht Euch von Gundrak aus in nördliche Richtung nach Dubra'Jin und sprecht mit Tol'mar. Er wird Euch diesbezüglich weitere Anweisungen geben können.", sourceObjective = "Har'koa möchte, dass Ihr mit Tol'mar in Dubra'jin sprecht.", completion = "Hör zu, Mann. Die Arbeit, die hier erledigt werden muss, is' gefährlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[13098] = { id = 13098, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Für die Nachwelt", description = "Gundrak ist verloren, Mann.\n\nDie Geschichte wird sich vor deinen Augen wiederholen. Wenn Trolle sich gegen ihre eigenen Götter wenden, dann ist's das sichere Ende. Es ist nur eine Frage der Zeit.\n\nWenn wir die Ereignisse bis ins Detail erfassen können, dann würde sich vielleicht verhindern lassen, dass zukünftige Generationen denselben dunklen Weg einschlagen.\n\nWenn du mutig genug bist, dann geh nach Gundrak und such nach Hinweisen darüber, was dazu geführt hat, dass das Reich der Drakkari so enden musste.", sourceObjective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und 6 Geschichtstafeln der Drakkari sammelt.", progress = "Hast du die Geschichtstafeln der Drakkari gefunden, Mann?", completion = "<Bah'Kini überfliegt die Worte auf den Tafeln nur kurz und widmet Euch dann wieder ihre Aufmerksamkeit.>\n\nDie sind echt, {race}. Sie werden ihren angestammten Platz in meiner Sammlung finden.\n\nVielleicht können wir diesem Treiben endlich ein Ende machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13099] = { id = 13099, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur ma' nachsehen", description = "Unten aus Gundrak waren fürchterliche Geräusche zu hören. In letzter Zeit sind sie lauter geworden und auch häufiger zu hören.\n\nMeine langjährige Schülerin konnte von ihrem Posten westlich von Gundrak aus die Ereignisse erfassen. Hättet Ihr vielleicht Zeit, bei Ihr nachzusehen, was los ist?", sourceObjective = "To'kini möchte, dass Ihr mit Bah'kini in Dubra'Jin sprecht.", completion = "Ne langjährige Schülerin? Ha!\n\nWenn'a mit \"langjährig\" n' ganzes Leben meint, dann das stimmt das sicha, eh.\n\nTo'kini is' mein feiga Vater - zu feige, sich füa nen Posten so nah bei Gundrak zu melden... deswegen hatter mich geschickt!", sourceObjectiveStatus = "unverified-source-field" }
quests[13100] = { id = 13100, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieerfüllter Pilzhackbraten", description = "Wir haben eine wichtige Lieferung zu machen! Orton Bennet bei Kuriositäten & Meer braucht einen Pilzhackbraten.\n\nBeschafft also einige energieerfüllte Pilze aus der Kanalisation von Dalaran und ein wenig kühles Fleisch und bereitet sie in Eurer Bratenform zu. Liefert den fertigen Hackbraten bei Orton ab.", sourceObjective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", progress = "Habt Ihr mir irgendwas zu essen mitgebracht?\n\nIch scheine nie von diesem Laden wegzukommen und sei es auch nur für eine Minute.", completion = "Das sieht köstlich aus! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[13101] = { id = 13101, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammlung im Zauberkasten", description = "Arille Azurblick im Zauberkasten hat bald eine Versammlung bei sich und braucht so fix wie möglich ein Festmahl!\n\nIhr müsst einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen namens \"Noch ein Gläschen\" in der Mitte von Dalaran beschaffen. Der Besitzer des Käseladens schuldet mir den Wein - Ihr werdet ihn irgendwo im Laden finden.\n\nBringt die Eintöpfe und den Wein zu Arille.", sourceObjective = "Bringt 4 nordische Eintöpfe, die Ihr selbst gekocht habt, und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", progress = "Wo ist mein Essen? Die Versammlungsmitglieder könnten jeden Augenblick hier sein!", completion = "Das ist genug Essen für alle! Ich bin mir sicher, dass die Kunden zufrieden sein werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13102] = { id = 13102, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanaleintopf", description = "Ajay Grün, der Gastwirt in der Kanalisation von Dalaran, braucht einen Gemüseeintopf für seine Kunden, da ihnen dort unten das Essen ausgeht.\n\nSammelt 4 Kristallsangkarotten aus dem Kristallsangwald, gebt sie gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nDen Kristallsangwald könnt Ihr über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.\n\nBringt den Gemüseeintopf zu Ajay, sobald er fertig gekocht ist.", sourceObjective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den fertigen Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", progress = "Ich hab' hungrige Leute dort unten! Wir brauchen etwas Eintopf.", completion = "Das wird im Nu weg sein! Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[13103] = { id = 13103, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käse für Leuchtegold", description = "Ranid Leuchtegold im Lederladen in Dalaran hatte plötzlich ein heftiges Verlangen nach Wein und Käse.\n\nIm Laden \"Noch ein Gläschen\" in der Mitte von Dalaran gibt es ein Regal mit Käse - holt Euch etwas davon und sammelt dann noch einige halbvolle Weingläser ein, die überall in Dalaran verstreut herumstehen. Danach sollt Ihr den Wein in eine Flasche füllen und diesen dann gemeinsam mit dem Käse Ranid servieren.\n\nWir denken, dass er den Unterschied nicht bemerken wird.", sourceObjective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Aha, das scheint mir ein guter Jahrgang zu sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[13104] = { id = 13104, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal in die Bresche, Held", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", sourceObjective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", completion = "Meine Kenntnisse der Taktiken der Geißel sind ohne Gleichen.\n\n<Der Schwarze Wächter mustert Euch.>\n\nVor der Schlacht um die Kapelle des hoffnungsvollen Lichts dienten meine Ritter und ich dem Lichkönig... sein eisiger Griff kontrollierte jede unserer Handlungen. Das Licht der Morgendämmerung hat alles verändert...", sourceObjectiveStatus = "unverified-source-field" }
quests[13105] = { id = 13105, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noch einmal in die Bresche, Held", description = "Die Vorhut ist gesichert. Wir haben das Tal der Echos zurückerobert und die Netzwälle, die den Zugang zur Bresche blockiert hatten, eingerissen. Jetzt ist die Zeit reif, Geißelholme anzugreifen und unsere Präsenz in Eiskrone zu festigen. Die Kriegsfront bewegt sich weiter!\n\nIch habe den Schwarzen Wächter um seine Hilfe bei unserem Angriff auf Geißelholme gebeten. Seine Kenntnisse der Geißel werden sich als unschätzbar wichtig für unsere Anstrengungen erweisen.\n\nGeht nun und meldet Euch bei ihm am Zelt außerhalb der Bresche, nordwestlich von hier.", sourceObjective = "Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche.", completion = "Eure Macht ist gewachsen, getreuer Ritter.\n\n<Hochlord Darion Mograines Blick ist auf Euch gefallen.>\n\nUnsere Rache wird bald vollzogen, Bruder. Koltira steht der Horde auf der Orgrims Hammer bei, während Thassarian die Allianz auf der Himmelsteiler unterstützt. Die Schwarze Klinge wird schon bald über Eiskrone hinwegfegen und die Armeen des Lichkönigs vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13106] = { id = 13106, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schwarzwacht", description = "Die Geißel verfügt über eine große Einrichtung, genannt die Fleischwerke, die zur Produktion von Monstrositäten und Fleischriesen dient. Wenn wir sie ausschalten könnten, würden wir den Lichkönig eines Gutteils seiner Armee berauben.\n\nIch habe Dunkelreiterin Arly in die Gegend entsandt. Sie hat westlich von Corp'rethar auf einem Höhenrücken eine kleine Basis errichtet, die Schwarzwacht, von wo aus sie die Fleischwerke überblicken kann. Ich habe gehört, dass der Argentumkreuzzug jemanden entsandt hat, um ihre Bemühungen dort zu koordinieren, aber die Dunkelreiterin wird wissen, was zu tun ist.", sourceObjective = "Sprecht mit Dunkelreiterin Arly in der Schwarzwacht in Eiskrone.", completion = "Gut. Wir brauchen jede Hilfe, die wir kriegen können. Olakin hier ist der Beitrag des Argentumkreuzzugs zu unseren Bemühungen. Lassen wir das Gequatsche und machen wir uns an die Arbeit, die Geißel ihrer Krieger aus Fleisch zu berauben.", sourceObjectiveStatus = "unverified-source-field" }
quests[13107] = { id = 13107, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senfwürstchen!", description = "Erzmagier Pentarus sieht sich gelegentlich gerne ein Kampfballspiel an und möchte auch gehen, doch er braucht für die Reise etwas zu essen.\n\nIhr müsst seinen Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Bereichen der Stadt zu finden.\n\nBringt ihm seinen Picknickkorb, damit er bereit für das große Spiel ist.", sourceObjective = "Füllt den leeren Picknickkorb mit 4 Rhinowürstchen, die Ihr selbst gekocht habt, und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", progress = "Bin fast startklar - muss nur noch auf das Essen und... ähm... meine Magierkollegen warten.", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[13108] = { id = 13108, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Koste es, was es wolle!", description = "So oder so, Loken wird sterben.\n\nSelbst wenn ich ihm alle Gliedmaßen einzeln herausreißen muss, wird er schon bald für seine Taten büßen.\n\nSolltet Ihr vor mir auf ihn treffen, so mögen der Ruhm und die Ehre für seine Niederlage Euer sein.\n\nKehrt zu mir mit seiner verlogenen Zunge zurück und erhaltet dafür meinen Dank und Segen.", sourceObjective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Loken besiegt. Danach sollt Ihr mit Lokens Zunge zu König Jokkum zurückkehren.", progress = "Wurde Loken seiner gerechten Strafe zugeführt?", completion = "Dieser niederträchtige Wurm ist tot?\n\nIhr habt Euch für mein Volk als ein wahrer Segen erwiesen, kleiner {race}.\n\nBitte nehmt dieses Geschenk als Dank für Eure loyale Freundschaft an.", sourceObjectiveStatus = "unverified-source-field" }
quests[13109] = { id = 13109, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diametral entgegengesetzt", description = "Ich muss offen zu Euch sein, <kleiner/kleine:r> {race}. Meine Leute sind nicht mehr dieselben, seit unsere Bande mit Thorim gebrochen sind.\n\nAls ihr Anführer wünsche ich mir nichts sehnlicher, als dass ihre Herzen heil werden und unsere Freundschaft mit dem Sturmherren erneuert wird. Mit Eurem Sieg über Fjorn habt ihr einen Schritt auf diesem Weg getan. Ich wünschte, Ihr würdet einen weiteren Schritt wagen...\n\nIn den Hallen der Blitze sitzt jemand, der selbst mächtiger als Fjorn ist und sich an unserer Existenz stört. Volkhan wird nicht eher ruhen, bis entweder er oder wir ausgelöscht sind.", sourceObjective = "König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Volkhan besiegt.", completion = "Volkhans Schrecken wird mein Volk nicht länger bis in den Schlaf verfolgen.\n\nSetzt Eure Bemühungen fort, kleiner {race}. Ich bin mir sicher, dass meine Leute Thorim mit der Zeit vergeben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[13110] = { id = 13110, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die rastlosen Toten", description = "Nicht all unsere Soldaten haben es lebend aus Geißelholme herausgeschafft. Viele wurden getötet und in entartete Reflexionen ihres früheren Selbst verwandelt. Das ist der Weg der Geißel. Für jene armen Verdammten gibt es keinen ewigen Frieden. Wir müssen ihren Seelen Ruhe verschaffen.\n\nReist durch die Bresche nach Geißelholme und tötet die skelettartigen wiedererweckten Kreuzfahrer. Sprenkelt dieses Weihwasser über ihre Gebeine, so dass ihre Seelen befreit werden können.", sourceObjective = "Vater Gustav im Tal der Echos in Eiskrone möchte, dass Ihr die Überreste von wiedererweckten Kreuzfahrern mit Weihwasser benetzt, um 10 ruhelose Seelen zu befreien.", progress = "Es ist eine makabere Aufgabe, {name}, aber sie muss getan werden.", completion = "Der Weg des rechtschaffenen Kreuzfahrers ist von Ungerechtigkeit und Übel gesäumt. Rettung kann es nur geben, wenn man nicht vom Weg abweicht. So, wie Ihr es heute vorgelebt habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13111] = { id = 13111, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Einzigartig", description = "Hör zu, Mann.\n\nAuf den ersten Blick sieht es so aus, als würde es sich hierbei wieder um die alte Leier handeln: Trolle, die verbotene Kräfte anzapfen und genau die Wesen zerstören, die sie eigentlich anbeten sollten.\n\nIn dem Fall stimmt es zwar auch, doch an diesen Drakkari ist etwas Besonderes dran. Wenn das, was ich herausgefunden habe, stimmt, dann gibt es in Gundrak einen ganz besonderen Golem - einen Golem, wie er noch nie zuvor erschaffen wurde!\n\nDu willst ein Abenteuer, Mann? Dann geh nach Gundrak und bring mir ein Stück dieses Golems, damit ich es untersuchen kann.", sourceObjective = "Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und ein Fragment des Kolosses der Drakkari beschafft.", progress = "Hast du mir ein Stück dieses Golems gebracht, Mann?", completion = "Ahh, ja Mann! Das ist es, wonach ich gesucht habe.\n\nHier, bitte schön - nimm dir was Schönes für den Ärger, den du hattest.", sourceObjectiveStatus = "unverified-source-field" }
quests[13112] = { id = 13112, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Energieerfüllter Pilzhackbraten", description = "Orton Bennet bei Kuriositäten & Meer braucht 'nen Pilzhackbraten.\n\nBeschafft also 'n paar energieerfüllte Pilze aus der Kanalisation von Dalaran und etwas kühles Fleisch und bereitet sie in Eurer Bratenform zu. Das Resultat liefert Ihr dann bei Orton ab.\n\nWenn der Rat mir nur erlauben würd', meine Gnomspezialität aufzutischen, ich würd' ihnen schon zeigen, was wirklich lecker ist!", sourceObjective = "Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran.", progress = "Habt Ihr etwas für mich? Ich komme so selten aus meinem Laden raus.", completion = "Hat Awilo das Essen geschickt? Versprecht Ihr mir, dass da keine Gnome drin sind?", sourceObjectiveStatus = "unverified-source-field" }
quests[13113] = { id = 13113, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Versammlung im Zauberkasten", description = "Kannst du dir das vorstellen? Die Horde hat Kannibalismus für illegal erklärt... das ist einfach nicht richtig, sag ich dir! Ich schätze mal, dass ich mich auf meine Arbeit konzentrieren sollte, wenn wir schon eine Bestellung haben.\n\nArille Azurblick im Zauberkasten hat viele Besucher bei sich, Mann. Er braucht einige nordische Eintöpfe und einen Krug Wein aus dem Käseladen in der Mitte von Dalaran.\n\nBring also den Wein und den Eintopf zu Arille.", sourceObjective = "Bringt 4 nordische Eintöpfe und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran.", progress = "Wo ist das Essen? Meine Gäste werden bald hier sein!", completion = "Meine Gäste sollten das passabel finden. Sagt ihnen nur nicht, dass es von Awilo kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13114] = { id = 13114, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kanaleintopf", description = "Wir haben eine neue Bestellung. Der Gastwirt in der Kanalisation von Dalaran braucht einen Gemüseeintopf, weil seine Kunden nich' so viel zu essen haben, Mann.\n\nDer hat deswegen nach einem Gemüseeintopf gefragt, da er meinen letzten Eintopf mit dem Gnom drin nicht so gern gemocht hat. Besorg dir 4 Kristallsangkarotten aus dem Kristallsangwald, koch sie gemeinsam mit 4 Stück kühlem Fleisch und bring das Resultat anschließend zu Ajay.\n\nDu kannst den Wald über die Portalkammer in der östlichen Ecke des Runenweberplatzes erreichen.", sourceObjective = "Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.\n\nBringt den Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran.", progress = "Gebt Acht, dass diesmal kein Gnom im Eintopf ist!", completion = "Eintopf sieht gut aus. Danke für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[13115] = { id = 13115, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Käse für Leuchtegold", description = "Ranid Leuchtegold im Lederladen verlangt es ordentlich nach Wein und Käse. Warum er keinen leckeren Gnom mag, versteh ich nicht.\n\nHol dir den Käse aus dem Käseladen in der Mitte von Dalaran und die halbvollen Weingläser, die auf den Tischen in der Stadt stehen. Geh danach zu Ranid und servier ihm Wein und Käse.\n\nDen Wein könnte man sozusagen als \"Auslese\" bezeichnen, Mann.", sourceObjective = "Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.\n\nBringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier.", progress = "Habt Ihr einen Diener mit meiner Wein- und Käseplatte gesehen? Mich hat der kleine Hunger gepackt!", completion = "Dieser Wein ist ziemlich beeindruckend! Ich muss wissen, woher er kommt.", sourceObjectiveStatus = "unverified-source-field" }
quests[13116] = { id = 13116, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Senfwürstchen!", description = "Erzmagier Pentarus schaut sich gerne sein verrücktes Kampfballspiel an, doch dafür braucht er auch was zu essen.\n\nDu musst seinen Picknickkorb mit 4 gekochten Rhinowürstchen und 4 Zweigen wilden Senfs füllen; letzterer ist in den grasbewachsenen Ecken der Stadt zu finden.\n\nFüll seinen Korb mit den leckeren Senfwürstchen auf, Mann.", sourceObjective = "Füllt den leeren Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.\n\nBringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran.", progress = "Stellt sicher, dass die wilden Senfwürstchen 100% Rhinozeros sind und dass kein Gnom drin ist!", completion = "Perfekt! Ich hoffe nur, dass die Dalaraner Demolierer endlich mal ein Spiel gewinnen werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[13117] = { id = 13117, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wo kommen sie her?", description = "Die unermüdlichen Lakaien des Lichkönigs arbeiten Tag und Nacht an der Erschaffung zahlloser neuer Monstrositäten und Fleischriesen da unten in den Fleischwerken.\n\nAber das war noch nicht alles. Mehr und mehr skelettene Arbeiter tauchen auf und beschleunigen die Arbeit noch zusätzlich.\n\nWenn wir nicht herausfinden, wo sie herkommen und wie sie so schnell arbeiten können, werden wir überrannt, bevor wir die Initiative übernehmen können. Sucht im Südosten und findet die Quelle dieser Skelette!", sourceObjective = "Untersucht einen Beschwörungsaltar im östlichen Teil der Fleischwerke und berichtet dann Dunkelreiterin Arly bei der Schwarzwacht davon.", progress = "Habt Ihr den Ursprung dieser Skelette gefunden?", completion = "<Ihr berichtet der Dunkelreiterin von Euren Entdeckungen beim Beschwörungsaltar.>\n\nSo etwas habe ich vermutet. Das dürfen wir nicht länger zulassen. Unsere oberste Priorität ist es, diese Beschwörungsaltäre zu zerstören, dann erst kümmern wir uns um das Unheil, das die Geißel hier bereits erschaffen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[13118] = { id = 13118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung von Geißelholme", description = "Die Geißel hat ihre Armeen gegen den Argentumkreuzzug gesandt und ist zurückgeschlagen worden. Was sie jetzt macht, nennt sich \"zuschlagen und niederbrennen\". Alle Gefangenen, die sie in Geißelholme gefangen halten, werden hingerichtet und als Diener des Lichkönigs wiederbelebt.\n\nOhne Zweifel wird der Argentumkreuzzug wünschen, dass Ihr seine Soldaten in Ehren verabschiedet. Etwas Derartiges werde ich nicht von Euch verlangen. Um zu siegen, müssen wir die Geißel unterschiedslos ausmerzen.\n\nZieht nach Geißelholme, nordwestlich durch die Bresche, und mäht alle nieder, die sich Euch in den Weg stellen.", sourceObjective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr 3 Hohepriester der Vergessenen Tiefen, 3 Unterkönige der Vergessenen Tiefen und 8 wiedererweckte Kreuzfahrer tötet.", completion = "Das habt Ihr gut gemacht, {name}. Ihre Zahlen gering zu halten wird dem Argentumkreuzzug die Zeit geben, die er braucht, um Fuß fassen zu können.", sourceObjectiveStatus = "unverified-source-field" }
quests[13119] = { id = 13119, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerstört die Altäre", description = "Sie beschwören also ihre Arbeiter und Krieger an diesen Altären?\n\nDie werden als Erstes verschwinden müssen. Der Meisterbeschwörer sollte einen Stab haben, mit dem er das Portal aktivieren kann. Wenn Ihr ihn also tötet und seinen Stab nehmt, dann könnt Ihr mit ihm das Beschwörungsportal überladen und dessen Altar zerstören.\n\nFührt diese Prozedur bei allen vier Altären durch und kehrt zu mir zurück, sobald sie zerstört wurden.", sourceObjective = "Tötet Meisterbeschwörer Zarod und benutzt seinen Beschwörerstab, um den ersten, zweiten, dritten und vierten Beschwörungsaltar zu zerstören. Habt Ihr diese Aufgabe erledigt, kehrt zu Dunkelreiterin Arly bei der Scharzwacht zurück.", completion = "<Dunkelreiterin Arly nickt anerkennend.>\n\nGut. Jetzt können wir unser Augenmerk darauf richten, den Rest der Fleischwerke zu zerstören.", sourceObjectiveStatus = "unverified-source-field" }
quests[13120] = { id = 13120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Todesblick", description = "Die Fleischwerke sind eine gewaltige Operation, und es wird schwer, alles, was sich dort abspielt, im Auge zu behalten. Zum Glück habe ich einen Plan.\n\n<Arly holt eine Kugel aus den Falten ihres Umhangs hervor und zeigt sie Euch.>\n\nDies ist eine Kugel des Todesblicks. Mit ihr können wir die Aktionen der Geißel verfolgen und entscheiden, wie wir am besten zuschlagen.\n\nLegt diese Kugeln auf die Halterungen, die in drei äußerst wichtigen Bereichen zu finden sind: im Monstrositäten- und Fleischriesenlabor gen Südwesten und auch in der Gegend um den riesigen grünen Kessel weit im Westen.", sourceObjective = "Benutzt die Kugel des Todesblicks, um Kugeln in die Kugelhalterung des Monstrositätenlabors, des Fleischriesenlabors und des Kesselbereichs zu legen. Kehrt anschließend zu Dunkelreiterin Arly in die Schwarzwacht zurück.", progress = "Habt Ihr diese Kugeln in ihre Halterung gelegt?", completion = "<Dunkelreiterin Arly schließt ihre Augen und scheint sich auf etwas zu konzentrieren, das weit in der Ferne liegt.>\n\nMit den Augen des Todes selbst beobachte ich unseren Feind. Dieses Wissen wird uns helfen, ihn endgültig zu vernichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13121] = { id = 13121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Durch das Innere Auge", description = "Wir müssen die Werkzeuge des Lichkönigs gegen ihn richten, wenn wir unseren nächsten Schritt in die Wege leiten wollen.\n\nHinter den Bergen im Südwesten liegt die Feste Kul'galar. In ihr halten sich die Orakel von Jotunheim auf, die Befehle von ihrem Meister empfangen und andere durch das Auge des Lichkönigs ausspionieren.\n\nEs ist jenes Auge, zu dem Ihr Euch durchkämpfen müsst. Obwohl man es nicht dazu verwenden kann, den Schleier um die Eiskronenzitadelle zu durchdringen, solltet Ihr dennoch Wertvolles mit seiner Hilfe herausfinden können, so dass wir wissen werden, wie wir am besten weiter vorgehen.", sourceObjective = "Die Knochenhexe in Njorndar hat Euch beauftragt, das Auge des Lichkönigs zu benutzen, um an Informationen zu gelangen.", completion = "Perfekt! Es ist wahr, dass Iskalder angeblich der größte Vrykulkrieger sein soll, der je existiert hat. Und Vardmadra selbst wird herkommen, um ihn zu bewerten!\n\nWir müssen sofort handeln, wenn wir vor ihnen zu diesem alten Helden gelangen wollen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13122] = { id = 13122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Geißelstein", description = "Ein Geißelstein ist ein Gegenstand, der allen Einheiten der Geißel bei Geburt oder Erschaffung übergeben wird. Es verleiht dem Träger gewisse Vorteile, aber was wichtiger ist, gewährt den Anführern der Geißel jederzeit Einblick in den Aufenthaltsort und die Bewegungen all ihrer Einheiten.\n\nMit genügend Geißelsteinen sollte ich in der Lage sein, die Bewegungen anderer Geißeleinheiten in Eiskrone zu überwachen.\n\nSammelt alle Geißelsteine, die Ihr finden könnt, während Ihr Geißelkrieger in Geißelholme tötet. Kehrt zu mir zurück, wenn eure Taschen voll sind.", sourceObjective = "Der Schwarze Wächter im Tal der Echos möchte, dass Ihr ihm 15 Geißelsteine bringt.", progress = "Geißelsteine werden uns dabei helfen, den Gegner aufzuspüren.", completion = "Dann lasst uns doch mal sehen, ob ich uns mit diesen Steinen nicht ein wenig Einblick verschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[13124] = { id = 13124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kampf geht weiter", description = "Malygos und seine Handlanger werden von Tag zu Tag stärker. Jetzt hat man auch noch unsere jüngste Angriffseinheit gefangen genommen und hält sie im Oculus fest.\n\nWir müssen versuchen, sie zu befreien! Belgaristrasz und seine Gefährten sind für uns unerlässlich.", sourceObjective = "Raelorasz möchte, dass Ihr Belgaristrasz und seine Gefährten aus dem Oculus befreit.", completion = "Hört gut zu, {race}.\n\nEure Arbeit hier hat gerade erst begonnen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13125] = { id = 13125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luft steht still", description = "Ihr müsst die Herren von Geißelholme besiegen, wenn dieser Ort vom Würgegriff der Geißel befreit werden soll.\n\nSalranax der Zerfleischer steht dem Tempel auf der ersten Ebene von Geißelholme vor. In der Nähe von Salranax findet Ihr den Hohepriester Yath'amon, der beim Geisterturm auf der zweiten Ebene predigt. Unterkönig Talonox hält bei der Schreckensgrube Hof, die obere Straße hinauf.\n\nSie sind alle herausragende Gegner und sollten mit Bedacht angegangen werden. Benutzt dieses Kriegshorn, wenn Ihr Hilfe brauchen solltet. Die Todesritter von Acherus werden kommen.", sourceObjective = "Der Schwarze Wächter beim Tal der Echos in Eiskrone will, dass Ihr Salranax den Zerfleischer, Unterkönig Talonox und Hohepriester Yath'amon tötet.", progress = "Erledigt sie, {name}!", completion = "Ein hart erkämpfter Sieg, {name}! Die Leutnants werden ausgetauscht, aber zumindest für heute steht die Luft um Geißelholme still.", sourceObjectiveStatus = "unverified-source-field" }
quests[13126] = { id = 13126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vereinte Front", description = "Von jetzt ab werden wir unsere Kräfte vereinen müssen, um weiter voranzukommen.\n\nVaros über uns versteckt sich hinter einem undurchdringlichen Schild. Um zu ihm zu gelangen, müsst Ihr die Zentrifugenkonstrukte zerstören, die diesen Schild mit Energie versorgen.\n\nJeder von uns kann Euch Drachen des jeweiligen Schwarms zur Verfügung stellen. Sie werden Euch helfen, ihn zu enthüllen.", sourceObjective = "Belgaristrasz möchte, dass Ihr 10 Zentrifugenkonstrukte zerstört, um Varos' Schild zu beseitigen. Danach müsst Ihr Varos Wolkenwanderer besiegen.", completion = "Es ist, wie ich es erhofft hatte, {race}. Wir arbeiten gut zusammen.\n\nMöge unsere fortwährende Kooperation genügen, um die vor uns liegenden Aufgaben zu bewältigen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13127] = { id = 13127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Magierlord Urom", description = "Zwischen uns und unserem ultimativen Ziel hier steht nur noch ein Hindernis. Sein Name ist Urom.\n\nEr bewacht den dritten Ring über uns. Nehmt Euch vor seiner mächtigen Zauberei in Acht.\n\nStreckt ihn nieder. Lasst ihn dafür büßen, dass er dem Feind die Treue geschworen hat!", sourceObjective = "Belgaristrasz möchte, dass Ihr Magierlord Urom im Oculus besiegt.", progress = "Habt Ihr Euch um Magierlord Urom gekümmert?", completion = "Der Sieg ist in Reichweite, Freund.\n\nKonzentration, denn jetzt kommt die wahre Prüfung.", sourceObjectiveStatus = "unverified-source-field" }
quests[13128] = { id = 13128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlacht in den Wolken", description = "Die Zeit ist gekommen, Euch Eregos zu stellen.\n\nEr bezieht seine Kraft aus den Energien, mit deren Verteidigung er beauftragt wurde... er trinkt aus dem Brunnen des großen Aspekts Malygos.\n\nJedoch können wir dank des Sieges über den Magierlord nun die volle Kraft unserer Drachen entfesseln. Eregos wird Euch sicherlich unterliegen, wenn Ihr sie weise einsetzt.", sourceObjective = "Belgaristrasz möchte, dass Ihr Eregos im Oculus tötet.", completion = "Ich spüre bereits, wie ihre Abwehr schwächer wird!\n\nDas ist der größte Schlag, den wir dem Herrn der Magie seit Beginn dieses Krieges zufügen konnten.\n\nVergesst nicht, Eregos' Lager aufzusuchen. Einige seiner Schätze könnten von Interesse für Euch sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13129] = { id = 13129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Psychospielchen", description = "<Kurzel reißt einen langen Streifen ihrer Bluse heraus und drückt ihn Euch in die Hand.>\n\nHier, {race}, nehmt. Taucht den Stoff in die Überreste von Novos dem Beschwörer.\n\nWir finden schon noch raus, was die Anführer der Geißel antreibt.", sourceObjective = "Kurzel möchte, dass Ihr den Fetzen von Kurzels Bluse auf die Reste von Novos dem Beschwörer anwendet und anschließend den sekretbefleckten Stoff zu ihr in die Feste Drak'Tharon bringt.", progress = "Habt Ihr das Tuch?", completion = "Hoffentlich finden wir jemanden, der bereit ist, diese Probe zu untersuchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13130] = { id = 13130, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Stein, der eine Revolution auslöste", description = "Wenn Ihr Geißelholme heute betrachtet, mögt Ihr lediglich eine ranzige Grube der Verwesung sehen, aber eines Tages wird es ein Ort voll Pracht und Ehre sein. Hochlord Fordring hat den Namen \"Festung der Gerechtigkeit\" auserkoren.\n\nNun, selbst der Bau einer uneinnehmbaren Festung wie der Eiskronenzitadelle hat mit einem einzelnen Stein begonnen. Und so beginnt unsere Suche nach dem Stein, der eine Revolution auslösen wird.\n\nReist nach Kristallsang, südlich von hier, und sucht das Unbändige Dickicht im Osten. Sobald Ihr dort seid, sammelt kristallines Kernholz vom Boden des Dickichts und elfisches Mauerwerk von den Ruinen von Shandaral.", sourceObjective = "Kreuzzugsarchitekt Silas im Tal der Echos in Eiskrone möchte, dass Ihr 10 Stämme kristallines Kernholz und 10 Stücke altes elfisches Mauerwerk sammelt.", progress = "Habt Ihr Euch verlaufen?", completion = "Kernholz ist von Natur aus resistent gegen Verrottung, Krankheit und Seuche. Dieses Kernholz jedoch schlägt diese Dinge sogar zurück! Auch das Bauwerk, das nun noch den Auswirkungen des unbändigen Dickichts ausgesetzt ist, wird in ähnlicher Weise wirken.\n\nBald schon werden wir einen großen Schritt weiter sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13131] = { id = 13131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schrott in der Truhe", description = "Seh dir das nur an! Meine Truhe war noch nie sou leer.\n\nMeine Jungs machten Luftsprünge, als sie all die Beude sah'n, und nu? Seh sie dir nur mal an! Nichts als Knochengerippe!\n\nWeiter drinnen gibt es mehr als genug Beude und sie ist nicht von der verfluchten Sorte, darauf würd ich wetten!\n\nBring mir die Beude und ich werde dich reich belounen, Kumpel.", sourceObjective = "Brigg im Turm Utgarde möchte, dass Ihr 5 blitzblanke Silberbarren, 3 glänzende Schmuckstücke, 2 goldene Kelche und eine Jadestatue beschafft.", progress = "Wie ging's dir da drin, Kumpel?", completion = "Klasse! Du hast's geschafft, Kumpel.\n\nNu kann ich mein Gesicht dem Käpt'n zeigen, ohne um mein Leben fürcht'n zu müssen - dir und deinen Kameraden sei Dank.\n\nHier ist noch ein wenig Beude als Gegenleistung für dich.", sourceObjectiveStatus = "unverified-source-field" }
quests[13132] = { id = 13132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Rache ist mein!", description = "Glück allein hat mich vor dem Schicksal meiner Kumpel bewahrt. Bei dem Trubel wurde ich umgestoßen - war von Anfang an ein wenig angeheitert gewesen. Also, ich hab dann hochgeguckt und sah, wie sich die ersten von ihnen verwandelten...\n\nDa stand so'n riesen Kerl mit jeder Menge Wachen, der sich das alles ansah. Sie sangen den Namen Ymiron... Wenn Ihr ihn umbringt, werden meine Kumpel vielleicht befreit.", sourceObjective = "Brigg im Turm Utgarde möchte, dass Ihr König Ymiron tötet.", progress = "Hast du denjenigen gefunden, der hier das Sagen hat, {race}?", completion = "Großartig! Vielleicht werden meine Kumpel jetzt in Frieden ruhen können.\n\nHier, Junge. Es soll nich' heißen, dass der alde Brigg nich' großzügig zu denjenigen sei, die ihm einen Gefallen getan haben.\n\nGut, mit dir Geschäfte zu machen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13133] = { id = 13133, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet den Held aus alter Zeit", description = "Rasch, {name}, geht in den Südwesten zu den Hallen der Vorfahren!\n\nDort werdet Ihr auf die schlummernden Mjordin stoßen. Weckt sie, bis Ihr Iskalder gefunden habt. Dann setzt dieses Amulett bei ihm ein und bringt ihn zu mir.\n\nGeht jetzt. Die Zeit ist knapp!", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr mit Iskalder zurückkehrt.", progress = "Wo ist der Held aus alter Zeit?\n\nWir haben keine Zeit zum Plaudern. Geht zu den Hallen der Vorfahren und findet ihn, bevor es zu spät ist!", completion = "Er ist ein schönes Exemplar und wird uns gute Dienste erweisen.\n\nNun müssen wir dafür sorgen, dass wir Vardmadra mit ihm in die Falle locken!", sourceObjectiveStatus = "unverified-source-field" }
quests[13134] = { id = 13134, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst ihr Blut fließen", description = "Die Geißel kann ihre Fleischmonster nicht ohne Blut und Balsamierungsflüssigkeit erschaffen, da die Teile geschützt und funktionsfähig bleiben müssen. Wenn wir ihnen diese Materialien nehmen würden, bräche ihre Armee auseinander und wir könnten ihre Schöpfungen mit Leichtigkeit zerstören.\n\nIn allen Laboren, in denen Fleischriesen und Monstrositäten zusammengeflickt werden, werdet Ihr Bottiche mit Balsamierungsflüssigkeit sowie riesige Kugeln voller Blut finden. Zerstört sie und bringt all jenen, die Euch aufhalten wollen, den Tod!", sourceObjective = "Dunkelreiterin Arly aus der Schwarzwacht möchte, dass Ihr 5 Bottiche mit Balsamierungsflüssigkeit und 5 Blutkugeln zerstört.", completion = "<Ein dunkles, hohles Lachen hallt Euch entgegen, als Ihr zur Dunkelreiterin kommt.>\n\nIhr riecht nach Sieg, {name}, und das sind wahrlich gute Neuigkeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[13135] = { id = 13135, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es könnte uns alle umbringen", description = "Südöstlich von hier, am Ostrand des Kristallsangwaldes, befindet sich ein Gebiet, das man Unbändiges Dickicht nennt. Die verschiedensten Kreaturen leben dort, jedoch alle von ihnen teilen die Eigenschaft der Bindung an magische Energien. Jedes von ihnen enthält reine, kristallisierte Energie, die uns alle töten könnte, wenn sie je instabil würde!\n\nBegebt Euch ins Unbändige Dickicht und tötet seine Bewohner, um die kristallisierte Energie zu erhalten. Wir benötigen Treibstoff, sie müssen sterben - von welcher Seite man es auch betrachtet, für uns ist es von Vorteil.", sourceObjective = "Kreuzzugsingenieur Spitzpatrick aus dem Tal der Echos in Eiskrone möchte, dass Ihr 8 Stücke kristallisierte Energie besorgt.", progress = "Habt Ihr die kristallisierte Energie?", completion = "Ah, das ist perfekt, Der Bomber müsste in null Komma nichts einsatzbereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13136] = { id = 13136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gezackte Splitter", description = "Ihr habt diesen gezackten, dunklen, brüchigen Splitter aus dem Körper eines Ghul gezogen. Die metallische Klinge ist nicht glatt und wurde vermutlich von einer ungeübten Hand geschmiedet oder aus einem größeren Stück herausgebrochen.\n\nIhr erinnert Euch, ähnliche Splitter in den Körper aller Ghule, die Euch in den Fleischwerken begegnet sind, gesehen zu haben, daher fragt Ihr Euch, warum ihre Schöpfer überhaupt Metall verwendet haben. Möglicherweise fällt Kreuzfahrer Olakin Sainrith dazu etwas ein, wenn Ihr ihm die Splitter aus mehreren Ghulen bringt.", sourceObjective = "Bringt Kreuzfahrer Olakin Sainrith in der Schwarzwacht 10 gezackte Splitter.", progress = "Was ist das Widerliches?", completion = "<Olakin begutachtet die Splitter vorsichtig.>\n\nIhr habt so etwas bei allen Ghulen da unten gesehen? In all meinen Kämpfen gegen die Geißel ist mir so etwas noch nie begegnet.", sourceObjectiveStatus = "unverified-source-field" }
quests[13137] = { id = 13137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nicht so ehrenhafter Kampf", description = "Auf dem höchsten Gipfel im Südwesten über Jotunheim liegt die Kriegsnarbenwarte. Dieser Ort ist den Vrykul heilig und hier tragen sie neben Valhalas gern ihre ehrenhaften Kämpfe aus.\n\nWir werden einen nicht so ehrenhaften Kampf dort besuchen.\n\nRuft Eure Gefährten zusammen und fliegt zum Turm. Entzündet das Signalfeuer, wenn Ihr bereit seid, und ich werde in Iskalders Gestalt erscheinen.\n\nWir werden kämpfen, Ihr werdet siegen, und Vardmadra wird gewiss anwesend sein, um sich den Kampf anzusehen!", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr Iskalder auf der Kriegsnarbenwarte besiegt.", completion = "Ich habe Vardmadra vorerst in Sicherheit gebracht, und an diesem Ort wird sie bleiben, bis wir unsere endgültige Rache nehmen!", sourceObjectiveStatus = "unverified-source-field" }
quests[13138] = { id = 13138, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ich schmelze... schmelze!", description = "<Olakin wendet einen der Splitter in seiner gepanzerten Hand.>\n\nMit genug Energie dahinter könnten sie Rüstungen durchdringen. Wir müssen herausfinden, woraus sie bestehen und was der Lichkönig mit ihnen vorhat.\n\nIm Osten in der Nähe der Eiskronenzitadelle liegt Malykriss. Aus den wenigen Berichten, die uns vorliegen, geht hervor, dass es voller Ausrüstung zum Verhütten und Schmieden ist. Bringt die Splitter dorthin und schmelzt sie in einem der offenen Hochöfen auf der untersten Ebene von Malykriss ein. Sobald das Metall eingeschmolzen und verändert ist, können wir es identifizieren.", sourceObjective = "Benutzt die Tasche mit gezackten Splittern in der Nähe eines der Hochöfen auf der untersten Ebene von Malykriss. Kehrt mit dem verhütteten Metallbarren zum Kreuzfahrer Olakin Sainrith bei der Schwarzwacht zurück.", progress = "Habt Ihr diese Fragmente schon eingeschmolzen?", completion = "Es besteht kein Zweifel, dies ist Rohsaronit. Wir haben daraus hergestellte Waffen in den Händen von Günstlingen des Lichkönig gesehen, aber dies ist das erste Mal, dass es für andere Zwecke benutzt wird. Der Umfang dieser Minenarbeiten muss riesig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[13139] = { id = 13139, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Im gefrorenen Herzen Nordends", description = "Silas und Spitzpatrick haben nun genug Material und Treibstoff, um mit dem Bau der Festung der Gerechtigkeit zu beginnen. Ihr und die Schwarze Klinge haben dafür gesorgt, dass die Geißel in Geißelholme dezimiert wurde und ihre Leutnants besiegt sind.\n\nIch habe mich entschieden, wo wir beginnen werden, doch zuerst müsst Ihr Hochlord Tirion Fordring meinen Bericht überbringen. Auf seinen Befehl hin werden wir in Eiskrone einmarschieren.", sourceObjective = "Liefert Vater Gustavs Bericht bei Hochlord Tirion Fordring in der Argentumvorhut in Eiskrone ab.", progress = "Steht bequem, {name}. Was gibt es zu berichten?", completion = "Eure Hilfe bei der Sicherung der Front war ein wesentlicher Bestandteil. Der erste echte Sieg in diesem Krieg ist nahe - daher ist unser nächster Schritt auch von größter Wichtigkeit.\n\nSeid unbesorgt, {name}, die Geißel wird nicht kampflos aufgeben. Eure größte Herausforderung steht Euch noch bevor.", sourceObjectiveStatus = "unverified-source-field" }
quests[13140] = { id = 13140, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Runenschmiede von Malykriss", description = "Die Splitter, die Ihr gefunden habt, können nur von einem Ort stammen: aus Malykriss. Hier, östlich von Corp'rethar, finden alle Metallarbeiten des Lichkönigs statt.\n\nVerwirrend daran ist, dass man kein Metall benötigt, um die Monstrositäten oder Fleischriesen zusammenzuflicken oder um die Skelettdiener zu beschwören. Findet die Skelettrunenschmiede auf der untersten Ebene von Malykriss und nehmt die Platten, die sie bearbeiten, an Euch. Wir müssen herausfinden, warum dieses Metall in den Fleischwerken Verwendung findet.", sourceObjective = "Bringt Kreuzfahrer Olakin in der Schwarzwacht 5 runenverzierte Saronitplattenrüstungen.", progress = "Konntet Ihr diese runenverzierten Platten an Euch bringen?", completion = "Diese Platten sehen fast genauso aus wie die Splitter. Sie müssen die herausgeschnittenen Stücke dafür verwenden, um die hier produzierten Ghule zu verbessern. Die Geißel ist verzweifelt genug, um aus allem eine Waffe herzustellen, wie es scheint. Umso mehr ein Grund, diesen schrecklichen Ort umso schneller zu zerstören!", sourceObjectiveStatus = "unverified-source-field" }
quests[13141] = { id = 13141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um den Kreuzfahrerturm", description = "<Hochlord Fordring hält ein Banner des Argentumkreuzzugs in den Händen.>\n\nDieses Banner ist unvergleichlich, {name}. Es enthält einen mächtigen Segen, der große Teile verseuchten Landes reinigen kann.\n\nIhr müsst es durch die Bresche in den Nordwesten in ein Gebiet bringen, das die Geißel spöttisch Kreuzfahrerturm nennt. Stellt das Banner auf die Schädel unserer am Kreuzfahrerturm gefallenen Brüder und verteidigt es gegen alle Angriffe. Sobald das Land gereinigt ist, kehrt Ihr zu Vater Gustav zurück.\n\nGeht jetzt, {name}, und habt keine Furcht.", sourceObjective = "Begebt Euch zum Kreuzfahrerturm und platziert das gesegnete Banner des Kreuzzugs auf dem Haufen Kreuzfahrerschädel. Verteidigt das Banner gegen den Angriff der Geißel, bis das Land auf dem Turm gereinigt ist. Kehrt dann zu Vater Gustav ins Tal der Echos in Eiskrone zurück.", completion = "Gesegnetes Licht! Wir haben den Turm eingenommen! Endlich können wir mit dem Bau der Festung der Gerechtigkeit beginnen. Hochlord Fordring und die Ritter sind bereits zu unserer neuen Basis aufgebrochen. Ihr müsst Euch dort mit ihnen treffen, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[13142] = { id = 13142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache der Banshee", description = "Die Zeit ist gekommen, {name}. Ihr müsst mit Euren Freunden den Fürsten der Festung Balargarde, den Meister von Jotunheim, Oberthan Balargarde, herausfordern.\n\nAm höchsten Punkt der Festung, die sich am Südwestrand von Jotunheim befindet, werdet Ihr auf ein Horn stoßen. Blast hinein und lasst all jene, die unerschütterlich genug sind, Eure Herausforderung hören.\n\nBalargarde wird keine andere Wahl haben, als sich Euch zu stellen. Und ich... Verzeihung, Vardmadra wird dort sein, um das Urteil zu fällen.\n\n<Die von einer Banshee besessene Vrykul stößt ein bellendes Lachen aus.>", sourceObjective = "Die Knochenhexe aus Njorndar möchte, dass Ihr für sie Rache nehmt, indem Ihr Oberthan Balargarde herausfordert und besiegt.", completion = "Was ich im Moment fühle, lässt sich nicht in Worte fassen, {name}. Meine Rache ist vollzogen, und es gibt hier für mich nichts mehr zu tun.\n\nKönnte ich doch hier sein, wenn der Lichkönig endlich gestürzt wird.\n\nAber lasst Euch nicht täuschen, denn Jotunheim ist noch lange nicht 'erledigt'. Ich werde diese Hexe weiterhin unter Kontrolle behalten, bis die Vrykul keine Bedrohung mehr darstellen.\n\nSeht Euch um, in dieser Höhle könnt Ihr viele wertvolle Dinge sehen. Sucht Euch etwas aus.", sourceObjectiveStatus = "unverified-source-field" }
quests[13143] = { id = 13143, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Neuer Rekrut", description = "Eins nach dem anderen. Ich habe ein paar geschmeidige Pirscher auf den Bollwerken östlich von hier gesehen. Sie hatten uns gedient, bevor wir uns von Arthas losrissen. Außerdem sind sie so ziemlich die besten Kundschafter, die es gibt, wenn man sie mit dem Auge der Herrschaft nur ein wenig antreibt.\n\nFliegt dorthin, findet einen der Pirscher, setzt ihm ein wenig zu, wendet dann dieses Siegel der Schwarzen Klinge auf ihn an und er wird Euch gehorchen. Führt ihn anschließend zur Spitze der Felsen nordöstlich von hier und er wird seinen Weg zu mir finden.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr einen unterworfenen geschmeidigen Pirscher zur Spitze der Felsen nordöstlich der Anhöhe des Leidens bringt.", progress = "Ich bin mir sicher, dass ihre neuen Meister nicht zimperlich mit ihnen umgehen werden; doch sie werden die Striemen, die wir ihnen beibrachten, auf jeden Fall nicht vergessen. Sie werden diese Siegel fürchten, solange sie leben.", completion = "Ich habe den armen Teufel an den Pfosten dort drüben gekettet und werde mir noch mehr von ihnen schnappen.\n\nNa, dann lasst uns doch das Auge mal ein wenig benutzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[13144] = { id = 13144, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwei Geißeln mit einem Skelett schlagen", description = "Einige ihrer Kreationen haben die Arbeiter in den Fleischwerken bereits fertiggestellt. Im Moment sind die Kreaturen noch an die Säulen rund um die Kante des Labors gekettet, aber wenn wir nicht schnell etwas unternehmen werden sie mit den Armeen des Lichkönigs marschieren.\n\nAus den auf dem Boden der Fleischwerke verteilten Knochenhaufen ragen gierig greifende Arme heraus. Diese Arme gehören zu Skeletten, die mit der Macht des Feuers belegt sind. Findet und befreit diese Skelette, bringt sie in die Nähe der fertigen Monstrositäten und genießt die Vorstellung!", sourceObjective = "Dunkelreiterin Arly an der Schwarzwacht möchte, dass Ihr 3 angekettete Monstrositäten mit brennenden Skeletten zerstört.", completion = "Ah, gut. Es geht doch nichts über den Geruch von verbranntem fauligen Fleisch am Morgen. Der Geruch ist ein Sieg über die Geißel.", sourceObjectiveStatus = "unverified-source-field" }
quests[13145] = { id = 13145, flavor = "source-reference", locale = "deDE", source = "MultiLanguage mop-classic a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceFlavor = "mop-classic", sourceRevision = "a9e7ba2d7b8654481abbd70f7190b341346c68eb", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Unheilvolle Festung", description = "Wir müssen wissen, mit was wir es zu tun haben.\n\nBringt mithilfe des Auges der Herrschaft einen geschmeidigen Pirscher unter Eure Kontrolle und erkundet die Gegend. Als ich hierher geflogen bin, habe ich ein paar Stellen gesehen, die Ihr für mich genauer untersuchen sollt: die Warte im Nordosten, das Gebiet der Arbeiter im Südosten, die große Schmiede in der Nähe des Zentrums und den Ritualbereich im Südwesten.\n\nDer Pirscher kann weit springen und Stürze aus größerer Höhe machen ihm nichts aus. Nutzt dies zu Eurem Vorteil und die Bollwerke werden kein Hindernis mehr darstellen.", sourceObjective = "Vereth der Gewiefte auf der Anhöhe des Leidens wünscht, dass Ihr mithilfe eines geschmeidigen Pirschers Malykriss erkundet.", progress = "Fliegen mag zwar etwas eleganter sein, aber wir hätten ohne den Pirscher nie so nah herankommen können, ohne dabei gesehen zu werden.", completion = "Ausgezeichnete Arbeit. Es scheint, dass mehr Todesritter Arthas treu geblieben sind, als ich zuerst dachte.\n\nEr versucht Acherus mit allen Mitteln zu ersetzen, so viel steht fest. Eine Zitadelle komplett aus Saronit wäre mit Sicherheit nicht leicht zu zerstören. Doch das müssen wir gar nicht... Wir können dem Treiben hier und jetzt ein Ende bereiten und die Anführer der Todesritter aus dem Weg schaffen, bevor sie eine wirkliche Bedrohung darstellen.\n\nUnd was am allerwichtigsten ist: Wir müssen für genug Tumult sorgen, um diese Todesritter von ihren Anführern zu trennen, damit wir zuschlagen können.", sourceObjectiveStatus = "unverified-source-field" }
